-- ============================================================================
-- Question bank import: 400 items from the four 2026 DECA district sample exams
-- (Marketing 1322, Hospitality & Tourism 1323, Finance 1324, Business Management
-- and Administration 1325), published by DECA Inc. / MBA Research.
--
-- Parsed straight from the exam PDFs: stem, four choices, the answer key's letter,
-- and the key's rationale (stored as `explanation`). Each item also carries the
-- performance indicator from the key's SOURCE line -- `pi_code` (e.g. CO:031) and
-- `pi_text` -- and the PI's two-letter prefix is what drives `kpi_area`, so the
-- grouping is the exam's own instructional-area taxonomy rather than a guess.
--
-- `difficulty_rating` starts at the 1500 default for every item; the Elo loop in
-- lib/algorithms/diagnosticElo.ts calibrates it from real answers over time.
--
-- Re-runnable: the insert skips any stem already in the bank.
-- ============================================================================

alter table public.questions
  add column if not exists pi_code     text,
  add column if not exists pi_text     text,
  add column if not exists source_exam text;

comment on column public.questions.pi_code is
  'MBA Research performance-indicator code from the exam key, e.g. CO:031. Prefix determines kpi_area.';

create index if not exists idx_questions_pi_code on public.questions(pi_code) where active;

-- Keep the answer key and rationale out of the client-safe view (unchanged from 0001);
-- pi_text is deliberately NOT exposed pre-grading, since an indicator like
-- "Write persuasive messages" would telegraph the answer.

insert into public.questions
  (question_text, choices, correct_index, explanation, kpi_area, cluster, difficulty_rating, pi_code, pi_text, source_exam)
select v.* from (values
  ('When writing a persuasive business message, you should remember to', array['communicate your personal goals.','open the message with a meaningful quote.','place the least important information at the beginning.','describe the benefits to the audience.'], 3::smallint, 'Describe the benefits to the audience. The primary goal of a persuasive message is to influence behavior. Influencing others involves communicating benefits of taking action. The readers are more likely to respond favorably to the message if they know how the action will impact or help them. Communicating benefits is a central element to all types of persuasive messages. The beginning of the message should catch the readers'' attention and encourage them to read more. Depending on the type of message, this might involve a quote. The message should be concise, so it should not contain unimportant information. The message should be written to communicate the business''s goals rather than personal ones.', 'Communication Skills', 'Marketing', 1500, 'CO:031', 'Write persuasive messages', 'Marketing District 2026 #1'),
  ('Which of the following is an example of a legal issue associated with information management:', array['Quality assurance','Customer privacy','Employee training','Company reputation'], 1::smallint, 'Customer privacy. Most governments have regulations regarding the privacy rights of customers. For example, a law may state that companies may not give out the personal information of customers unless they receive permission. This is an example of a legal issue associated with information management. Company reputation, quality assurance, and employee training are not necessarily legal issues related to information management.', 'Information Management', 'Marketing', 1500, 'NF:076', 'Explain legal issues associated with information management', 'Marketing District 2026 #2'),
  ('Allowing customers to voluntarily provide their own information in customer relationship management programs is beneficial in which of the following ways:', array['It enables the sales department to prioritize sales leads.','It enables customers to offer suggestions for new services.','It enables the marketing department to tailor ads to those customers.','It enables customers to feel that the business is in control of their information.'], 1::smallint, 'It enables customers to offer suggestions for new services. Businesses benefit from feedback and new ideas when customers voluntarily offer suggestions for new services. Allowing customers to voluntarily provide their own information does not directly benefit the sales or marketing departments. Customers voluntarily providing their own information allows the customers to feel they are the ones in control of their information, not the business.', 'Customer Relations', 'Marketing', 1500, 'CR:016', 'Discuss the nature of customer relationship management', 'Marketing District 2026 #3'),
  ('Which of the following areas of management and administration is often referred to as "support staff":', array['Human resource management','Business information management','General management','Administrative services'], 3::smallint, 'Administrative services. Employees working in administrative services facilitate business operations through a variety of administrative and clerical duties, including information and communication management, data processing and collection, and project tracking. These positions are often referred to as support staff positions. Business information technology employees help to align business and IT goals. Careers in general management focus on planning, organizing, directing, and evaluating part or all of a business organization through the allocation and use of financial, human, and material resources. Human resource management careers focus on the staffing activities that involve planning, recruitment, selection, orientation, training, performance appraisa l, compensation, and safety of employees.', 'Professional Development', 'Marketing', 1500, 'PD:025', 'Explain employment opportunities in business', 'Marketing District 2026 #4'),
  ('How can a consumer typically determine the best interest rates for personal savings accounts and personal loans?', array['Contact a brokerage firm to get advice.','Evaluate commercial banks'' requirements and rates.','Evaluate rates offered by uninsured online banks.','Evaluate credit union requirements and rates.'], 3::smallint, 'Evaluate credit union requirements and rates. Credit unions typically provide the highest interest rates on savings accounts and the lowest interest rates on loans. Commercial banks typically do not offer consumers the beneficial interest rates that credit unions can provide. Uninsured online banks sometimes offer better rates, but they also carry more risk. Brokerage firms buy and sell different types of securities and do not typically provide information about interest rates offered by banking institutions.', 'Financial Analysis', 'Marketing', 1500, 'FI:075', 'Describe types of financial-services providers', 'Marketing District 2026 #5'),
  ('Is it ever appropriate for an individual looking for a job to send a cover letter to a business that has not advertised a job opening?', array['No; the business will discard the letter if it has no openings.','Yes; the worker should write to each business in the industry.','Yes; the worker can write if they have heard about a job opening.','No; a letter is used only in response to job advertisements.'], 2::smallint, 'Yes; the worker can write if they have heard about a job opening. In some cases, a worker looking for a job will hear about a job opening from a source other than a job advertisement. It is acceptable for the worker to write a letter stating that they have heard of an opening and ask to be considered for the position. In some cases, this results in an interview and a job. Most companies do not discard such letters but keep them on file in case of future need. It would not be appropriate or practical to send letters to all businesses in the industry.', 'Professional Development', 'Marketing', 1500, 'PD:030', 'Write a cover letter', 'Marketing District 2026 #6'),
  ('When you are able to respect and appreciate other people''s unique viewpoints, you can', array['have constructive dialogue with others.','take on more responsibility at work.','work more efficiently at your job.','expect people to take advantage of you.'], 0::smallint, 'Have constructive dialogue with others. An important component of effective communication is respect. When you are able to respect and appreciate other people''s unique viewpoints, you can have constructive dialogue with people of all backgrounds. Being able to respect and appreciate other people''s unique viewpoints does not necessarily allow you to take on more responsibility at work; however, the ability to handle diverse viewpoints is a valuable skill that can make you an attractive job applicant. Your ability to work efficiently is not related to your ability to appreciate other viewpoints. People will not take advantage of you when you respect and appreciate their opinions. Rather, they will most likely return the favor and respect and appreciate your own opinions.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:136', 'Consider conflicting viewpoints', 'Marketing District 2026 #7'),
  ('The human resources manager sends an email to all employees stating that they will need to park on the street on Tuesday because the maintenance department will be repairing the company''s parking lot. This is an example of a(n)', array['formal inquiry.','projection report.','informational message.','business proposal.'], 2::smallint, 'Informational message. Communicating information involves providing others with facts. In the example, the human resources manager is informing the company''s employees about an issue with the company''s parking lot. The human resources manager is not writing a projection report, business proposal, or formal inquiry.', 'Communication Skills', 'Marketing', 1500, 'CO:039', 'Write informational messages', 'Marketing District 2026 #8'),
  ('When using an online search engine to obtain business information, employees should enter __________ in the search engine''s __________ field.', array['keywords; query','ordinary slang; subject','vague terms; reply','general phrases; answer'], 0::smallint, 'Keywords, query. A search engine is a software program that automatically crawls the web looking for information pertaining to specified search terms and then displays a list of results. To conduct an online search, the employee enters specific or keywords (terms, phrases, slang) that pertain to the topic of interest into the query field and clicks on the search button. The search will provide results that include the keywords in the description. The words entered into the query field should be specific enough to generate desired results. For example, entering the term, "Washington," will likely generate responses about the U.S. state, the U.S. capitol, and the first U.S. president. If the researcher wanted information about manufacturers in Washington state , entering the words "Washington state manufacturers" into the query field would more likely provide the desired results; therefore, the more specific the keywords, the more applicable the results. The field in which a person enters keywords is not called a reply, answer, or subject field. Slang may or may not be a keyword.', 'Information Management', 'Marketing', 1500, 'NF:006', 'Demonstrate basic web-search skills', 'Marketing District 2026 #9'),
  ('What requirement of a legally enforceable contract requires that both of the parties who are entering into the contract are sane, sober, and of legal age?', array['Capacity','Genuineness of assent','Consideration','Legality of purpose'], 0::smallint, 'Capacity. Certain conditions must be met for a contract to be legally enforceable. Capacity involves having the mental and cognitive ability to make and understand the agreement and the consequences of their actions. If one party is a child or is found to be mentally challenged or impaired, the contract is invalid and unenforceable. Consideration means that the agreement must include something of value that both parties bargain for. Genuineness of assent means that all parties know what they are agreeing to. Legality of purpose means that the agreement must not violate any laws.', 'Business Law', 'Marketing', 1500, 'BL:002', 'Describe the nature of legally binding contracts', 'Marketing District 2026 #10'),
  ('A business that produces products for which there is a steady, predictable demand for large quantities is most likely to use which of the following production processes:', array['Batch','Unit','Intermittent','Continuous'], 3::smallint, 'Continuous. A continuous production process is one that turns out products without stopping. The process is used by businesses that make such products as soft drinks that are in steady demand by consumers and can be held in stock as necessary. An intermittent production system is shut down from time to time for various reasons, such as a decline in demand or an oversupply of stock. A batch production process produces specific quantities of a product as needed (e.g., restaurant entrees). A unit production process focuses on producing one or a few products at a time.', 'Operations', 'Marketing', 1500, 'OP:017', 'Explain the concept of production', 'Marketing District 2026 #11'),
  ('Annie recently started a new business. When selecting employees, she chose the applicants she knew personally rather than the individuals she had never met before. This is an example of', array['objectivity.','nepotism.','puffery.','fairness.'], 1::smallint, 'Nepotism. Nepotism is the practice of using one''s power or influence to benefit one''s friends or relatives. Choosing your friends and family members for a job, like Annie did, is an example of nepotism in action. This is not an example of fairness or objectivity; rather, it is an example of unfairness and subjectivity. Puffery involves making an unsubstantiated claim for personal gain, such as overstating a business''s year -one profits to attract potential investors. Puffery is not demonstrated in this example.', 'Entrepreneurship', 'Marketing', 1500, 'EN:044', 'Describe the use of business ethics in entrepreneurship', 'Marketing District 2026 #12'),
  ('A restaurant has guidelines outlining how frequently employees should wash their hands and how often they should wipe down tables. These guidelines are examples of', array['policies.','protocols.','precedents.','procedures.'], 0::smallint, 'Policies. A policy is any guideline explaining how employees are to act. For example, a restaurant may have a strict policy regarding employee hygiene. The policy might outline how frequently employees should wash their hands and how often they should wipe down tables. A procedure, on the other hand, is a step-by-step process that employees must follow while performing a specific task. "Protocol" is often used to describe an organization''s overall set of guidelines rather than a specific rule. A precedent is an earlier event used as an example for subsequent action.', 'Professional Development', 'Marketing', 1500, 'PD:250', 'Adhere to company protocols and policies', 'Marketing District 2026 #13'),
  ('Before leaving for the night, employees of Double Scoop Ice Cream Shop are required to clean the counters, sweep the floor, and move leftover ice cream to overnight freezers. This closing process is an example of a(n)', array['procedure.','policy.','agreement.','contract.'], 0::smallint, 'Procedure. A procedure is a step-by-step process that personnel must follow in performing a specific task. Procedures and policies are similar but not the same. Procedures outline step -by-step processes, while policies are more general. A policy is any guideline that explains how employees are to act. The closing process of Double Scoop Ice Cream Shop is an example of a procedure, not a policy, contract, or agreement.', 'Communication Skills', 'Marketing', 1500, 'CO:057', 'Analyze company resources to ascertain policies and procedures', 'Marketing District 2026 #14'),
  ('Which of the following statements is true of diversity:', array['Diversity applies only to minorities.','In group settings, diversity increases creativity and innovation.','Diversity in the workplace is decreasing.','Valuing diversity means ignoring or minimizing differences.'], 1::smallint, 'In group settings, diversity increases creativity and innovation. Diversity brings different views, experiences, and strengths to the table. This is invaluable in a group setting. Think of it this way: If you fill a brainstorming session with people who are exactly like you, you won''t get any new ideas. However, if you find people who have different backgrounds and experiences, they will likely have solutions you might not have thought of. Diversity doesn''t just apply to minorities, and it doesn''t refer only to race or ethnicity. Diversity includes everyone, which is why it''s so important to learn to value diversity. Although some people think that valuing diversity means ignoring or minimizing differences, that''s not the case. Instead, we should openly ackn owledge differences and see them as assets, not problems. Diversity in the workplace is actually greatly increasing. A few decades ago, the workforce consisted predominantly of white men. Today, white men make up a much smaller portion of the workforce in the United States than before. That''s why employees who value diversity are in high demand, and companies without them will find it difficult to succeed.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:033', 'Exhibit cultural sensitivity', 'Marketing District 2026 #15'),
  ('A primary reason that governments regulate the ways in which businesses must report financial data is to', array['reduce taxes.','stimulate market growth.','ensure transparency.','eliminate mistakes.'], 2::smallint, 'Ensure transparency. Governments require businesses to provide certain types of financial information to regulatory agencies and shareholders. The accounting function collects and records the financial information in the appropriate format. Transparency involves fully disclosing the required information so it is understandable to the intended audience. Governments do not regulate the ways in which businesses report financial data to reduce taxes or stimulate market growth. The consequences of incorrect info rmation (e.g., fines) may reduce the risk of mistakes on the report, but the risk of mistakes cannot be eliminated.', 'Financial Analysis', 'Marketing', 1500, 'FI:353', 'Explain legal considerations for accounting', 'Marketing District 2026 #16'),
  ('Iliana is running a charity raffle for her church, and she determines that she needs a roll of 200 tickets. What should she do next?', array['See if the church already has tickets available.','Buy the roll of tickets online.','Come up with an alternative to using tickets.','Estimate the costs of the raffle.'], 0::smallint, 'See if the church already has tickets available. After determining the specifications of the tangible resources she needs, Iliana should then determine what resources she already has. She should not buy the tickets online or come up with an alternative to using tickets before checking to see if the church already has the tickets available. Finally, estimating the costs of the raffle is not the next step to take after determining the specifications of needed tangible resources.', 'Operations', 'Marketing', 1500, 'OP:003', 'Identify resources needed for project', 'Marketing District 2026 #17'),
  ('Which of the following activities consumes most of a retail buyer''s time:', array['Promotion','Merchandise pricing','Merchandise selection','Sales force management'], 2::smallint, 'Merchandise selection. Selection of merchandise includes identifying merchandise with the greatest potential for resale, deciding what items to buy, calculating the appropriate quantities, choosing vendors, and determining when to buy. Managing the sales force, pricing goods, and planning promotions may also be part of the buyer''s responsibility, but selecting merchandise is the buyer''s primary task.', 'Operations', 'Marketing', 1500, 'OP:015', 'Explain the nature and scope of purchasing', 'Marketing District 2026 #18'),
  ('Which approach to fairness includes treating others how they deserve to be treated according to an ethical understanding of what is right?', array['Empathy','Equality','Consistency','Justice'], 3::smallint, 'Justice. In the context of fairness, justice means treating others how they deserve to be treated according to an ethical understanding of what is right. When you act with justice in mind, you are taking people''s unique needs into account when determining what is fair for that individual. The equality approach to fairness means treating people consistently regardless of their individual characteristics, traits, and circumstances. Empathy is understanding and identifying with the thoughts, feelings, values, attitudes, and/or actions of another person. Consistency is the state of being unchanging.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:127', 'Demonstrate fairness', 'Marketing District 2026 #19'),
  ('When developing a presentation, it is important that each slide contain', array['colorful graphics.','numerical data.','creative transitions.','key points.'], 3::smallint, 'Key points. Employees use presentation software to develop visual aids that support an oral presentation. Slides for the presentation should include key points that highlight or reinforce the most important information, which may or may not include numerical data. Colorful graphics and creative transitions often make a presentation more interesting, but they are not necessary elements for each slide.', 'Information Management', 'Marketing', 1500, 'NF:008', 'Demonstrate basic presentation applications', 'Marketing District 2026 #20'),
  ('Luke is writing a complex report that will be submitted to the company''s board of directors. He has collected relevant information that he would like to provide to the audience—information that is not necessary to include in the body of the report. In what section of the report should Luke include this supplemental information?', array['Appendix','Table of contents','Executive summary','Bibliography'], 0::smallint, 'Appendix. Supplemental information for long or complex reports is presented in an appendix, which is a separate section placed at the end of a report. The information in the appendix might contain graphs, text, or a combination of both elements. A bibliography is a component of a report that summarizes the information sources that the writer used to prepare the report. An executive summary is an overview of the entire report. The table of contents is the portion of a long report in which the sections are listed with their page numbers.', 'Communication Skills', 'Marketing', 1500, 'CO:088', 'Select and utilize appropriate formats for professional writing', 'Marketing District 2026 #21'),
  ('Which of the following statements best describes the difference between an occupation and a career:', array['Your occupation is your lifelong work journey, whereas your career is a short-term job.','Occupation is a broad term that describes the field you work in, whereas your career is your lifelong work journey.','Occupations generally bring you a sense of satisfaction or accomplishment, whereas careers are generally just for a paycheck.','An occupation is a short-term work endeavor, whereas a career is a long-term work endeavor.'], 1::smallint, 'Occupation is a broad term that describes the field you work in, whereas your career is your lifelong work journey. An occupation is a category of work, such as "educator." Within an occupation, there may be several different types of jobs, such as teacher, principal, guidance counselor, or reading specialist. Someone with an occupation of "educator" may have a career that includes several of those job titles. Careers often span an entire lifetime and are comprised of an individual''s various jobs over time. Occupations and careers are generally long- term, whereas individual jobs may be short-term. Your occupation and your career may both bring you great satisfaction and accomplishment.', 'Professional Development', 'Marketing', 1500, 'PD:034', 'Explain possible advancement patterns for jobs', 'Marketing District 2026 #22'),
  ('Fellow employees come back from lunch late consistently, forcing you to cover their responsibilities. Which of the following is an example of using assertiveness to handle this problem:', array['Reporting the problem to a supervisor','Applying for a different job','Ignoring the problem','Confronting the coworkers about the problem'], 3::smallint, 'Confronting the coworkers about the problem. Assertiveness is the ability to express yourself; communicate your point of view; and stand up for your rights, principles, and beliefs. Confronting the coworkers about the extra work you are doing for them and the fact that they are taking advantage of you and the company is healthy, assertive behavior. Reporting the problem, ignoring the issue, or changing jobs avoids a confrontation but does not solve the problem.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:018', 'Identify desirable personality traits important to business', 'Marketing District 2026 #23'),
  ('One reason why creditors review a business''s income statement is to decide if the business will be able to', array['develop new products.','repay a loan.','increase staff.','expand operations.'], 1::smallint, 'Repay a loan. Creditors are responsible for deciding whether a business should be given a loan. The income statement helps creditors assess the business''s creditworthiness and the risk of extending credit to the business. It provides the evidence needed to prove that the business can pay back the loan. Expanding operations, developing new products, and increasing staff are some of the reasons why a business might apply for a loan and need to provide creditors with its income statement.', 'Financial Analysis', 'Marketing', 1500, 'FI:094', 'Describe the nature of income statements', 'Marketing District 2026 #24'),
  ('Companies that implement a clear chain of command often experience a __________ workflow with less', array['smoother; communication.','more flexible; redundancy.','smoother; redundancy.','more flexible; communication.'], 2::smallint, 'Smoother; redundancy. Organizations with effective chains of command see a smoother workflow and tend to have fewer workflow problems such as redundancy and confusion. A strong chain of command can improve overall communication among employees, not lessen it—the chain of command ensures that communication within a company is methodical, orderly, and efficient. A chain of command does not make workflow more flexible because it implements a hierarchy that should be followed.', 'Professional Development', 'Marketing', 1500, 'PD:252', 'Follow chain of command', 'Marketing District 2026 #25'),
  ('One way that businesses can reduce the risk of credit card fraud at the point of sale is by', array['establishing credit limits for card usage.','verifying the cardholder''s identification.','reviewing sales receipts during closing procedures.','conducting a financial audit.'], 1::smallint, 'Verifying the cardholder''s identification. During a sales transaction, employees should ask customers to present another form of identification when they pay for items with a credit or debit card. By comparing the signature on the credit card that the customer presents with the signature or photo of another form of identification (e.g., driver''s license), employees can verify that the customer is the authorized cardholder. Credit card issuers establish the credit limits for credit card holders. Reviewing sales receipts during closing procedures, conducting a financial audit, and establishing credit limits for card usage are not ways to reduce risks associated with credit card fraud at the point of sale.', 'Operations', 'Marketing', 1500, 'OP:013', 'Explain routine security precautions', 'Marketing District 2026 #26'),
  ('The migration of people from one location to another that affects the types of products that businesses sell is an example of a', array['population trend.','social lifestyle.','geography issue.','transportation route.'], 0::smallint, 'Population trend. Migration is a population trend that indicates the movement of people throughout the country as well as into and out of the country. Migration trends are important to businesses because businesses need to know where their customers are located. For example, many people are leaving colder climates and migrating to what is considered the Sunbelt. This movement affects businesses because the types of products they sell and the way they sell them will change. Also, the increased migration of ethnic groups into the country creates a need for new goods and services that meet the needs of a multicultural population. The migration of people from one location to another is not a geography issue, a transportation route, or a social lifestyle.', 'Information Management', 'Marketing', 1500, 'NF:013', 'Describe current business trends', 'Marketing District 2026 #27'),
  ('A business''s ethics determine whether an action is acceptable for that business, especially if the action', array['contributes to the business''s profitability.','has a negative impact on others.','is illegal.','affects the environment.'], 1::smallint, 'Has a negative impact on others. A business''s ethics determine whether an action is acceptable for that business, especially if the action has a negative impact on others—employees, customers, community members, etc. Sometimes, a business''s ethics influence its decision on an environmental issue, but the environment is not a more important factor in ethics than any other issue. Anything illegal should be unacceptable for a business, regardless of its ethics. Sometimes, unethical practices may contribute to a business''s profitability, but this is not necessarily a more important factor than others in determining a business''s actions.', 'Economics', 'Marketing', 1500, 'EC:106', 'Explain the nature of business ethics', 'Marketing District 2026 #28'),
  ('What is the most important piece of information that a cash flow statement provides?', array['Amount of money expected','Beginning of tax year','Cost of maintenance','Statistics from industry'], 0::smallint, 'Amount of money expected. How much money will flow into and out of a business is typically the most important piece of information that a cash flow statement provides. Businesses need to know whether they will have enough cash coming in to meet monthly obligations. For example, if businesses discover that they will not collect enough money, they can plan a sale to generate more income or tighten their credit policies. Predicting the cost of maintenance is only a small part of estimating expenses in a cash flow statement. Businesses decide when their tax year will begin. Many businesses use industry statistics when developing their cash flow statements.', 'Financial Analysis', 'Marketing', 1500, 'FI:091', 'Describe the nature of cash flow statements', 'Marketing District 2026 #29'),
  ('As a team leader, taking responsibility for your team''s success or failure in achieving the vision is part of', array['being an example.','being a good listener.','establishing good working relationships.','being enthusiastic.'], 0::smallint, 'Being an example. Taking responsibility for your team''s success or failure as it works toward the vision is being an example and a sure sign of solid leadership. This responsibility does not necessarily relate to establishing good working relationships, being enthusiastic, or being a good listener.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:060', 'Enlist others in working toward a shared vision', 'Marketing District 2026 #30'),
  ('Making required textbooks available at a campus bookstore is an example of creating __________ utility.', array['time','form','place','possession'], 2::smallint, 'Place. Place utility is usefulness created by making sure that products are available at the place where they are wanted or needed by consumers. Textbooks are needed on campus and will be sold there to students and faculty. Time utility is usefulness created when products are made available at the time they are needed or wanted by consumers. Form utility is usefulness created by altering or changing the form or shape of a good to make it more useful to the consumer. Possession utility is usefulness created when ownership of a product is transferred from the seller to the user.', 'Economics', 'Marketing', 1500, 'EC:004', 'Determine economic utilities created by business activities', 'Marketing District 2026 #31'),
  ('A country can often produce goods more cheaply than other nations because it', array['places limits on its imports.','has easy access to raw materials.','possesses a very high standard of living.','is not subject to tariffs and quotas.'], 1::smallint, 'Has easy access to raw materials. Because countries have different resources, they trade with one another to get what they want and need. Countries can often produce goods more cheaply than other countries because they have easy access to raw materials, up-to-date technology, or workers with special skills. Countries are more efficient when they produce products for which their resources are best suited. Placing limits on imports, lack of tariffs and quotas, and a very high standard of living do not necessarily affect a nation''s ability to produce goods cheaply.', 'Economics', 'Marketing', 1500, 'EC:016', 'Explain the nature of global trade', 'Marketing District 2026 #32'),
  ('Which of the following factors have provided businesses with more opportunities to buy and sell products at the international level:', array['Language barriers','Strict safety standards','Free trade agreements','Protectionism'], 2::smallint, 'Free trade agreements. Free trade agreements lessen the trade restrictions (e.g., tariffs, quotas, licenses) among countries. For example, the United States-Mexico-Canada Agreement (USMCA) is a trade agreement among the United States, Canada, and Mexico that has eliminated trade barriers. When fewer trade barriers exist, there are more opportunities for businesses to buy and sell products in other countries. Protectionism is a government''s policy to protect domestic industries and businesses against foreign competition. Protectionism, language barriers, and strict safety standards often hinder a business''s ability to enter international markets.', 'Economics', 'Marketing', 1500, 'EC:104', 'Discuss the global environment in which businesses operate', 'Marketing District 2026 #33'),
  ('Monitoring your progress is an important step in improving self-control because it allows you to', array['adjust your efforts if necessary.','set new goals.','identify a target behavior.','change your environment.'], 0::smallint, 'Adjust your efforts if necessary. Only by monitoring your progress can you determine whether the methods you are using are working or need to be changed. Changing your environment is not always possible. Identifying the target behavior involves selecting the behavior you wish to change. New goals should be set at the beginning of the process.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:025', 'Demonstrate self-control', 'Marketing District 2026 #34'),
  ('Which of the following levels of managers spend most of their time staffing, directing, and controlling the day -to- day activities of the business:', array['Mid-level','Executive','First-line','Regional'], 2::smallint, 'First-line. First-line or supervisory managers work directly with the employees who carry out the business''s routine work. First-line managers report to the mid-level managers. Mid-level managers are responsible for implementing the goals set by executive (top-level) managers, and are the link between supervisory and executive (top-level) managers. Mid-level managers report to the executive managers. Executive managers are responsible for the whole organization and spend most of their time setting organizat ional goals and conducting strategic planning. A regional manager manages employees in a specific location or region. Regional managers are usually considered mid-level managers.', 'Strategic Management', 'Marketing', 1500, 'SM:001', 'Explain the concept of management', 'Marketing District 2026 #35'),
  ('When Emily posts an advertisement for a job opening on an employment website, she is using technology for __________ purposes.', array['performance-management','training','selection','recruitment'], 3::smallint, 'Recruitment. Recruitment involves seeking out and attracting potential employees. Primary technological tools that human-resources professionals use to recruit job candidates include their company websites and employment websites such as Monster and Indeed. The employee-selection process involves identifying the most qualified candidates for a job through screening and interviewing processes. Performance management facilitates the activities and processes used to evaluate employees'' job performance. Training uses different methods to teach employees how to perform their jobs. Emily is not using technology for employee -selection, performance-management, or training activities.', 'Human Resources Management', 'Marketing', 1500, 'HR:412', 'Describe the use of technology in human resources management', 'Marketing District 2026 #36'),
  ('A business that fails to protect its employees from unnecessary risk or health hazards on the job may be sued for', array['negligence.','incompetence.','libel.','misrepresentation.'], 0::smallint, 'Negligence. A business might be sued for negligence if it does not take reasonable precautions to protect workers from risks or health hazards on the job. The basis of negligence is that the problems could have been easily avoided if the business had made some minor adjustments. Consequently, businesses usually try to make the workplace as safe as possible in order to avoid being sued for negligence. Misrepresentation involves making unrealistic claims about products. Libel is making false statements that harm an individual''s reputation. Incompetence involves not having the skills or abilities necessary to perform satisfactorily.', 'Business Law', 'Marketing', 1500, 'BL:001', 'Describe legal issues affecting businesses', 'Marketing District 2026 #37'),
  ('What is one of the reasons that economic systems are necessary?', array['Products are expensive.','Governments are unstable.','People are interdependent.','Resources are unlimited.'], 2::smallint, 'People are interdependent. People in all economic systems are interdependent. In other words, they must depend on each other to obtain the things they need. The economic system provides a way for this to happen. For example, people work to produce goods and services for others but also earn incomes that they use to buy goods and services that they cannot make for themselves. Many resources are limited rather than unlimited. Some governments are unstable, but many are stable. The cost of products ranges from inexpensive to expensive. These factors are not the reasons that economic systems are needed.', 'Economics', 'Marketing', 1500, 'EC:007', 'Explain the types of economic systems', 'Marketing District 2026 #38'),
  ('Ashley owns a small hardware shop. Every month, she reviews her inventory lists to see which products are popular and which are not. Using this information, Ashley is able to order the appropriate amount of each product for her store. This is an example of the importance of', array['stocking a diverse array of products.','monitoring internal records.','over-purchasing certain products.','ignoring inventory when ordering.'], 1::smallint, 'Monitoring internal records. Monitoring internal records for business information is an important practice for business owners. By tracking records such as inventory, business owners can gain valuable business information such as which products are doing well and which products are less popular. This example demonstrated the importance of monitoring internal records, not over-purchasing certain products, stocking a diverse array of products, or ignoring inventory when ordering.', 'Information Management', 'Marketing', 1500, 'NF:014', 'Monitor internal records for business information', 'Marketing District 2026 #39'),
  ('Which of the following is a disadvantage of consensus building:', array['Discussing different points of view','Encouraging unnecessary compromise','Relying on group members'' persuasive skills','Making each person speak in front of the group'], 1::smallint, 'Encouraging unnecessary compromise. A disadvantage of consensus building is that it encourages group members to compromise even when it might not be wise for a group member to compromise on their personal beliefs. Persuasive skills should not be a part of consensus building. But, if they are, consensus building certainly does not rely on them. Some group members may speak in front of the group, but no one is required to. Everyone is given equal say, but how a group member presents their information can vary . Discussing different points of view is not a drawback to consensus building. In fact, it promotes consensus.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:011', 'Use consensus-building skills', 'Marketing District 2026 #40'),
  ('Marley is working with a group member who''s explaining her part of a project. Marley wants to make sure her group member knows she''s listening, so she says things like, "I see," "uh-huh," and "I understand." Which active listening skill is Marley demonstrating?', array['Using a verbal acknowledgment response','Repeating critical information','Collecting all the information possible','Paraphrasing the message to test her understanding'], 0::smallint, 'Using a verbal acknowledgment response. In one-on-one or small group conversations like Marley''s, a short verbal response lets the speaker know you are paying close attention. By saying things like "I see" or "uh -huh," you let the other person know that you''re actively listening. Repeating critical information is another important active listening skill that involves repeating things like phone numbers, names, or websites. When you paraphrase the message, you repeat what the other person said but in your own words. When you collect all the information possible, you observe gestures, interpret body language, and listen to the person''s tone of voice. All of these are important active listening skills, but they aren''t what Marley is doing in this example.', 'Communication Skills', 'Marketing', 1500, 'CO:017', 'Demonstrate active listening skills', 'Marketing District 2026 #41'),
  ('Tallulah''s coworkers describe her as adaptable, cooperative, enthusiastic, and optimistic. When she comes across a problem at work, Tallulah figures out how to solve it without being asked. In other words, Tallulah shows', array['initiative.','respect.','aggressiveness.','empathy.'], 0::smallint, 'Initiative. Initiative is the willingness to act without having to be told to do so. People who demonstrate initiative are willing to accept and seek out additional or even unpleasant duties. By figuring out how to solve a problem at work without being asked, Tallulah is demonstrating initiative, not necessarily aggressiveness, empathy, or respect.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:024', 'Explain the importance of demonstrating initiative', 'Marketing District 2026 #42'),
  ('It is difficult to make decisions that can cause you harm, which is why financial professionals often act unethically due to', array['loss aversion.','sunk costs.','conformity.','self-interest.'], 3::smallint, 'Self-interest. It is natural to look out for yourself! Self-interest, however, can bias decision-making. It is difficult to make the ethical choice if it goes against your own well-being, which is why finance professionals sometimes act unethically to protect themselves. Loss aversion is the tendency to avoid a loss at all costs, even when attempting to avoid that loss can lead to negative consequences. Conformity is the tendency to behave in the same way that everyone else does rather than exercising one''s own judgment. Sunk costs are costs that have already been incurred and thus cannot be recovered.', 'Financial Analysis', 'Marketing', 1500, 'FI:355', 'Discuss the role of ethics in finance', 'Marketing District 2026 #43'),
  ('Sales commissions are a __________ expense.', array['fixed','variable','one-time','capital'], 1::smallint, 'Variable. Sales commissions are a variable expense—they usually fluctuate with changes in production. They are not a one-time expense—businesses pay them on a continual basis. They are not a capital expense—these are one-time purchases a business makes, such as land or equipment. They are not a fixed expense —fixed expenses do not change along with changes in production.', 'Operations', 'Marketing', 1500, 'OP:024', 'Explain the nature of overhead/operating costs', 'Marketing District 2026 #44'),
  ('What should you do if a customer is being difficult or demanding?', array['Tell the customer that their attitude is inappropriate.','Promise to give the customer a significant discount.','Continue to treat them with courtesy and respect.','Ignore them and focus on another customer.'], 2::smallint, 'Continue to treat them with courtesy and respect. Even if a customer is difficult and demanding, they should still be treated well. You should never ignore a customer, and it''s out of line to tell a customer that their attitude is inappropriate. You also shouldn''t confront customers. Even if they''re being rude, you still must treat them respectfully. Be careful about making promises to the customer that you might not be able to fulfill. Broken promises are poor customer relations, so avoid promising anything unless you''re sure that your manager would approve.', 'Customer Relations', 'Marketing', 1500, 'CR:003', 'Explain the nature of positive customer relations', 'Marketing District 2026 #45'),
  ('Emma is reviewing the sales budget in relation to the actual sales generated for a set time frame. How is Emma using financial information in this situation?', array['To analyze the impact of aging accounts','To compare estimated performance with actual performance','To establish new quality standards and benchmarks','To identify external economic trends'], 1::smallint, 'To compare estimated performance with actual performance. Businesses rely on accurate financial information to make sound business decisions. In the situation provided, Emma is comparing one financial report (budget) with another financial report (actual sales) to determine if the business performed as expected—if it achieved its sales goals. Although external economic conditions can affect sales, Emma is analyzing internal financial information rather than identifying external economic trends. Emma is not establishi ng new quality standards and benchmarks or analyzing the impact of aging accounts.', 'Financial Analysis', 'Marketing', 1500, 'FI:579', 'Describe the need for financial information', 'Marketing District 2026 #46'),
  ('Marketing is described as creating', array['gaps.','exchanges.','advertisements.','needs.'], 1::smallint, 'Exchanges. Marketing is described as creating exchanges—or encouraging trade by providing opportunities. Regarding the other options, marketing satisfies needs, uses advertisements, and bridges the gap between producers and customers.', 'Marketing', 'Marketing', 1500, 'MK:001', 'Explain marketing and its importance in a global economy', 'Marketing District 2026 #47'),
  ('As an employee, you should accept your supervisor''s suggestions for improvement and then', array['forget the suggestions.','change your behavior.','go your own way.','complain to your coworkers.'], 1::smallint, 'Change your behavior. Constructive criticism is evaluative information designed to help someone improve. Changing your behavior is both the intent of the feedback and the desired outcome. Forgetting about the suggestions and going your own way or complaining about them will not benefit you and may cause you problems.', 'Emotional Intelligence', 'Marketing', 1500, 'EI:003', 'Explain the use of feedback for personal growth', 'Marketing District 2026 #48'),
  ('The employees of the DER corporation have personally helped establish quality control guidelines to follow when serving customers. When problems occur, they discuss ways to further improve customer service with their supervisors. What type of quality control strategy is the DER corporation using?', array['Feedback control','External control','Concurrent control','Internal control'], 3::smallint, 'Internal control. Quality guidelines established by employees to solve problems are a type of internal control strategy. External control refers to rewards tied to performance and the supervision of employees by managers. Concurrent control monitors activities during their performance and makes corrective suggestions. Feedback control evaluates an activity afterwards and points out what may have gone wrong.', 'Operations', 'Marketing', 1500, 'OP:164', 'Utilize quality control methods at work', 'Marketing District 2026 #49'),
  ('Which of the following is an advantage of opening a franchise:', array['Paying royalties','Reliance on raw materials','Restrictions on products, prices, and location','A well-known brand name'], 3::smallint, 'A well-known brand name. Often, opening a franchise brings an existing customer base that is familiar with the brand name, which can increase the possibility of success in comparison to a new, unknown business. Paying royalties and restrictions on products, prices, and location would be considered disadvantages of opening a franchise. Reliance on raw materials is a disadvantage of the manufacturing business model.', 'Economics', 'Marketing', 1500, 'EC:138', 'Describe types of business models', 'Marketing District 2026 #50'),
  ('What type of planned obsolescence is generally considered socially and economically desirable because the replacement product offers more benefits or a lower cost?', array['Technological','Style','Psychological','Fashion'], 0::smallint, 'Technological. Technological obsolescence equates to significant technological improvements that result in a more effective product (e.g., CDs, from cassettes, from phonograph records). Style obsolescence refers to superficial changes to a product resulting in a new product. The new model is intended to make users of the older model feel out-of-date and encourage them to purchase the new model. This is typical in fashion merchandise. Psychological and fashion are synonymous with style obsolescence.', 'Product/Service Management', 'Marketing', 1500, 'PM:040', 'Explain business ethics in product/service management', 'Marketing District 2026 #51'),
  ('Which of the following is an element of an effective survey:', array['An explanation of its purpose','A long set of instructions','Biased questions','Vague questions'], 0::smallint, 'An explanation of its purpose. It''s important to let survey participants know why a survey is being administered. This means explaining what information is being collected and how it will be used. Questions should be unbiased and as clear as possible. Instructions should be as short and concise as possible.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:418', 'Explain characteristics of effective data-collection instruments', 'Marketing District 2026 #52'),
  ('A company''s strategy, culture, and communication combine to form brand', array['identity.','touchpoints.','promise.','cues.'], 0::smallint, 'Identity. Brand identity is the culmination of what a company wants to be—what it says about who it is. Strategy, culture, and communication all contribute to brand identity. Brand touchpoints are any instances in which the customers encounter the brand, such as a promotional message or a company website. Brand cues are messages that affect buying behavior in regard to a brand, such as a certain word that makes a customer think of a product. A brand promise is a commitment made by a brand to its customers about what it intends to deliver.', 'Product/Service Management', 'Marketing', 1500, 'PM:207', 'Describe factors used by businesses to position corporate brands', 'Marketing District 2026 #53'),
  ('Naomi uses quality market research methods, is open about those methods, and backs up the research with transparent, objective analysis. Naomi is establishing', array['privacy.','credibility.','competition.','adaptability.'], 1::smallint, 'Credibility. Credibility is believability. It is critical that marketers ensure the information they manage is believable. Otherwise, no one will trust the information, and it won''t be useful. Marketers can establish credibility by using quality research methods, being open about those methods, and backing up the research with transparent, objective analysis. Naomi is not establishing competition, privacy, or adaptability in this scenario.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:025', 'Explain the role of ethics in marketing-information management', 'Marketing District 2026 #54'),
  ('Which of the following is the most common distribution channel for consumer goods:', array['Producer to ultimate consumer to agent to retailer','Producer to wholesaler to retailer to ultimate consumer','Wholesaler to producer to retailer to ultimate consumer','Retailer to agent to ultimate consumer to producer'], 1::smallint, 'Producer to wholesaler to retailer to ultimate consumer. Producer to wholesaler to retailer to ultimate consumer is the most common distribution channel for consumer goods. First, the producer makes the good. Next, the wholesaler moves the good from the producer to the retailer. Then, the retailer sells the good, and finally, the ultimate consumer purchases it. An agent is a business or individual that assists in the sale and/or promotion of goods and services but does not buy them from the producer. If an agent is used, their involvement is typically the second step of the process after producer.', 'Channel Management', 'Marketing', 1500, 'CM:003', 'Explain the nature of channels of distribution', 'Marketing District 2026 #55'),
  ('A business''s expense reports and cash-register receipts are sources of __________ research data.', array['internal, quantitative','external, quantitative','elementary, qualitative','organic, qualitative'], 0::smallint, 'Internal, quantitative. Internal data, such as expense reports and cash-register receipts, are generated within the business. Because expense reports and cash-register receipts contain specific, numerical, measurable data, they are quantitative data. Businesses collect external data from outside sources such as competitors'' web sites and government publications. Qualitative data are based on emotions, feeling, thoughts, and experiences. Elementary and organic are not types of data.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:281', 'Describe options businesses use to obtain marketing research data (i.e., primary and', 'Marketing District 2026 #56'),
  ('During the first year that Rick owned his new car, the vehicle seemed to spend more time in the repair shop than it did on the road. Rick contacted the auto manufacturer and demanded his money back because the car seemed to be defective, but the manufacturer refused. A member of the Better Business Bureau agreed to act as an impartial third party in the dispute. The BBB member studied the facts of the case, determined that the car was indeed defective, and decided how much money the carmaker would be requir ed to refund to Rick. This is an example of', array['automation.','attrition.','arbitration.','arbitron.'], 2::smallint, 'Arbitration. When two parties engage in a dispute that they are unlikely to resolve on their own, an impartial third party may step in. The impartial third party, called an arbitrator, hears both sides'' arguments, studies the facts of the case, and then determines a remedy for the situation. This process is called arbitration. The Arbitron Ratings Company uses consumer-generated data to analyze radio advertising. Attrition is a natural reduction in numbers of people due to death, retirement, job changes, etc. Automation is a production method in which machines do tasks automatically.', 'Product/Service Management', 'Marketing', 1500, 'PM:017', 'Identify consumer protection provisions of appropriate agencies', 'Marketing District 2026 #57'),
  ('What are businesses often able to do if they have a narrow product mix?', array['To industrialize','To generalize','To specialize','To cannibalize'], 2::smallint, 'To specialize. Businesses having a narrow product mix often are able to specialize, which allows them to produce efficiently and concentrate on marketing their limited number of product lines. Businesses with only a few product lines are able to focus all their efforts on their limited specialties. Cannibalization is the situ ation that exists when the sale of one of a company''s products takes away sales from another of its products. Generalization is the opposite of specialization. Industrialization is the changeover from producing goods by hand labor to the use of machines and the organization of such production into industries.', 'Product/Service Management', 'Marketing', 1500, 'PM:003', 'Explain the concept of product mix', 'Marketing District 2026 #58'),
  ('Which of the following is the type of branding that differentiates an organization from its competitors:', array['Corporate','Product','Universal','Loyalty'], 0::smallint, 'Corporate. A corporate brand is all of the combined impressions, images, or experiences associated with a company or parent entity. Disney is an example of a corporate brand. The Disney theme parks and resorts, Marvel Entertainment, ABC and ESPN television networks, and consumer products are a reas within the Disney corporate brand. Product brands are the combined impressions, images, and experiences associated with a particular good, service, or product line. Loyalty and universal are not types of brands.', 'Product/Service Management', 'Marketing', 1500, 'PM:206', 'Explain the nature of corporate branding', 'Marketing District 2026 #59'),
  ('During the decline stage, a company may choose to discontinue a product and sell off the remaining inventory in a process known as', array['a super sale.','penetration pricing.','foreclosure.','liquidation.'], 3::smallint, 'Liquidation. During the decline stage, a company may choose to discontinue a product and sell off the remaining inventory in a process known as liquidation (converting assets to cash). Penetration pricing is a strategy used during the introduction stage, where marketers price a product low to achieve rapid market acceptance. A company may or may not sell inventory in a super sale—they often sell it to another company, not retail customers. A foreclosure occurs when a person or business can no longer make pa yments on a piece of property.', 'Product/Service Management', 'Marketing', 1500, 'PM:024', 'Identify the impact of product life cycles on marketing decisions', 'Marketing District 2026 #60'),
  ('A disadvantage to businesses that use email as a direct-mail strategy is that recipients may not get the message because many computers have', array['invalid home addresses.','spam filters.','promotion controls.','reply options.'], 1::smallint, 'Spam filters. Direct mail is a promotional medium that comes to consumers'' homes and businesses. Email is a form of direct mail that businesses send by computer. Spam is junk email that the recipient does not request and does not allow the recipient to request removal from the subscriber list. To reduce the amount of spam recipients receive, businesses and consumers are installing software programs that filter the spam, which keeps it from reaching the intended recipients. Invalid email addresses, rather than home addresses, would prevent email recipients from receiving email. Reply options do not keep email from reaching the intended message recipients. Promotion control is a fictitious term.', 'Promotion', 'Marketing', 1500, 'PR:089', 'Explain the nature of direct marketing channels', 'Marketing District 2026 #61'),
  ('Which of the following is the main internal audience for public relations activities:', array['Suppliers','Employees','Labor unions','Community leaders'], 1::smallint, 'Employees. Most businesses provide information to employees, the business''s main internal audience. Providing information is a public relations activity because it is intended to maintain good relations with employees. Employees tend to work more effectively and have higher morale when they are well informed and have accurate information about the business''s plans and goals. Providing accurate information also reduces rumors, which may have a negative impact on employees. Suppliers, labor unions, and commun ity leaders are not internal audiences, although they have direct contact with many businesses.', 'Promotion', 'Marketing', 1500, 'PR:253', 'Discuss internal and external audiences for public-relations activities', 'Marketing District 2026 #62'),
  ('Qualitative marketing data are valuable, but they can be limited because', array['the data do not provide enough detail.','the data are objective rather than subjective.','the data usually only include a small portion of the target market.','participants'' responses are constrained by limited options.'], 2::smallint, 'The data usually only include a small portion of the target market. Qualitative data provide researchers with valuable knowledge to use in planning marketing activities. The scope, however, is limited. Since qualitative research usually only includes a very small portion of the target market, it is often not enough to make generalizations about an entire population. In qualitative data, participants'' responses are not necessarily constrained by the limited options. Qualitative data tend to provide more detail than quantitative data. Fi nally, qualitative data are subjective rather than objective.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:289', 'Describe data-collection methods (e.g., observations, mail, diaries, phone, internet,', 'Marketing District 2026 #63'),
  ('A pricing tactic used by some businesses that might be unethical is one that', array['confuses customers.','advertises discounts.','offers rebates.','is competitive.'], 0::smallint, 'Confuses customers. A business that deliberately tries to confuse customers about the price of goods and services may be behaving unethically. Some pricing structures may be complex, which makes them difficult for customers to understand. As a result, customers usually are unable to figure out how to get a lower price and end up spending more than they should. This practice is considered unethical because customers don''t have a fair chance to get the best price. Most pricing tactics are intended to be competitive. It is also common for businesses to advertise discounts and offer rebates. These tactics are not unethical.', 'Pricing', 'Marketing', 1500, 'PI:015', 'Describe the role of business ethics in pricing', 'Marketing District 2026 #64'),
  ('Which of the following is an aspect of coordinating the distribution of a product with other marketing activities:', array['Setting an appropriate price','Analyzing customer satisfaction','Developing an operating budget','Recruiting qualified personnel'], 0::smallint, 'Setting an appropriate price. Setting the price of a product is one of the marketing activities that a business should coordinate with distribution in order to successfully sell to customers. Not only does a business need to make its product available, but it also must sell it at a price that consumers are willing to pay. If a product is not priced appropriately, customers usually will not buy it even if it is widely distributed. Businesses often analyze customer satisfaction after a product is marketed to determine if any changes need to be made. Developing an operating budget and recruiting qualified personnel are not marketing activities.', 'Channel Management', 'Marketing', 1500, 'CM:007', 'Coordinate channel management with other marketing activities', 'Marketing District 2026 #65'),
  ('Providing favorable adjustment and return policies is one way that a __________ builds clientele.', array['business','society','coalition','salesperson'], 0::smallint, 'Business. Without a loyal customer base, a business cannot thrive in the marketplace. A business that develops and implements favorable adjustment and return policies not only makes the customer happy, but helps the salesperson sell the product and improves the business''s overall ability to build a loyal clientele. A society is a group of individuals that shares an environment. A coalition is a group of individuals who gather for a specific purpose. Societies and coalitions do not exist for the purpose of building clientele.', 'Selling', 'Marketing', 1500, 'SE:828', 'Explain key factors in building a clientele', 'Marketing District 2026 #66'),
  ('A company''s managers ask themselves, "Why is our market share dropping?" This is an example of a __________-oriented decision problem.', array['discovery','strategy','situation','research'], 0::smallint, 'Discovery. Discovery-oriented decision problems are aimed at answering the questions "what?" or "why?" Strategy-oriented questions are aimed at answering the questions "how?" or "which?" A research problem asks what research needs to be done to solve the decision problem. This is not referred to as a situation-oriented problem.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:282', 'Discuss the nature of marketing research problems/issues', 'Marketing District 2026 #67'),
  ('Which of the following might a salesperson rely on to obtain firsthand product knowledge:', array['Customer opinion','Vendor information','Personal experience','Government reports'], 2::smallint, 'Personal experience. An effective way of obtaining firsthand product knowledge is for a salesperson to use the product personally. Salespeople who use the products they sell find out exactly how the product works and often are better able to answer customers'' questions. Personal experience is a good way of learning about products. Customer opinion, vendor information, and government reports are not ways of obtaining firsthand product knowledge.', 'Selling', 'Marketing', 1500, 'SE:062', 'Acquire product information for use in selling', 'Marketing District 2026 #68'),
  ('What type of promotional media is a business using when it sends out a postcard telling customers who recently purchased products that the business is adding a new line of products?', array['Direct mail','Participative','Sales letter','Persuasive'], 0::smallint, 'Direct mail. Direct mail is a promotional medium that comes to consumers'' homes and businesses. Businesses that use direct mail often send it to current customers who are likely to buy more products. Persuasive direct mail encourages immediate action such as mail orders or inquiries. A sales letter is a type of printed direct mail, as is a postcard. Participative is not a type of direct mail.', 'Promotion', 'Marketing', 1500, 'PR:007', 'Explain types of advertising media', 'Marketing District 2026 #69'),
  ('One of the customer benefits of warranties and guarantees is the right to', array['free training.','legal recourse.','lower prices.','personalized service.'], 1::smallint, 'Legal recourse. There are many different kinds of benefits from warranties and guarantees. Consumer benefits from warranties and guarantees include legal recourse if a company does not fulfill its obligations under a warranty or a guarantee. The courts will uphold a legitimate claim and see that the cust omer obtains satisfaction. The benefits of warranties and guarantees do not include lower prices, personalized service, and free training.', 'Product/Service Management', 'Marketing', 1500, 'PM:020', 'Explain warranties and guarantees', 'Marketing District 2026 #70'),
  ('One way that businesses use environmental monitoring in the marketing planning process is to', array['obtain information about natural resources.','identify changes that might be opportunities.','locate health-conscious consumers.','review the safety status of physical facilities.'], 1::smallint, 'Identify changes that might be opportunities. Environmental monitoring involves tracking external forces, such as population statistics, to determine if there are new trends that indicate changes. By identifying any changes in the external environment, businesses can decide if these changes might be opportunities for the business. For example, statistics might show that there has been a 50% decrease in milk consumption in the last 10 years. A business that produces and sells other types of beverages might decide that this change is an opportunity for the business to reach the market that no longer drinks milk. Businesses do not use environmental monitoring in the marketing planning process to obtain information about natural resources, locate health-conscious consumers, or review the safety status of physical facilities.', 'Market Planning', 'Marketing', 1500, 'MP:008', 'Explain the role of situation analysis in the marketing planning process', 'Marketing District 2026 #71'),
  ('When marketers are developing the product element of the marketing mix, which of the following factors should they consider:', array['When messages should be delivered','How to raise a product''s value','Which brands should be used','How much of the product to order'], 2::smallint, 'Which brands should be used. The product element of the marketing mix focuses on the goods, services, or ideas a business will offer its customers. When developing the product element, marketers should consider which brands should be used, what level of quality should be produced or provided, and how the product should be packaged, among other things. How to raise a product''s value is something that marketers would consider when developing the price element of the marketing mix. How much of the product to order is something marketers would consider in the place element. When messages should be delivered would be considered part of the promotion element.', 'Market Planning', 'Marketing', 1500, 'MP:001', 'Explain the concept of marketing strategies', 'Marketing District 2026 #72'),
  ('Ryan works in marketing at a telecommunications company. His current assignment involves conducting research on customers'' TV viewing preferences. He designs a survey to send to customers in the mail, holds a focus group to learn more about his customers'' television activity, and recruits participants for a formal study using an in-home data tracking device. Ryan is displaying which of the following good research practices:', array['Using multiple types of research methods','Defining and articulating a research question','Reevaluating the research question as needed','Engaging in research planning before starting'], 0::smallint, 'Using multiple types of research methods. Mixed methods research is a research methodology that involves collecting and analyzing data from various sources using various methods. This type of research usually involves both qualitative (descriptive) and quantitative (numerical) data. Researchers who utilize various methods to gather information gain a better understanding of the topic they are studying than if they had used a single research method. Defining and articulating a research question, engaging in research planning, and reevaluating the research question as needed are also examples of good research practices; however, they are not demonstrated in this scenario.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:428', 'Assess appropriateness of marketing research for the problem/issue (e.g., research', 'Marketing District 2026 #73'),
  ('Six Thinking Hats is a creative-thinking technique that stimulates idea generation by', array['categorizing information.','assigning each group member a different job.','playing the devil''s advocate.','providing positive feedback.'], 0::smallint, 'Categorizing information. The Six Thinking Hats technique is a creative-thinking technique that utilizes different ways of approaching a problem. Each of the six hats represents one aspect of the situation. For example, the white hat looks at all the facts and data available. The blue hat summarizes and organizes thoughts and information. By placing each aspect into different categories, the situation can be evaluated by using various viewpoints. Playing the devil''s advocate or looking at the negatives of the situation is one part of the overall technique. The Six Thinking Hats technique can be used in a group or alone. Therefore, it cannot be assumed that this method of creative thinking is always conducted in a group situation where each group member is assigned a different job. Positive feedback is a general term and is not necessarily a step in the Six Thinking Hats creative-thinking technique.', 'Product/Service Management', 'Marketing', 1500, 'PM:127', 'Identify methods/techniques to generate a product idea', 'Marketing District 2026 #74'),
  ('Marketers can gain an understanding of how customers behave by studying', array['physiology.','psychology.','geography.','demography.'], 1::smallint, 'Psychology. Psychology is the science that deals with the characteristics of human behavior. Marketers can gain an understanding of how and why people behave the way they do by studying psychology. Understanding customers'' buying behavior and what makes them tick helps marketers to be tter meet their needs. Demography is the study of the characteristics of populations. Physiology is the biological study of the functions of living organisms. Geography is the study of the earth.', 'Professional Development', 'Marketing', 1500, 'PD:024', 'Explain employment opportunities in marketing', 'Marketing District 2026 #75'),
  ('Reaching closure is the phase in the selling process when salespeople often need to', array['identify customer reactions.','sell product benefits.','answer remaining objections.','determine buying needs.'], 2::smallint, 'Answer remaining objections. Reaching closure is the fourth phase of the selling process. It often involves answering any remaining objections the customer may have. Salespeople should anticipate objections and learn to use them to their advantage in a sales presentation. When customers are satisfied that their objections have been satisfactorily addressed, they often give off signals that the time has come to close the sale. Salespeople sell product benefits when prescribing solutions to customer needs. Sa lespeople do not determine buying needs or identify customer reactions during the reaching closure phase of the selling process.', 'Selling', 'Marketing', 1500, 'SE:048', 'Explain the selling process', 'Marketing District 2026 #76'),
  ('A large firm conducts a series of focus groups to determine if it should release a new product. What should the firm do with the data resulting from the focus groups?', array['Use the data to make generalizations.','Analyze data with statistics.','Act immediately on the data.','Identify problems with the new product.'], 3::smallint, 'Identify problems with the product. The data results from focus groups are qualitative data, which are difficult to analyze statistically. This is because focus groups use small sample sizes and are relatively unstructured, as opposed to a survey of a large portion of the population. The firm should not use the data to make generalizations about the entire population because the sample size is small. The firm should definitely not act immediately on the data because there is no way to analyze the results.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:062', 'Explain techniques for processing marketing data', 'Marketing District 2026 #77'),
  ('Barney''s Computers advertises that the company provides delivery and instruction to purchasers of computer packages. Barney''s is offering __________ services.', array['design','pure','product-screening','product-related'], 3::smallint, 'Product-related. There are two kinds of services that businesses offer: pure services and product -related services. Pure services do not include a tangible product, while product-related services are services that are offered with a product. Product screening is not a type of service but the process of considering each idea for a new product and discarding those that seem unworkable. Design is the way in which a product functions or the way it looks.', 'Product/Service Management', 'Marketing', 1500, 'PM:001', 'Explain the nature and scope of the product/service management function', 'Marketing District 2026 #78'),
  ('Which of the following is a benefit of using technology in channel management:', array['It eliminates the need for employees.','It increases delivery times.','It increases efficiency.','It decreases the accuracy of orders.'], 2::smallint, 'It increases efficiency. Technology can be used to increase the efficiency of channel management. Although it can save a company time and money, it does not mean that no employees are needed. It increases the accuracy of orders and decreases delivery times.', 'Channel Management', 'Marketing', 1500, 'CM:004', 'Describe the use of technology in the channel management function', 'Marketing District 2026 #79'),
  ('With a high level of selling ethics, you would typically ask which of the following questions in an ethical situation:', array['What is the right thing to do?','What is required of me?','What can I get away with?','What would others advise?'], 0::smallint, 'What is the right thing to do? With a high level of selling ethics, you would typically ask, "What is the right thing to do?" You would not consider what you could get away with, and you would not do only what is required. Although you might consider someone else''s advice, the right thing to do may be different from that advice.', 'Selling', 'Marketing', 1500, 'SE:106', 'Explain legal and ethical considerations in selling', 'Marketing District 2026 #80'),
  ('When a channel member has the means to provide certain financial incentives to cooperative intermediaries in the supply chain, the channel member is exerting its power through', array['a reward system.','sanctions and tariffs.','tying agreements.','its expertise.'], 0::smallint, 'A reward system. All of the businesses and individuals that move goods and services through a product''s supply chain are the distribution channel members. The channel members depend on each other to make sure the end users receive the products when they need them and where they need them. Depending on the product and the nature of the channel relationship, one channel member may have a power source that the other channel members do not have. For example, a channel member that can offer financial incentives to one or more channel members to move products has power based on the ability to provide rewards. If a channel member has knowledge that other channel members don''t have, that channel member''s power base is expertise. Sanctions are the ability to penalize a channel member. A tying agreement is an illegal agreement requiring a customer to buy other products in order to obtain desired goods and services.', 'Channel Management', 'Marketing', 1500, 'CM:008', 'Explain the nature of channel-member relationships', 'Marketing District 2026 #81'),
  ('Leena reviews Remy''s advertisement draft and notes that it looks too cluttered and busy. "Customers would feel overwhelmed looking at this!" she explains. How should Remy revise his advertisement?', array['Decrease the margins.','Decrease the font size.','Add white space.','Add more images.'], 2::smallint, 'Add white space. Adding white space will help improve readability, create balance, and focus readers'' attention. Decreasing the font size, adding more images, and decreasing the margins would make the advertisement more difficult to read and less effective. An advertisement should make the best use of space, characters, and imagery to clearly communicate the message.', 'Promotion', 'Marketing', 1500, 'PR:251', 'Explain the importance of coordinating elements in advertisements', 'Marketing District 2026 #82'),
  ('When a business lowered its prices during a bad economic time, it demonstrated __________ pricing.', array['realistic','exchange','competitive','flexible'], 3::smallint, 'Flexible. Because pricing is a tug-of-war and a constant quest for balance, businesses must be willing to be flexible and adjust their prices as necessary. For example, during bad economic times, customers are cautious about how they spend their money, and businesses may need to lower prices to attract these customers. Realistic pricing means prices are what customers expect to pay. Competitive pricing involves being aware of the prices others are charging and pricing your own products accordingly. Exchange price is the amount of money that the buyer is willing to pay and the seller is willing to accept for a good or service.', 'Pricing', 'Marketing', 1500, 'PI:001', 'Explain the nature and scope of the pricing function', 'Marketing District 2026 #83'),
  ('The owner of Doxie Dog Rescue wrote an article about the organization''s latest fundraising campaign and emailed it to three local newspapers. She hopes that at least one of the three papers will run the article for free in their publication. Doxie Dog''s owner is using a __________ to promote her organization''s activities.', array['editorial','press kit','matte release','letter to the editor'], 2::smallint, 'Matte release. Generally used as filler material in written publication, a matte release is an article that is not generated by a publication''s staff. Instead, businesses write these matte releases and submit the material to be printed by one or more media outlets. The business benefits from free promotion, and the publication benefits because the content takes up space. A matte release may be contained in a press kit. An editorial is generally written by a staff member of a publication. A letter to the editor is a form of editorial that is generally written by readers of the publication.', 'Promotion', 'Marketing', 1500, 'PR:250', 'Explain communications channels used in public-relations activities', 'Marketing District 2026 #84'),
  ('What is the primary goal of corporate promotion?', array['To explain a specific feature','To create a certain image','To publicize a service','To sell a product'], 1::smallint, 'To create a certain image. The primary goal of corporate promotion is to create a certain image of the company in the eyes of the consumer. This is accomplished by informing consumers about the company, its ideas, and its philosophy. Unlike product promotion, institutional or corporate promotion does not attempt to sell a good or service. The goal of corporate promotion is not to explain a specific feature.', 'Promotion', 'Marketing', 1500, 'PR:002', 'Explain the types of promotion (i.e., institutional, product)', 'Marketing District 2026 #85'),
  ('When Jamie develops a questionnaire, she places very broad questions at the beginning of the questionnaire and progressively includes questions that are narrower in scope toward the end of it. What sequencing format is Jamie using to develop the questionnaire?', array['Branching','Funnel','Bridging','Remote'], 1::smallint, 'Funnel. The funnel approach involves asking very broad questions at the beginning of the questionnaire. This helps the respondents focus and get comfortable with the survey. Then, the questionnaire progressively asks the questions that are narrower in scope toward the end of the questionnaire. The funnel approach helps researchers organize the questionnaire in a way that prevents question-order bias. Branching is a technique that requires respondents to go to another place in the questionnaire to answer spe cific questions if they respond a certain way to the initial question. Bridging and remote are not questionnaire formats.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:293', 'Evaluate questionnaire design (e.g., types of questions, question wording, routing,', 'Marketing District 2026 #86'),
  ('A characteristic of product bundling is that a business sells several products together for a(n)', array['higher interest rate.','higher profit margin.','reduced price.','unlimited time.'], 2::smallint, 'Reduced price. Product bundling is the practice of putting together a number of goods/services to create a one - price package. Most often, the bundled package is priced so it costs the customer less than if they purchased each product separately. The goal of product bundling is to increase sales and to get customers to try something that they normally wouldn''t purchase. The interest rate is the percentage figure used in calculating interest charges, which are money payments for borrowed money. Product bundli ng does not always provide the business with a higher profit margin, nor does it always require the business to consider interest rates. The amount of time a business bundles particular products depends on the type of product and the business''s objectives.', 'Product/Service Management', 'Marketing', 1500, 'PM:041', 'Describe the nature of product bundling', 'Marketing District 2026 #87'),
  ('A business might be involved in the illegal activity of deceptive pricing if it', array['misleads customers about the true value of a product.','changes prices according to current demand.','offers special prices on a discontinued item.','sells products at a limited number of predetermined price points.'], 0::smallint, 'Misleads customers about the true value of a product. Deceptive pricing is an illegal pricing tactic because it misleads customers about the true value of a product. An example of deceptive pricing is setting a high price on a product and then advertising a big discount which actually reduces the price to a realistic, or normal, level. Customers buy the item because they think they are saving money when, in fact, they are paying what the item is actually worth. Price lining involves selling products at a limited number of predetermined price points. Variable pricing involves changing prices according to current demand. Promotional pricing involves offering special prices on certain products such as discontinued items. These pricing activities are not illegal .', 'Pricing', 'Marketing', 1500, 'PI:017', 'Explain legal considerations for pricing', 'Marketing District 2026 #88'),
  ('The Calisto Cafe franchise calculated how many times its new menu item sold. What type of research data did the company collect?', array['Quantitative','Qualitative','Descriptive','Exploratory'], 0::smallint, 'Quantitative. Calisto Cafe collected numeric data to determine how many times its new menu item sold. Therefore, it collected quantitative data, which are specific and measurable. The franchise did not collect qualitative data based on thoughts, opinions, feelings, or experiences. Exploratory and descriptive are types of research, not types of data.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:284', 'Describe methods used to design marketing research studies (i.e., descriptive,', 'Marketing District 2026 #89'),
  ('An electronic data interchange (EDI) system facilitates a company''s ability to', array['test product quality.','manage product availability.','improve product durability.','develop new products.'], 1::smallint, 'Manage product availability. An electronic data interchange (EDI) system allows a company to monitor its inventory and order products through a computer connection that it shares with its vendors. An EDI system helps a company monitor its inventory to ensure that enough products are available when and where they are needed. An EDI system does not facilitate a company''s ability to improve product durability, test product quality, or develop new products.', 'Product/Service Management', 'Marketing', 1500, 'PM:039', 'Describe the use of technology in the product/service management function', 'Marketing District 2026 #90'),
  ('Traits of successful salespeople include self-motivation, persistence, and', array['impatience.','self-confidence.','insecurity.','selective listening skills.'], 1::smallint, 'Self-confidence. The success and profitability of a business depends on how well the product sells. As employees, salespeople must be successful in persuading customers to purchase the company''s products. Successful salespeople exhibit self-confidence; that is, they believe in their talents, skills, and objectives during the selling process. And by exhibiting self-confidence, salespeople communicate a sense of knowledge and credibility to the customer. Traits of successful salespeople also include patience, positive self-esteem, and comprehensive listening skills.', 'Selling', 'Marketing', 1500, 'SE:017', 'Explain the nature and scope of the selling function', 'Marketing District 2026 #91'),
  ('Which of the following is a benefit to consumers of promotion:', array['Building a clientele','Creating a specific image','Increasing sales of products','Learning new ways to use products'], 3::smallint, 'Learning new ways to use products. Consumers often learn new or better ways to use the products they purchase from the promotions for the products. This helps them to receive full value for their money. Increasing sales of products, creating an image, and building a clientele are promotional activities that benefit the business.', 'Promotion', 'Marketing', 1500, 'PR:001', 'Explain the role of promotion as a marketing function', 'Marketing District 2026 #92'),
  ('Which of the following is an example of salespeople using customer service to facilitate sales relationships:', array['Following up only when necessary','Sending information about competitors','Responding to complaints promptly','Recommending expensive new products'], 2::smallint, 'Responding to complaints promptly. Salespeople invest a lot of time in acquiring customers; therefore, it is important that they concentrate on developing those relationships. One way to maintain and improve a sales relationship is to provide excellent customer service, such as responding to complaints promptly. Salespeople who respond promptly are telling their customers that they are important and that their business is valuable. Customers appreciate the prompt attention and usually respond by continuing to do business with the salesperson. Salespeople should follow up with customers frequently rather than only when necessary. Salespeople do not send information about competitors or recommend expensive new products that their customers don''t need.', 'Selling', 'Marketing', 1500, 'SE:076', 'Explain the role of customer service as a component of selling relationships', 'Marketing District 2026 #93'),
  ('What do advertising regulations usually require businesses to disclose about the products they advertise?', array['Hidden features','Endorsements','Limitations','Personal benefits'], 2::smallint, 'Limitations. Certain products have limitations, such as producing side effects in some people or being potentially hazardous. When businesses advertise these products, they are usually required to disclose the limitations so consumers can make an informed decision about whether to buy. Businesses that violate these regulations run the risk of being sued by consumers who were harmed by the products. Advertisements usually describe the benefits of the products and often contain endorsements. Advertisements of ten point out important features, especially if they are hidden.', 'Promotion', 'Marketing', 1500, 'PR:101', 'Describe the regulation of promotion', 'Marketing District 2026 #94'),
  ('Effective marketing-research projects have certain specific characteristics that apply to all research regardless of scope or complexity. Two characteristics of effective marketing research are', array['thorough and debatable.','systematic and timely.','objective and superficial.','accurate and incomprehensive.'], 1::smallint, 'Systematic and timely. Two ways to describe effective marketing research are systematic and timely. Marketing research is systematic because it follows a step-by-step process that involves gathering, recording, and analyzing information. Marketing research is timely because there are usually due dates associated with it. Other ways to describe effective marketing research include accurate, objective, thorough, reliable, and valid. Incomprehensive, superficial, and debatable are not terms used to describe effective marketing research.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:010', 'Explain the nature of marketing research', 'Marketing District 2026 #95'),
  ('A company features an ad of a man doing common household tasks like washing the dishes and doing laundry. What recommended ethical promotion practice is demonstrated in this commercial?', array['Avoid stereotypes and sexism.','Consider social responsibility.','Handle customer information responsibly.','Exaggerate product benefits.'], 0::smallint, 'Avoid stereotypes and sexism. Ethical marketers seek diversity in both representation and decision -making teams. They avoid sexist or ableist language and imagery and gather feedback from diverse focus groups. Marketers need to consider impact over intent. Society often assumes common household tasks are done by women, so an ad depicting a man washing the dishes and doing laundry follows the recommended ethical promotion practice of avoiding stereotypes and sexism. This commercial does not demonstrate the recommended ethical promotion practices of considering social responsibility or handling customer information responsibly. Exaggerating product benefits is not a recommended ethical promotion practice.', 'Promotion', 'Marketing', 1500, 'PR:099', 'Describe the use of business ethics in promotion', 'Marketing District 2026 #96'),
  ('What activity involves transforming facts and figures into a useful format?', array['Data processing','Information gathering','Data mining','Information reporting'], 0::smallint, 'Data processing. Data processing is an important activity in the marketing-information management function because data are typically not useful in their original form. Data processing takes the raw data and transforms them into organized, meaningful marketing information. After transforming the data into useable information, marketers gather the information and prepare reports to facilitate decision making. Data mining is the process of searching computer databases to look for patterns and relationships among information.', 'Marketing-Information Management', 'Marketing', 1500, 'IM:001', 'Explain the nature and scope of the marketing-information management function', 'Marketing District 2026 #97'),
  ('One of the purposes of the situational analysis component of a marketing plan is to determine a business''s', array['operating objectives.','distribution channels.','expansion options.','current weaknesses.'], 3::smallint, 'Current weaknesses. A situational analysis is a determination of a firm''s current business situation and the direction in which the business is headed. Both internal and external environmental conditions are evaluated to determine the business''s current strengths, weaknesses, opportunities, and threats. It is important for a business to identify and understand its weaknesses to make adjustments in the marketing plan. If businesses fail to address their weaknesses, they may lose customers to competitors. Det ermining distribution channels, operating objectives, and expansion options are not the purposes of the situational analysis component of a marketing plan.', 'Market Planning', 'Marketing', 1500, 'MP:007', 'Explain the nature of marketing plans', 'Marketing District 2026 #98'),
  ('A maker of detergents, soaps, and cleaning supplies divides its market according to consumers'' response to the company''s products. This business is using __________ segmentation.', array['demographic','behavioral','psychographic','geographic'], 1::smallint, 'Behavioral. Behavioral segmentation groups consumers into categories on the basis of what they are looking for in a product and why they buy the product. Demographic segmentation divides a market by characteristics people have in common that affect their purchasing power. Geographic segmentation groups consumers according to where they are located. Psychographic segmentation groups people into markets on the basis of lifestyles and personalities.', 'Market Planning', 'Marketing', 1500, 'MP:003', 'Explain the concept of market and market identification', 'Marketing District 2026 #99'),
  ('A minor league sports team displays the logo of a local business on its jerseys in exchange for sponsorship money. This collaboration is an example of a(n)', array['public relations campaign.','customer support network.','supply chain.','affinity partnership.'], 3::smallint, 'Affinity partnership. Affinity partnerships are strategic relationships formed among companies or organizations for mutual benefit. A sports team displaying a business logo on its jerseys is an example of an affinity partnership. The sports team benefits from the sponsorship money, while the business benefits from the increased brand exposure. This collaboration is not an example of a supply chain, which is a system of processes involved in the production and distribution of a product. It is not an example of a customer support network or a public relations campaign.', 'Channel Management', 'Marketing', 1500, 'CM:021', 'Explain the nature of affinity partner relationships', 'Marketing District 2026 #100'),
  ('A business has added automation to its assembly line process. This addition is most likely an example of', array['invention.','creativity.','innovation.','problem-solving.'], 2::smallint, 'Innovation. Innovation is the development of something new, such as a new product, method, strategy, or process. Innovation can also involve an improvement of something that already exists. Adding automation to an assembly line is an example of innovation because the automation is likely to improve the efficiency of the assembly line process. An invention involves creating something entirely new that did not exist prior to the invention. Creativity, which can be a part of developing innovative ideas, is the ability to generate unique ideas, approaches, and solutions. People with problem-solving skills are often able to innovate and find solutions to obstacles in their path.', 'Professional Development', 'Finance', 1500, 'PD:126', 'Explain the need for innovation skills', 'Finance District 2026 #1'),
  ('The reason why a business prepares a balance sheet is to determine its', array['average cash flow.','estimated annual income.','current financial situation.','future sales goal.'], 2::smallint, 'Current financial situation. A balance sheet is a financial statement that captures the financial condition of the business at that particular moment. It indicates what the business owns, what it owes, and its worth as of a certain date. By preparing a balance sheet, a business can determine if it has sufficient assets to cover its liabilities and still have money remaining, or if its liabilities are more than its assets. A business does not prepare a balance sheet to determine its average cash flow, estimated annual income, or future sales goal.', 'Financial Analysis', 'Finance', 1500, 'FI:093', 'Explain the nature of balance sheets', 'Finance District 2026 #2'),
  ('The Six Sigma model involves continuously implementing activities that', array['stimulate revenue and lessen decision-making.','influence regulation and decrease outputs.','improve quality and reduce inefficiencies.','promote consistency and eliminate resources.'], 2::smallint, 'Improve quality and reduce inefficiencies. Six Sigma is a quality-management framework that involves continuously setting higher goals of perfection. Six Sigma builds upon previous goals to set higher goals in order to continuously improve the quality of the business''s goods, services, or processes. The ultimate goal is to maximize outputs, reduce inefficiencies and waste, have no process or product defects, and minimize production costs. If these actions are successful, the business''s profits may increase. As a quality-control framework, the primary purpose of Six Sigma is not to eliminate resources, lessen decision-making, influence regulation, or decrease outputs.', 'Operations', 'Finance', 1500, 'OP:163', 'Identify quality-control measures', 'Finance District 2026 #3'),
  ('Which of the following is a political factor that might be identified as part of an environmental scan:', array['Increasing tax rates','Changing family roles','Changing laws and regulations','Decreasing interest rates'], 2::smallint, 'Changing laws and regulations. Environmental scanning is the process of collecting information about the environment surrounding your business. Changing laws and regulations is a political factor that might be identified as part of an environmental scan. Decreasing interest rates and increasing tax rates are both economic trends that may be identified as part of an environmental scan. Changing family roles is a society and culture trend.', 'Information Management', 'Finance', 1500, 'NF:015', 'Conduct an environmental scan to obtain business information', 'Finance District 2026 #4'),
  ('High levels of investment in new plants and equipment indicate producers expect a(n)', array['increase in consumer spending.','decrease in consumer spending.','decrease in sales-stock ratio.','shortage of consumer goods.'], 0::smallint, 'Increase in consumer spending. Producers are not willing to build new plants or buy new equipment unless they feel the economy is growing and expanding. The expansion phase of a business cycle is a time of economic prosperity. When there is a shortage of consumer goods, demand has exceeded supply, and the business cycle has peaked. A decrease in consumer spending and a decrease in sales-to-stock ratio occur in a period of economic contraction.', 'Economics', 'Finance', 1500, 'EC:018', 'Determine the impact of business cycles on business activities', 'Finance District 2026 #5'),
  ('Which of the following situations is an example of an employee taking action to increase sales:', array['Poppy orders additional inventory from a vendor who was offering deep discounts for a limited time.','Kevin advises a customer that shipping charges will increase 5% for orders over $1,000.','Annabelle calls on her customers to determine if they need additional products.','Nigel increases the markup of the company''s primary product from 25% to 35%.'], 2::smallint, 'Annabelle calls on her customers to determine if they need additional products. A company should communicate its business goals to its employees, so the employees understand how their work contributes to the company''s growth and well-being. A sales goal is just one of many types of company goals. Sales are critical to the company''s financial well-being because they generate income and profit for the company. Annabelle is taking action to increase sales because she is calling on her customers with the goal of making sales that meet their needs. Kevin is advising a customer about a policy change. Although Poppy is taking advantage of lower prices by ordering additional inventory, there is no guarantee that the inventory will sell. Increasing prices may increase the profit margin, but it doesn''t result in higher sales. In fact, if the prices are too high, customers may not purchase the product, and sales may decrease.', 'Marketing', 'Finance', 1500, 'MK:015', 'Discuss actions employees can take to achieve the company''s desired results', 'Finance District 2026 #6'),
  ('Gabriel''s boss just assigned him a new project. He must create a video presentation, which he has no idea how to do. He feels discouraged, but then reminds himself that this is an opportunity to learn an important new skill. This is an example of which step for maintaining a positive attitude:', array['Look good.','Have a sense of humor.','Think positively.','Surround yourself with positive people.'], 2::smallint, 'Think positively. Gabriel''s behavior in this situation illustrates the step "think positively" in the list of steps to maintain a positive attitude. Gabriel found the good aspects of what seemed like a bad situation, and this allowed him to turn his problem into an opportunity. While having a sense of humor, looking good, and surrounding yourself with positive people are all important steps towards maintaining a positive attitude, they aren''t shown in Gabriel''s actions.', 'Emotional Intelligence', 'Finance', 1500, 'EI:019', 'Exhibit a positive attitude', 'Finance District 2026 #7'),
  ('Ethical behavior is crucial for entrepreneurial success because', array['investors only support unethical companies.','unethical behavior is usually more profitable.','customers expect companies to act ethically.','the public generally distrusts entrepreneurs.'], 2::smallint, 'Customers expect companies to act ethically. It''s never easy to win customers'' trust and support—but in today''s competitive market, it''s harder than ever for new companies to stand out from the crowd. Customers increasingly expect the companies that they support to act in the best interest of their communities, the environment, and the world. As a result, many entrepreneurs spend valuable time and resources trying to develop ethical workplace cultures that will help them distinguish their companies from the competition. It is not true that investors only support unethical companies; many investors will only support companies that demonstrate a commitment to ethics. The public does not generally distrust entrepreneurs—and although unethical behavior may be profitable in the short term, it is unsustainable and bad for business in the long term.', 'Entrepreneurship', 'Finance', 1500, 'EN:044', 'Describe the use of business ethics in entrepreneurship', 'Finance District 2026 #8'),
  ('During a job interview, what should an applicant do to be able to answer the interviewer''s questions adequately?', array['Dress appropriately.','Listen carefully.','Talk rapidly.','Respond quickly.'], 1::smallint, 'Listen carefully. To answer questions adequately, an applicant should listen carefully to the interviewer. The applicant needs to understand exactly what the interviewer is asking. By listening carefully, an applicant will be able to respond with the proper information. Talking rapidly and responding quickly will not help applicants answer questions adequately. Applicants should dress appropriately for job interviews, but that will not help them answer questions unless they listen carefully and understand what is being asked.', 'Professional Development', 'Finance', 1500, 'PD:028', 'Interview for a job', 'Finance District 2026 #9'),
  ('Sometimes a good decision maker will accept the risks associated with a decision because', array['the risks will have no negative impact.','they have no way to evaluate the risks.','they don''t have any information about them.','they will be able to reach an important goal.'], 3::smallint, 'They will be able to reach an important goal. Decision makers often accept risks when the benefits of achieving the goal outweigh the cost of those risks. A good decision maker uses a systematic process to evaluate risks. Risks are analyzed and accepted based on information, not on the absence of it. All risks have the potential for a negative impact.', 'Emotional Intelligence', 'Finance', 1500, 'EI:091', 'Assess risks of personal decisions', 'Finance District 2026 #10'),
  ('When creating a cash flow statement, which of the following is included in a business''s cash paid out:', array['Ending cash balance','Sale of assets','Cash receipts','Cost of goods'], 3::smallint, 'Cost of goods. Cash paid out includes all cash payments which include costs of goods, fixed expenses, and variable expenses on a cash flow statement. Ending cash balance is determined by subtracting cash paid out from the total cash available. Cash receipts are included in the cash receipts portion of the cash flow statement. Sale of assets represent a source of cash receipts on the cash flow statement.', 'Financial Analysis', 'Finance', 1500, 'FI:091', 'Describe the nature of cash flow statements', 'Finance District 2026 #11'),
  ('Price indicates how much value is placed on a good, service, or resource by the', array['seller.','merchant.','consumer.','sales manager.'], 2::smallint, 'Consumer. The consumer uses the good, service, or resource. How much the consumer values the good, service, or resource directly influences the price set for the particular item. If consumers value an item highly, they will be willing to pay more for it. Sales managers, sellers, and merchants may set prices, but consumers decide if those prices indicate a good value.', 'Economics', 'Finance', 1500, 'EC:006', 'Describe the functions of prices in markets', 'Finance District 2026 #12'),
  ('What is the first step you should take when planning a project?', array['Determine quality standards.','Identify the project''s stakeholders.','Identify resources.','Develop a draft plan.'], 1::smallint, 'Identify the project''s stakeholders. The first step is to figure out who else is involved in the project—the project''s stakeholders. Identifying the project''s stakeholders is the first step because you do not want to start planning any other aspects of the project without getting their input and including them in the process. Before you determine quality standards, identify resources, or develop a draft plan, you need to identify the project''s stakeholders so they will be considered throughout these other steps.', 'Operations', 'Finance', 1500, 'OP:519', 'Plan project', 'Finance District 2026 #13'),
  ('Which of the following situations is an example of an employee exhibiting unethical behavior:', array['Scheduling a two-week vacation','Clocking out at the end of the day','Taking a day of sick leave to play golf','Working four 10-hour days to shorten the week'], 2::smallint, 'Taking a day of sick leave to play golf. Employees usually are allowed a certain number of sick days to be used in the event of health or medical problems. Employers expect employees to use sick days for legitimate reasons. It is considered unethical for an employee to use a sick day for recreational activities or vacation. Clocking out at the end of the day is standard practice in many businesses. Employees may schedule vacation for the length of time they are entitled, which may be two weeks. Many businesses allow employees to work four 10-hour days, which amounts to a 40-hour week.', 'Emotional Intelligence', 'Finance', 1500, 'EI:004', 'Demonstrate ethical work habits', 'Finance District 2026 #14'),
  ('Prior to finalizing a purchase, both parties involved agree not to disclose information about the other party and sign a document. In this scenario, both parties signed a(n)', array['kickback.','exclusive agreement.','confidentiality agreement.','labor contract.'], 2::smallint, 'Confidentiality agreement. A confidentiality agreement is a legally binding promise not to disclose information about another party. Because both parties agreed not to disclose information about the other party in this scenario, this is an example of a confidentiality agreement. A kickback is an illegal payment or bribe paid in return for securing a contract. An exclusive agreement is an illegal agreement that forbids customers from buying goods and services from competitors. A labor contract is an agreement between a union and a company outlining the wages, fringe benefits, working conditions, and rules under which employees will work.', 'Operations', 'Finance', 1500, 'OP:246', 'Discuss the importance of utilizing ethical purchasing methods', 'Finance District 2026 #15'),
  ('Income from sales, cost of goods sold, gross profit on sales, operating expenses, and net profit or loss are all part of a(n)', array['sales budget.','income statement.','balance sheet.','marketing plan.'], 1::smallint, 'Income statement. An income statement is a financial summary that shows how much money the business has made or lost. It is also called a profit-and-loss statement. A balance sheet shows a firm''s assets, liabilities, and owner''s equity. A marketing plan is a set of procedures or strategies for attracting the target customer to the business. A sales budget is an estimate of expenditures related to sales.', 'Financial Analysis', 'Finance', 1500, 'FI:094', 'Describe the nature of income statements', 'Finance District 2026 #16'),
  ('Which of the following examples best illustrates someone practicing "not knowing":', array['Louis doesn''t look up unknown information on his phone right away.','Sandy tries driving along the back roads instead of taking the highway.','Rosa practices deep breathing and other relaxation techniques.','Parviz makes a list of all of the things that he cannot control.'], 0::smallint, 'Louis doesn''t look up unknown information on his phone right away. Tolerating ambiguity is all about being comfortable with not knowing what will happen or what the correct action is. If you can get comfortable with the unknown, however, you won''t try to fill in the blanks with wrong or incomplete information. Louis is allowing himself to accept the unknown without quickly trying to figure out the answer. Sandy''s drive along back roads instead of the highway is an example of stepping out of her comfort zone rather than practicing not knowing. Parviz is doing a reality check rather than practicing not knowing. Finally, Rosa is practicing mindfulness rather than practicing not knowing.', 'Emotional Intelligence', 'Finance', 1500, 'EI:092', 'Develop tolerance for ambiguity', 'Finance District 2026 #17'),
  ('When preparing income tax documents for clients who have placed trust in them, accountants have a responsibility to', array['have conflicts of interest.','act in the best interests of those clients.','be as subjective as possible.','put their own interests before those of the clients.'], 1::smallint, 'Act in the best interests of those clients. Fiduciaries have a legal obligation to act in the best interest of their clients. Accountants are not always considered fiduciaries, but they typically are when they are performing services like tax services and business consulting. In these situations, accountants should be objective, not have conflicts of interest, and put their own interests aside in favor of their clients'' interests.', 'Financial Analysis', 'Finance', 1500, 'FI:353', 'Explain legal considerations for accounting', 'Finance District 2026 #18'),
  ('A company that sells securities to the public must', array['guarantee that securities will always be valuable.','discourage investors from asking questions.','tell investors about the risks of these securities.','avoid selling risky securities.'], 2::smallint, 'Tell investors about the risks of these securities. Companies that sell securities have to tell the truth about the securities they sell. They must be honest about their business and the risks of securities. Securities cannot be guaranteed because they always involve some degree of risk. Investors should ask questions and do research on securities; a company should not discourage them from doing so.', 'Financial Analysis', 'Finance', 1500, 'FI:356', 'Explain legal considerations for finance', 'Finance District 2026 #19'),
  ('During a brainstorming session, should participants be allowed to add new ideas to the list that are based on another group member''s idea?', array['Yes; ideas that are too outrageous should be immediately modified.','No; it can be interpreted as a poor evaluation of the idea.','No; using someone else''s idea is considered stealing.','Yes; other participants'' ideas can trigger new ideas.'], 3::smallint, 'Yes; other participants'' ideas can trigger new ideas. This process is called stepping-stones or triggers, and it is encouraged in brainstorming because one person''s ideas can easily trigger new and different ideas. It is not considered stealing, but instead is an important part of working together to build on each other''s ideas to find more ideas. Adding a stepping-stone idea to a brainstorming list is not a form of evaluating the original ideas. All ideas are considered equal in a brainstorming session, including those that are very outlandish or outrageous.', 'Communication Skills', 'Finance', 1500, 'CO:061', 'Defend ideas objectively', 'Finance District 2026 #20'),
  ('Some businesses try to decrease expenses and increase profits in the customer service area by', array['improving service quality.','offering competitive services.','adding free services.','eliminating free services.'], 3::smallint, 'Eliminating free services. Eliminating or reducing the number of services that are offered to customers free of charge reduces the business''s expenses, which should help increase its profits. Many businesses have eliminated such free services as delivery and gift wrapping, or they offer these services for a fee. Adding free services, improving service quality, and offering competitive services are likely to increase expenses.', 'Economics', 'Finance', 1500, 'EC:010', 'Identify factors affecting a business''s profit', 'Finance District 2026 #21'),
  ('Budgets can be described in terms of', array['desires, debt, and discipline.','money, maps, and management.','account books, bills, and bankruptcy.','savings, sales, and success.'], 1::smallint, 'Money, maps, and management. Budgets can be described in terms of money, maps, and management. Budgets are about money, can be compared to maps, and are great management tools. Account books, bills, and bankruptcy; desires, debt, and discipline; and savings, sales, and success are all related to certain aspects of budgeting, but none describes its main characteristics as well as money, maps, and management.', 'Financial Analysis', 'Finance', 1500, 'FI:106', 'Describe the nature of budgets', 'Finance District 2026 #22'),
  ('Why are ethics especially important to those who work in finance?', array['Ethics prevent companies from ever losing money.','Ethics challenge companies to reduce operating expenses.','Unethical behavior in finance leads to catastrophic results.','People who work in finance are naturally unethical.'], 2::smallint, 'Unethical behavior in finance leads to catastrophic results. Ethics are incredibly important in finance because of the damaging effects that unethical financial practices can have on companies, their employees and customers, and the economy as a whole. People who work in finance are not naturally unethical. Ethics do not necessarily challenge companies to reduce operating expenses, nor do they prevent them from ever losing money.', 'Financial Analysis', 'Finance', 1500, 'FI:355', 'Discuss the role of ethics in finance', 'Finance District 2026 #23'),
  ('The price of raw materials used in manufacturing a product was double what had been projected for the year. Which of the following could the business determine by analyzing its financial informati on:', array['Errors in forecasting','Supply and demand','Equipment costs','Variances'], 3::smallint, 'Variances. Businesses analyze their financial information to determine the differences between what they had forecast and what actually happened. By doing this, they can account for those differences and improve future forecasts. In this scenario, equipment costs were not a factor. The business could not determine from its financial information whether the supply of raw materials decreased or demand increased. Forecasts are estimates based on information known at the time the forecast was made and will not be exactly what actually happens. In this scenario, therefore, the variances would not be considered forecasting errors.', 'Financial Analysis', 'Finance', 1500, 'FI:579', 'Describe the need for financial information', 'Finance District 2026 #24'),
  ('A collection letter that a business writes to customers to encourage them to pay is an example of a(n) __________ message.', array['persuasive','informational','aggressive','threatening'], 0::smallint, 'Persuasive. A collection letter is a type of persuasive message that many businesses write to customers who are delinquent in making payments on their accounts. The purpose of the collection letter is to persuade customers to send payment or to contact the business to make some type of arrangement. Collection letters should not be threatening or overly aggressive because they may offend customers rather than encourage them to respond immediately. Although a collection letter contains information, it is not considered to be an informational message.', 'Communication Skills', 'Finance', 1500, 'CO:031', 'Write persuasive messages', 'Finance District 2026 #25'),
  ('An important aspect of upholding ethical accounting standards involves the ability to be', array['intolerant.','resourceful.','unconventional.','objective.'], 3::smallint, 'Objective. Accountants prepare the accounting information that businesses use to make financial decisions. Therefore, it is important for accountants to uphold the ethical standards of their profession by providing accurate, objective (unbiased) financial information. A person who uses unique processes or creativity to achieve a goal is being resourceful. Accountants need to follow the GAAP to perform their jobs rather than use unique processes. An intolerant person is prejudiced. An unconventional person is often viewed as unusual or eccentric.', 'Financial Analysis', 'Finance', 1500, 'FI:351', 'Discuss the role of ethics in accounting', 'Finance District 2026 #26'),
  ('A group of business employees getting together to share ideas to solve problems is an example of', array['visualizing.','concept mapping.','brainstorming.','role-playing.'], 2::smallint, 'Brainstorming. Brainstorming is a creative thinking technique involving the identification of as many different ideas as possible during a certain time frame. Brainstorming can be done by one person but is used most often in a group setting, such as business employees getting together to share ideas in order to solve problems. Businesses often encourage employees to brainstorm to generate new approaches and solutions. Role-playing involves acting out a situation. Concept mapping involves drawing a map of your ideas so that you can see how one idea relates to another. Visualizing involves picturing something in your mind.', 'Professional Development', 'Finance', 1500, 'PD:012', 'Demonstrate appropriate creativity', 'Finance District 2026 #27'),
  ('Which of the following payment methods relies on radio frequency identification (RFID) or near field communication (NFC) technology to make secure payments:', array['Money orders','Contactless purchasing','Wire transfers','Electronic funds transfer (EFT)'], 1::smallint, 'Contactless purchasing. Contactless purchasing uses credit or debit cards that are stored electronically in someone''s digital wallet. It relies on radio frequency identification (RFID) or near field communication (NFC) to make secure payments. Neither money orders, electronic funds transfer (EFT), nor wire transfers use RFID or NFC technology to make payments.', 'Financial Analysis', 'Finance', 1500, 'FI:058', 'Explain forms of financial exchange (cash, credit, debit, electronic funds transfer, etc.)', 'Finance District 2026 #28'),
  ('Management is divided into major functions, two of which are', array['controlling and directing.','analyzing and planning.','staffing and supervising.','organizing and producing.'], 0::smallint, 'Controlling and directing. Controlling is the management function that monitors the work effort. It evaluates an organization''s performance and corrects problems, if necessary. Directing is the management function that provides guidance to workers and work projects so that they can help the business meet its goals. The other management functions are staffing (finding qualified employees to perform job tasks); organizing (deciding how the work required by an organization will be divided); and planning (deciding what will be done in an organization and how it will be accomplished). Supervising, producing, and analyzing are not management functions.', 'Strategic Management', 'Finance', 1500, 'SM:001', 'Explain the concept of management', 'Finance District 2026 #29'),
  ('Which of the following is a technique you can use to demonstrate a positive attitude over the phone:', array['Be informed about your business''s rules.','Smile when you answer the phone.','Use a wide vocabulary in conversations.','Shut out all distractions while talking.'], 1::smallint, 'Smile when you answer the phone. Your attitude is projected over the phone. A smile or a frown can actually be heard in your voice by the person on the other end of the line. A smile indicates a positive attitude, and a frown indicates a negative attitude. Using a wide vocabulary, being informed about the business''s rules, and shutting out distractions while you are talking to a caller are all helpful in providing service, but they are not ways to demonstrate a positive attitude.', 'Communication Skills', 'Finance', 1500, 'CO:114', 'Handle phone calls in a businesslike manner', 'Finance District 2026 #30'),
  ('What type of information in a company''s CRM system can help a company determine a customer''s product preferences?', array['Customer''s address','Customer''s prior purchases','Customer''s preferred payment method','Customer''s name'], 1::smallint, 'Customer''s prior purchases. A CRM system can keep records of sales history, which can help a company determine a customer''s product preferences. CRM systems also store many other types of data such as a customer''s contact and payment methods. A customer''s name, address, or preferred payment method provides very few clues to determine their product preferences.', 'Information Management', 'Finance', 1500, 'NF:014', 'Monitor internal records for business information', 'Finance District 2026 #31'),
  ('Allen works in an ice-cream shop that makes fresh ice cream throughout the day, and he sells it to customers as they come in. Because Allen does both jobs, he has a limited amount of time to attend to customers as well as make the ice cream. His employer decides to hire another worker who will only make the ice cre am, allowing Allen to work at the counter full time. In other words, Allen''s employer has decided to employ specialization by', array['task.','time.','seniority.','day.'], 0::smallint, 'Task. Allen is only working at the counter. Because he works at the counter all the time and does not trade shifts with the new worker, he is not specializing by time or day. Seniority in this case has little to do with specialization because Allen''s specific task was decided by the employer.', 'Economics', 'Finance', 1500, 'EC:014', 'Analyze impact of specialization/division of labor on productivity', 'Finance District 2026 #32'),
  ('One of the benefits to you of receiving feedback on the job is that it', array['makes you feel like a valued employee.','lets you know how you are doing.','helps you understand the supervisor.','raises your level of self-esteem.'], 1::smallint, 'Lets you know how you are doing. Feedback on the job lets you know whether you are exceeding, meeting, or falling short of the business''s expectations. It lets you know whether you should continue as you are or change. Only positive feedback would raise your self-esteem or make you feel valued. Feedback is not intended to help you understand your supervisor.', 'Emotional Intelligence', 'Finance', 1500, 'EI:003', 'Explain the use of feedback for personal growth', 'Finance District 2026 #33'),
  ('What is one reason why businesses write informational messages?', array['To explain new policies','To analyze sales proposals','To obtain positive feedback','To develop research reports'], 0::smallint, 'To explain new policies. One of the main functions of an informational message is to provide information to readers in such a way that they understand the message. A type of written information that businesses often provide to customers is an explanation of new policies and how those policies will affect customers. For example, if a business is changing its credit policy, it wants to inform customers about the change and let them know that the change will benefit them. Research reports are an in-depth study of a specific business problem or situation. Businesses write informational messages to inform rather than to obtain feedback. Analyzing sales proposals involves reviewing information.', 'Communication Skills', 'Finance', 1500, 'CO:039', 'Write informational messages', 'Finance District 2026 #34'),
  ('Natural disasters like tornadoes, earthquakes, and floods are considered __________ risks.', array['strategic','operational','hazard','financial'], 2::smallint, 'Hazard. Hazard risks are potential events or situations that can cause injury or harm to people, property, or the environment. Most hazard risks can only cause business losses, not gains. Types of hazard risks include natural disasters, like tornadoes, earthquakes, floods, blizzards, hurricanes, and wildfires. Operational risks are the possible events and situations that can result from employee actions, core processes, and daily business activities. Strategic risks often concern the overall business environment, economic or political issues, or the company''s objectives. Financial risks are possible events or situations that directly influence a company''s cash flow.', 'Economics', 'Finance', 1500, 'EC:011', 'Determine factors affecting business risk', 'Finance District 2026 #35'),
  ('The first task in creating a risk-management plan is', array['identifying as many known risks as possible.','figuring out how team members will communicate.','determining how to avoid risks.','strategizing for limiting the impact of risks.'], 0::smallint, 'Identifying as many known risks as possible. The first task in creating a risk-management plan is identifying as many known risks as possible. After that, project managers can determine how to avoid those risks or limit their potential impact. Figuring out how team members will communicate is a task for the communications plan.', 'Operations', 'Finance', 1500, 'OP:001', 'Develop project plan', 'Finance District 2026 #36'),
  ('Cash register tape is an example of a(n)', array['supply.','equipment.','service.','material.'], 0::smallint, 'Supply. Supplies are industrial goods that are constantly being purchased and used up in the operation of a business. Materials are industrial goods that become part of the finished product after they have been processed. Equipment is industrial goods used in the operation of a business, but not used in the actual production of a good or service. Cash register tape is a tangible good rather than an intangible service.', 'Economics', 'Finance', 1500, 'EC:002', 'Distinguish between economic goods and services', 'Finance District 2026 #37'),
  ('When people desire to fit in with the crowd and just do what everyone else is doing, they are displaying', array['herd mentality.','status quo bias.','groupthink.','risk-taking behavior.'], 0::smallint, 'Herd mentality. When people just follow others without thinking, they are demonstrating herd mentality. Status quo bias refers to a preference to maintain the status quo and the view that a change from it is a loss. Risk- taking behavior refers to risky activities one might participate in. Groupthink refers to a process that occurs when bad decisions are made by a group because the group''s members fear expressing opinions or suggesting ideas that others may disagree with.', 'Emotional Intelligence', 'Finance', 1500, 'EI:134', 'Challenge the status quo', 'Finance District 2026 #38'),
  ('Which of the following scenarios is an example of selling an idea:', array['Leonard University provides all incoming students with a brand new computer.','Your teacher tells the class to read pages 30-45 in your textbook for homework.','The local fire department holds a popular holiday toy drive every year.','You convince your parents to give you and your siblings a weekly allowance.'], 3::smallint, 'You convince your parents to give you and your siblings a weekly allowance. This is an example of idea selling because it involves convincing another party to go along with an idea or proposal. A teacher assigning homework, a fire department hosting a toy drive, and a university providing students with computers are not examples of idea selling because they do not involve convincing other people to buy into an idea.', 'Emotional Intelligence', 'Finance', 1500, 'EI:108', '"Sell" ideas to others', 'Finance District 2026 #39'),
  ('Consumers can borrow against future income to make current purchases by making use of', array['credit.','money orders.','interest.','certificates of deposit.'], 0::smallint, 'Credit. Credit is the arrangement by which businesses or individuals can purchase now and pay later. Money orders are purchased at banks, post offices, or stores to be used as checks. Certificates of deposit are savings certificates. Interest is the fee lenders charge borrowers for the use of credit.', 'Financial Analysis', 'Finance', 1500, 'FI:002', 'Explain the purposes and importance of credit', 'Finance District 2026 #40'),
  ('Talia manages a business''s accounts payable, accounts receivable, inventory, and cash. Talia is responsible for', array['the business''s capital structure.','market risk management.','working capital management.','capital investment decisions.'], 2::smallint, 'Working capital management. An organization''s finance function is responsible for managing the business''s working capital and making capital investment decisions for the company. Working capital is the difference between a business''s current assets and current liabilities. Working capital management focuses on the company''s current balance of assets and liabilities and involves the management of accounts payable and receivable, inventory, and cash. Working capital management involves decisions made for the short-term—one year or less. Capital investment decisions determine which projects the business will invest in, how the investment(s) will be financed, and whether or not to pay dividends to the company''s shareholders. The business''s capital structure consists of the mix of debt and equity financing used to finance investments and projects. Market risk is the risk of financial loss due to the decreased value of an investment, and market risk management involves using financial instruments to manage exposure to market risk. Capital investment decisions, the business''s capital structure, and market risk management are typically long-term in nature. Talia is not responsible for capital investment decisions, the business''s capital structure, or market risk management.', 'Financial Analysis', 'Finance', 1500, 'FI:354', 'Explain the role of finance in business', 'Finance District 2026 #41'),
  ('An organization with a quality culture would have executive-level managers who are', array['good at delegating all commitments for quality assurance.','able to enlist the expertise of outside contractors for quality.','committed and involved and take responsibility for quality.','flexible, indifferent, and not responsible for quality.'], 2::smallint, 'Committed and involved and take responsibility for quality. Executive-level managers are both committed and involved. They take responsibility for quality and do not delegate that responsibility. This is a characteristic shared by organizations with a quality culture. The alternatives remove the responsibility for quality from the executive-level manager and delegate it to others.', 'Operations', 'Finance', 1500, 'OP:019', 'Describe crucial elements of a quality culture', 'Finance District 2026 #42'),
  ('How can human resources managers foster fairness in the hiring process?', array['By refusing to interview candidates with certain backgrounds','By asking applicants to reveal their marital status','By implementing racial screening in the hiring process','By using the same hiring process for all applicants'], 3::smallint, 'By using the same hiring process for all applicants. Human resources professionals can foster fairness in the hiring process by using the same process consistently, meaning that all applications and interviews are handled in the same manner. Asking applicants to reveal their marital status, implementing racial screening, and refusing to interview candidates with certain backgrounds are all illegal business practices that do not foster fairness.', 'Human Resources Management', 'Finance', 1500, 'HR:411', 'Explain the role of ethics in human resources management', 'Finance District 2026 #43'),
  ('Behavior that is characterized by a willingness to ignore the rights of others and exploit them to achieve personal goals is __________ behavior.', array['offensive','passive','assertive','aggressive'], 3::smallint, 'Aggressive. Aggressive behavior is characterized by a willingness to ignore the rights of others and exploit them to achieve personal goals. Offensive behavior is unpleasant or displeasing. Assertive behavior is characterized by respect for personal rights as well as for the rights of others. Passive behavior is characterized by a failure to exercise personal rights and a lack of respect for personal needs.', 'Emotional Intelligence', 'Finance', 1500, 'EI:008', 'Use appropriate assertiveness', 'Finance District 2026 #44'),
  ('Which of the following currencies is considered decentralized:', array['Cryptocurrency','Swiss franc','The euro','U.S. dollar'], 0::smallint, 'Cryptocurrency. Cryptocurrencies are not tied to any country so they are considered to be decentralized. Currencies that are controlled by a country are considered centralized currencies. The euro is controlled by several European countries. The U.S. dollar is the official currency of the United States. The Swiss franc is the official currency of Switzerland.', 'Financial Analysis', 'Finance', 1500, 'FI:059', 'Identify types of currency (paper money, coins, banknotes, government bonds, treasury', 'Finance District 2026 #45'),
  ('Which of the following is a way for employers to prevent recordkeeping or payroll fraud:', array['Require sales staff to observe customers on the selling floor','Divide cash-related responsibilities among different employees','Train salespeople to be familiar with prices','Provide procedures for the personal use of office supplies'], 1::smallint, 'Divide cash-related responsibilities among different employees. Employers generally divide up cash-related responsibilities among employees so that one employee checks the records of another. This reduces the possibility that a dishonest employee can steal by changing the cash records. Training salespeople to be familiar with prices is a technique that helps reduce price-ticket switching. Providing procedures for the personal use of office supplies will help reduce pilferage. Requiring sales staff to observe customers on the selling floor will help prevent shoplifting.', 'Operations', 'Finance', 1500, 'OP:013', 'Explain routine security precautions', 'Finance District 2026 #46'),
  ('What function of money enables a person to save their wealth until it is needed?', array['Incentive','Unit of measure','Store of value','Medium of exchange'], 2::smallint, 'Store of value. Money serves as a store of value because it enables individuals to save or store their wealth (in the form of money) easily and compactly. Money serves as a medium of exchange when it is used to obtain goods and services. When it is used to express the value or worth of something, money serves as a unit of measure. Money can also act as an incentive. An incentive is a motivator—something that encourages individuals to behave in a particular way.', 'Financial Analysis', 'Finance', 1500, 'FI:060', 'Describe functions of money (medium of exchange, unit of measure, store of value)', 'Finance District 2026 #47'),
  ('You offer to cover a coworker''s shift on Saturday. When a friend asks you to hang out that night, you tell them that you have to work. Which trust-building technique are you demonstrating?', array['Taking responsibility for your mistakes','Keeping your promises','Communicating often and openly','Not sharing confidential information'], 1::smallint, 'Keeping your promises. Perhaps the most important thing you can do to build trust is to keep your promises. If you don''t do what you say you''ll do, it''s difficult for others to count on you. If you promise to cover a coworker''s shift, you can build trust by keeping your promise. Communicating often and openly, not sharing confidential information, and taking responsibility for your mistakes are other techniques used to build trust.', 'Emotional Intelligence', 'Finance', 1500, 'EI:128', 'Build trust in relationships', 'Finance District 2026 #48'),
  ('Joel, a car salesman, purposely adjusts his communication style to mirror the habits of his customers. He finds that customers are more comfortable talking to someone that communicates in a familiar way. In other words, Joel is', array['tricking his customers.','building rapport.','being dishonest.','subduing his own personality.'], 1::smallint, 'Building rapport. One of the most effective ways to build rapport is by mirroring—matching your communication style to that of your audience. Customers generally feel more comfortable when salespeople communicate in ways that are familiar to them. Mirroring is not dishonest or a way to trick customers—it is simply a communication strategy. Joel is not necessarily subduing his own personality in this example; rather, he is matching his communication style to that of his customers.', 'Communication Skills', 'Finance', 1500, 'CO:084', 'Employ communication styles appropriate to target audience', 'Finance District 2026 #49'),
  ('Amir has a steady job, but he decides to increase his income by taking aerial photographs with his drone and selling them on his own website. His side business becomes very profitable, and he earns well over $2,000 each month. Amir''s side business is so successful that it significantly increases his', array['unearned income.','commission.','earned income.','wages.'], 2::smallint, 'Earned income. Since Amir is making a substantial amount of money each month, it would be considered earned income and is subject to taxes. Unearned income refers to money made from interest, rents, dividends or transfer payments. Commission is earned income made from set fees or a percentage of sales paid to an employee or contractor. Wages refer to payment exchanged for hours worked.', 'Financial Analysis', 'Finance', 1500, 'FI:061', 'Describe sources of income and compensation', 'Finance District 2026 #50'),
  ('Which of the following capabilities would be most useful when using budgeting applications:', array['Allowing overspent budgets to smoothly move through the system','Deleting files from the prior year automatically','Selecting records to audit at random','Creating unlimited scenarios to depict the impact of decisions'], 3::smallint, 'Creating unlimited scenarios to depict the impact of decisions. When using budgeting applications, users can benefit by creating a variety of "what-if" scenarios in order to develop the most realistic budget. Automatic deletion of files would be a disadvantage since the prior year''s budget is used in developing the future budget. An audit trail should be maintained on all data entries rather than audits occurring at random. An effective budgeting application would set limits on how much over budget an account can go and flag the overage so that steps can be taken to handle the situation.', 'Financial-Information Management', 'Finance', 1500, 'FM:013', 'Demonstrate budgeting applications', 'Finance District 2026 #51'),
  ('What is the first step in designing a multi-table query?', array['Determine the criteria.','Set the correct join direction.','Pinpoint exactly what you want to know.','Locate the correct tables.'], 2::smallint, 'Pinpoint exactly what you want to know. To create a successful multi-table query, the first step is figuring out exactly what question you want the database to answer. If you aren''t exactly sure what you want to know, the database cannot provide you with the information you need. Determining the criteria for the query, locating the correct tables, and setting the correct join direction are all important steps to take before creating the query, but none of them will be successful unless the exact question has been determined first.', 'Information Management', 'Finance', 1500, 'NF:124', 'Demonstrate advanced database applications', 'Finance District 2026 #52'),
  ('A flood has caused damage to a company''s inventory warehouse. This is an example of what type of risk that enterprise risk management addresses?', array['Security','Legal','Strategic','Operational'], 3::smallint, 'Operational. Enterprise risk management (ERM) is an organization-wide strategy to identify, assess, and prepare for potential dangers and hazards that may harm or interfere with an organization''s finances, operations, and objectives. ERM addresses several types of risk, including operational, security, strategic, legal, financial, and compliance risk. This scenario is an example of operational risk, which threatens the day-to-day activities required for a company to operate. Security risk threatens a company''s physical or digital assets, such as inadequate controls over sensitive customer information stored on network servers. Strategic risk threatens a company''s long-term plan. Legal risk threatens a company if it faces a lawsuit or penalty of any sort.', 'Risk Management', 'Finance', 1500, 'RM:062', 'Discuss the nature of enterprise risk management (ERM)', 'Finance District 2026 #53'),
  ('When individuals purchase items such as high-performance sports cars, rare collectibles, and jewelry containing large, precious gemstones, they must often pay __________ taxes.', array['estate','gift','property','luxury'], 3::smallint, 'Luxury. Governments increase their revenues by charging taxes on nonessential, often very expensive goods and services, such as high-end automobiles, rare collectibles, and jewelry. This type of tax is called a luxury tax. An individual who receives a certain amount of money as a gift may be required to pay a gift tax. Property taxes are paid on buildings (e.g., homes) and land. A person who inherits some or all of a deceased person''s assets pays an estate tax, which is based on the net value of the assets or estate.', 'Business Law', 'Finance', 1500, 'BL:134', 'Discuss the effect of tax laws and regulations on financial transactions', 'Finance District 2026 #54'),
  ('Which of the following is an impact of introducing compliance technology into a business:', array['It reduces a company''s overall efficiency.','It increases the likelihood of a data breach.','It replaces living specialists from a company.','It identifies patterns and trends in a company.'], 3::smallint, 'It identifies patterns and trends in a company. Introducing compliance technology into a business has several positive impacts. This includes identifying patterns and trends in a company, which can lead to a more competent risk assessment. Compliance technology cannot and should not replace living specialists in a company. For example, a computer can analyze information and draw conclusions from it, but it is up to the specialist to determine what to do with these conclusions. Compliance technology will improve a company''s overall efficiency, not reduce it. Compliance technology increases the protection of a company''s private data and information and decreases the likelihood of a data breach.', 'Business Law', 'Finance', 1500, 'BL:149', 'Describe the use of technology in compliance', 'Finance District 2026 #55'),
  ('Which of the following is responsible for creating and reviewing corporate governance policies for a business:', array['Board of accountancy','Board of managers','Board of directors','Board of elections'], 2::smallint, 'Board of directors. A corporation''s board of directors is responsible for approving and reviewing the corporate governance policies of the business. These corporate governance policies specify the guidelines and rules by which a corporation is directed and run. The boards of elections are local organizations that help run local elections. The board of accountancy regulates accounting practices. A board of managers runs day-to-day operations in a business and would typically not be involved in creating and reviewing corporate governance policies.', 'Professional Development', 'Finance', 1500, 'PD:213', 'Discuss the importance of corporate governance in business', 'Finance District 2026 #56'),
  ('What does the "open" column of a stock table tell you?', array['The first price at which the stock was sold on a given day','The number of shares of a stock traded in a given day','The relationship between the price of a stock and company earnings','The lowest price at which the stock was sold this year'], 0::smallint, 'The first price at which the stock was sold on a given day. A stock table provides valuable information to investors. In the "open" column of a stock table, you can see the first price at which a certain stock was sold on a certain day when the markets open. The lowest price at which a stock was sold this year can be found in the "52-week low" column. The number of shares traded in a given day can be found in the "volume" column. The relationship between the price of a stock and company earnings can be found in the "P/E ratio" column.', 'Financial Analysis', 'Finance', 1500, 'FI:275', 'Interpret securities table', 'Finance District 2026 #57'),
  ('Chris purchased 500 shares of microcap HRR stock. Then, he posted false information about HRR on several investment websites to hype up the stock. After driving up the price of HRR stock, Chris quickly sold all of his stock in the company and earned a large profit. The price of the stock then fell, leaving HRR investors with worthless stock. What type of investment scam did Chris commit?', array['Ponzi scheme','Pump and dump','Phishing','Pyramid scheme'], 1::smallint, 'Pump and dump. Pump and dump is an investment scam that takes place mostly online. It typically involves scammers who buy a small stock and then hype it up to other investors, causing its price to rise. The scammers sell when the price is high, leaving the victims to deal with the rapid price decline afterwards. A pyramid scheme is an illegal form of multi-level marketing in which emphasis is placed on collecting initial fees from as many people as possible. A Ponzi scheme is an investment scam that lures in new investors by promising high rates of return with little to no risk. Phishing is an online identity-theft scam that fools its victims into believing they are submitting sensitive, personal information (such as credit card numbers or bank passwords) to a legitimate website.', 'Business Law', 'Finance', 1500, 'BL:133', 'Discuss legal considerations in the finance industry', 'Finance District 2026 #58'),
  ('Two potential outcomes of using Six Sigma in finance are that it', array['helps determine financial positioning and increases costs.','lessens inefficiencies and identifies problem areas.','decreases costs and declines the quality of work.','reduces errors and lowers customer satisfaction.'], 1::smallint, 'Lessens inefficiencies and identifies problem areas. Six Sigma''s primary focuses are to reduce variation, lessen defects, and improve quality. When applied to financial information, some of the potential outcomes (or benefits) of using Six Sigma are that it reduces errors and inefficiencies, identifies problem areas, decreases costs, increases customer satisfaction, improves the quality of work, and even helps determine financial positioning. A decline in the quality of work, lowered customer satisfaction, and increased costs are not the targeted outcomes of using Six Sigma in finance.', 'Financial-Information Management', 'Finance', 1500, 'FM:016', 'Discuss non-traditional uses for financial information (e.g., lean, sustainability reporting,', 'Finance District 2026 #59'),
  ('What type of financial firm offers multiple types of financial products using one pool of capital?', array['Consolidated cross-product parent company','Fully integrated financial services provider','Universal bank and trust corporation','Financial holding company'], 1::smallint, 'Fully integrated financial services provider. There are several different types of financial firms that offer integrated financial services. A fully integrated financial services provider offers multiple types of financial products (e.g., loans, insurance, trust services) using one pool of capital. A universal bank is a corporate entity that offers banking products directly to customers but also sells other financial products, especially insurance, through subsidiaries. Each subsidiary has its own pool of capital. A financial holding company, also known as a parent company, owns most or all of the shares of individually incorporated subsidiaries that engage in different types of financial activities. Like subsidiaries of a universal bank, each subsidiary of a financial holding company has its own pool of capital. Universal bank and trust corporations and consolidated cross-product parent companies are fictitious terms.', 'Financial Analysis', 'Finance', 1500, 'FI:573', 'Discuss the nature of convergence/consolidation in the finance industry', 'Finance District 2026 #60'),
  ('Researchers surveyed students at a university to determine what type of credit and debit cards they most commonly use. Upon completion of the survey, all of the data were placed into a spreadsheet. Instead of observing the data as a whole, the researchers want to analyze the data of students that use Discover credit cards, and they do so by breaking the data down into a subset for further analysis. This process is known as', array['data filtering.','a data element.','a data script.','data normalization.'], 0::smallint, 'Data filtering. Data filtering is the process of selecting a smaller part of a data set and using that subset for examination or analysis. Because the researchers wanted to analyze the data of students that use Discover credit cards, they used data filtering. Data normalization is the organization of data to appear similar across all records and fields, and it increases the cohesion of said data. A data element is the fundamental data structure in a data processing system. A data script is a language used to describe and influence binary data formats as types.', 'Information Management', 'Finance', 1500, 'NF:124', 'Demonstrate advanced database applications', 'Finance District 2026 #61'),
  ('Which of the following is a piece of information that is often added to a customer relationship management (CRM) system:', array['Job applications','Product inventory','Sales opportunities','Budget spreadsheets'], 2::smallint, 'Sales opportunities. A customer relationship management system is software that provides businesses with information about their customers and potential customers. CRM systems are used to store information such as sales opportunities so that employees can turn these opportunities into buying customers. CRM systems do not typically include job applications, product inventory, or budget spreadsheets because these aspects of the business are not related to customers.', 'Customer Relations', 'Finance', 1500, 'CR:024', 'Use Customer Relationship Management (CRM) technology', 'Finance District 2026 #62'),
  ('Spreadsheets, database applications, and other software are often used by businesses for', array['employee recognition.','financial analysis.','staff communication.','public relations.'], 1::smallint, 'Financial analysis. Technology such as spreadsheets, databases, and other software applications have made it easier for companies to perform financial analysis. Companies use these technologies to analyze their financial performance, create budgets, predict future incomes and expenses, and review their overall financial health. Companies do not generally use these technologies for employee recognition, staff communication, or public relations.', 'Financial-Information Management', 'Finance', 1500, 'FM:014', 'Demonstrate financial analysis applications', 'Finance District 2026 #63'),
  ('Which of the following primarily serves as an organization''s conscience during decision -making:', array['The public','Employees','Board of directors','The "C-Suite" (CEO, CFO, etc.)'], 2::smallint, 'Board of directors. The board of directors guides the organization during the decision-making process so that the organization continues to accomplish its mission in an efficient and ethical way. It would not be appropriate for the C-Suite, an organization''s employees, or the public to act as an organization''s conscience during decision-making.', 'Professional Development', 'Finance', 1500, 'PD:303', 'Describe the impact of governance processes on decision-making and management', 'Finance District 2026 #64'),
  ('A business can protect its digital financial data from losses associated with fire, flood, and electrical outages by', array['installing intrusion detection systems.','implementing a manual filing system.','performing backup procedures on a regular basis.','changing passwords and encryption techniques periodically.'], 2::smallint, 'Performing backup procedures on a regular basis. Backing up the computer system and storing the backup information off-site can reduce financial losses due to uncontrollable circumstances such as electrical outages or fire. Businesses that do not perform backup procedures on a regular basis may lose the data for good or take a lot of time and money to replace if a disaster harms its computer systems. Computer systems help make businesses operate more efficiently than manual systems do. Different types of intrusion detection systems (e.g., firewalls) are designed to protect the business''s computer systems from unauthorized access. Passwords and encryption are additional techniques used to secure access to computer information.', 'Risk Management', 'Finance', 1500, 'RM:042', 'Describe the use of technology in risk management', 'Finance District 2026 #65'),
  ('Which of the following is a common cause of disparate data structures within many large corporations'' financial - information management systems?', array['Capital structure','Channels of distribution','Mergers and acquisitions','Accounting method'], 2::smallint, 'Mergers and acquisitions. Mergers and acquisitions commonly handicap large corporations'' financial- information management systems because of disparate data structures. Even though two companies may become one as a result of a merger or acquisition, the two companies'' historical financial data may be incompatible or housed in different data structures, making a merge of the data difficult. Channels of distribution, the company''s capital structure, and the accounting method that the company uses do not commonly cause disparate data structures within financial-information management systems.', 'Financial-Information Management', 'Finance', 1500, 'FM:002', 'Explain the nature and scope of the financial-information management function', 'Finance District 2026 #66'),
  ('Ben works at a popular pizzeria. His managers recently introduced a new goal of selling 200 large pizzas per weeknight. To help the shop reach this goal, Ben and his fellow associates are assigned extra duties--and offered additional pay if they meet the 200-pizza goal. After three weeks, Ben''s managers announce that the shop exceeded its goal every night. Ben and his coworkers feel a sense of accompl ishment and are proud of their hard work. This example demonstrates the benefits of', array['involving employees in the achievement of organizational objectives.','leaving low-level employees out of management decisions.','setting organizational goals that are attainable and realistic.','overworking employees without compensating them for their efforts.'], 0::smallint, 'Involving employees in the achievement of organizational objectives. A company''s employees play a large role in achieving organizational goals. Without the effort and commitment of employees, organizational goals are unlikely to be met. This example demonstrates the benefits of involving employees in the achievement of organizational objectives. By involving and incentivizing the shop''s employees, the pizzeria was able to exceed its goals. This example does not demonstrate leaving low-level employees out of management decisions or overworking employees without compensating them. It''s important to set goals that are attainable and realistic, but this example best demonstrates the benefits of involving employees in the achievement of company goals.', 'Professional Development', 'Finance', 1500, 'PD:301', 'Ascertain employee''s role in achieving governance objectives', 'Finance District 2026 #67'),
  ('Which of the following situations is a potential external risk to a business:', array['An employee is injured on the job.','Management delays approval for the yearly budget.','An inaccurate inventory count leads to missing products.','The inflation rate changes over time.'], 3::smallint, 'The inflation rate changes over time. Inflation is an external, macroeconomic phenomenon that can have a major impact on companies and the economy as a whole. Inflation can pose risks to businesses by altering the habits of consumers and devaluing the business''s liquid assets. An injured employee, an inaccurate inventory count, and budget delays are all examples of internal risks to a business.', 'Risk Management', 'Finance', 1500, 'RM:058', 'Discuss the nature of risk control (i.e., internal and external)', 'Finance District 2026 #68'),
  ('A furniture retailer located in the city of Springdale wants to know how many of its high-volume customers are located within its own city limits. What are two criteria that should be included in its database query?', array['Purchase dates in the last year and Springdale addresses','Email address entered and purchases over $100,000','Springdale addresses and purchases over $100,000','Number of purchases over 10 and email address entered'], 2::smallint, 'Springdale addresses and purchases over $100,000. When running a query in a database, you must apply criteria so the database knows which entries to retrieve. These criteria should align with the questions that the query is meant to answer. Because the furniture retailer is interested in high-volume customers in Springdale, the criteria should match up with that. Springdale addresses and purchases over $100,000 will pull up the information that the retailer needs to know. Purchase dates in the last year, email address entered, and number of purchases over 10 will not provide the information that the retailer is seeking.', 'Information Management', 'Finance', 1500, 'NF:124', 'Demonstrate advanced database applications', 'Finance District 2026 #69'),
  ('Banyan is working on restructuring a database to reduce data redundancy and improve data integrity. In other words, Banyan is engaging in data', array['recovery.','normalization.','elimination.','clarification.'], 1::smallint, 'Normalization. Data normalization is the process of reorganizing and restructuring a database to reduce data redundancy and improve data integrity. Normalization seeks to get rid of nonconforming data and improve the usability of the database. This process is not referred to as data recovery, elimination, or clarification.', 'Information Management', 'Finance', 1500, 'NF:124', 'Demonstrate advanced database applications', 'Finance District 2026 #70'),
  ('Which of the following is an example of an external mechanism of corporate governance:', array['Board of directors'' policies','A company''s code of conduct','A company''s business objectives','Government regulations'], 3::smallint, 'Government regulations. External mechanisms are controls that come from outside of the organization. An example is government regulations that are imposed upon a company. Internal mechanisms come from within an organization. A board of directors'' policies, a company''s business objectives, and a company''s code of conduct are all internal mechanisms of control.', 'Professional Development', 'Finance', 1500, 'PD:302', 'Identify the factors that impact governance structures', 'Finance District 2026 #71'),
  ('To prevent unauthorized access to a computer system or network, businesses typically install', array['debugger applications.','compression software.','spyware applications.','firewall software.'], 3::smallint, 'Firewall software. Firewalls are computer programs that secure and protect computer networks from unauthorized users. Spyware is a type of software that gathers information about a user''s computer activity (e.g., browsing history) without their knowledge. Debugger applications help identify and correct computer- programming errors. Compression software reduces the size of an electronic file, which reduces storage space and increases the speed of transmission.', 'Financial-Information Management', 'Finance', 1500, 'FM:011', 'Describe the use of technology in the financial-information management function', 'Finance District 2026 #72'),
  ('Which of the following is commonly used to reduce an investor''s capital gains tax burden:', array['Puttable bonds','Value stocks','Short-term investments','Capital losses'], 3::smallint, 'Capital losses. An investor''s capital gains are their earnings from the appreciation of investments. Most federal governments collect taxes from investors on these capital gains. One way to reduce an investor''s capital gains tax burden is to subtract their capital losses (money that they have lost from the depreciation of investments) from the capital gains. They would only pay taxes on the difference, if it is positive. If their capital losses are greater than the capital gains, then they wouldn''t pay any capital gains tax at all. Long-term, rather than short- term, investments help investors reduce their capital gains tax burden, especially in the United States where long-term capital gains are taxed at a lower rate than short-term capital gains. Puttable bonds and value stocks typically have no impact on an investor''s capital gains taxes.', 'Business Law', 'Finance', 1500, 'BL:134', 'Discuss the effect of tax laws and regulations on financial transactions', 'Finance District 2026 #73'),
  ('By reviewing an income statement to see how every line item compares to revenue, Anushka conducted a __________ analysis.', array['SWOT','break-even','vertical','horizontal'], 2::smallint, 'Vertical. A vertical analysis is a financial analysis technique that reviews line items (such as those found on an income statement) as a proportion of revenue. In other words, analysis occurs by looking up and down (vertically) a financial document. A horizontal analysis is a financial analysis technique that looks at the year- over-year (YoY) change in each line item—looking left and right (horizontally) to conduct analyses. A SWOT analysis is a marketing tool that investigates a business''s strengths, weaknesses, opportunities, and threats. A break-even analysis is the process of determining the level at which revenues equal total costs.', 'Financial-Information Management', 'Finance', 1500, 'FM:009', 'Describe techniques used to analyze customer financial information', 'Finance District 2026 #74'),
  ('Which of the following is a consequence of noncompliance in the financial industry:', array['Audits and damaged reputation','Protection from lawsuits','Improved communication','Rule violation prevention'], 0::smallint, 'Audits and damaged reputation. Noncompliance refers to when a business or organization fails to fulfill its compliance requirements and responsibilities. There are several consequences a business may face for noncompliance, including audits, damaged reputation, financial penalties, suspension or termination of the business, and even imprisonment. A company that is guilty of noncompliance is susceptible to audits, which will draw closer inspection of a business''s processes and financials. In addition, noncompliance can hurt customer and investor confidence and can make lenders wary of providing financing to the business, all of which can hurt the business''s reputation. Rule violation prevention, protection from lawsuits, and improved communication are benefits of compliance in the finance industry.', 'Business Law', 'Finance', 1500, 'BL:148', 'Discuss the nature and scope of compliance in the finance industry', 'Finance District 2026 #75'),
  ('How could financial analysis applications be used to identify possible conflicts of interest?', array['By isolating entries against authorization records for new or terminated employees','By comparing employee phone numbers and addresses to vendor information for payables','By comparing yearly volume with on-hand quantity for stock items','By comparing vendor payables posted to purchase orders'], 1::smallint, 'By comparing employee phone numbers and addresses to vendor information for payables. A conflict of interest is a situation in which it is impossible to be truly impartial. It would prevent someone from performing their duties and responsibilities objectively. To spot probable conflicts of interest, businesses can use their financial analysis applications to cross check employee data with those of vendors. The other examples can be used to analyze financial data for other purposes.', 'Financial-Information Management', 'Finance', 1500, 'FM:014', 'Demonstrate financial analysis applications', 'Finance District 2026 #76'),
  ('Which of the following would most likely influence an organization''s corporate governance structure:', array['An unexpected grant from the government is received.','A major flood damages the company''s primary warehouse.','A member of the board of directors is charged with fraud.','An entry-level employee is fired for their lack of professionalism.'], 2::smallint, 'A member of the board of directors is charged with fraud. An organization''s board of directors is designed to hold the company accountable for its actions and steer the organization clear of ethical pitfalls. If a member of a company''s board of directors is charged with fraud or another crime, the company would most likely take immediate action to replace that member. A major flood, the firing of an entry-level employee, or an unexpected grant from the government would not influence a company''s corporate governance structure.', 'Professional Development', 'Finance', 1500, 'PD:302', 'Identify the factors that impact governance structures', 'Finance District 2026 #77'),
  ('One way to build professional relationships in the finance industry is to', array['implement a referral system.','encourage others to discuss their finances.','read about industry trends.','print new business cards for distribution.'], 0::smallint, 'Implement a referral system. A referral is a recommendation given to an individual or business by another individual or business. For example, satisfied clients may refer their friends, family, or colleagues to their financial planners for financial advice. This is one way that businesspeople working in the finance industry can build professional relationships. A financial planner may implement a referral system or program to encourage clients or associates to provide referrals. A referral system might involve giving a free consultation or discount to a client who has provided the financial planner with a lucrative referral. Reading about industry trends and printing new business cards are not actions that build professional relationships. The finance professional must take action on the trends they have researched and distribute the business cards to others to begin building professional relationships. Because financial information is personal and confidential, people are usually selective with whom they share their information.', 'Professional Development', 'Finance', 1500, 'PD:153', 'Discuss opportunities for building professional relationships in finance', 'Finance District 2026 #78'),
  ('What type of financial statement includes an accounting of the shareholders'' equity for a company?', array['Income statement','Balance sheet','Annual report','Cash flow statement'], 1::smallint, 'Balance sheet. The balance sheet gives a summary of a company''s financial health at a specific point in time. It contains two major sections: a listing of the company''s assets and a listing of its liabilities. The liabilities section also indicates the shareholders'' equity, which is the value of all the outstanding stock owned by shareholders. Shareholders'' equity is determined by subtracting the liabilities from the assets. The income statement, also known as the profit-and-loss statement, shows a company''s profitability over a specific period of time. The cash flow statement tracks the money that comes into and flows out of a company. An annual report is not a type of financial statement, but it does contain financial statements, along with a good deal of other information about the company.', 'Financial Analysis', 'Finance', 1500, 'FI:274', 'Describe sources of securities information', 'Finance District 2026 #79'),
  ('Which of the following is considered an internal control mechanism for a company:', array['Government regulations','Separation of duties','Industry standards','Union contracts'], 1::smallint, 'Separation of duties. Internal controls are accounting and auditing processes used by a company to ensure proper financial reporting, prevent fraud, and make sure the company is complying with laws and regulations. Separation of duties is a common internal control a company may use, as it ensures no single individual is in charge of authorizing and recording a financial transaction. Union contracts, government regulations, and industry standards are examples of external controls—any influence from outside a company that impacts how it operates.', 'Professional Development', 'Finance', 1500, 'PD:214', 'Describe the components of a well-governed company (e.g., board of directors, reporting,', 'Finance District 2026 #80'),
  ('Scott, a financial analyst, wants to determine whether a company has substantial short -term assets to cover its immediate liabilities without selling inventory. What liquidity ratio should he use?', array['Acid-test','Days sales outstanding','Current','Cash'], 0::smallint, 'Acid-test. An acid-test ratio determines whether a company has substantial short-term assets to cover its immediate liabilities without selling inventory. It does so by measuring the company''s ability to meet its short- term obligations with its most liquid assets. The ratio therefore excludes inventories from its current assets, as inventory may not be converted to cash quickly. A current ratio measures a company''s ability to meet current liabilities out of current assets. A cash ratio removes many current assets when considering a business''s ability to meet its short-term goals, as it only looks at assets that are already liquid. A days sales outstanding ratio refers to the average number of days it takes a company to collect payment after making a sale.', 'Financial-Information Management', 'Finance', 1500, 'FM:009', 'Describe techniques used to analyze customer financial information', 'Finance District 2026 #81'),
  ('What is the primary responsibility of a financial planner?', array['To provide appropriate financial guidance','To maximize their clients'' tax obligation','To double a client''s investment','To ensure that their clients can retire'], 0::smallint, 'To provide appropriate financial guidance. Financial planners are responsible for helping their clients achieve their financial goals by providing sound advice and suggesting appropriate financial products—such as investments, insurance, saving and budgeting, etc. Although financial planning involves using financial tools to grow the client''s wealth, the financial planner cannot guarantee that the client''s investment will double in value or that the client will generate enough investment income to retire at a certain age. A financial planner will work to minimize a client''s tax obligation rather than maximize it.', 'Customer Relations', 'Finance', 1500, 'CR:012', 'Explain the responsibilities of finance professionals in providing client services', 'Finance District 2026 #82'),
  ('Which finance career area most commonly deals with an individual''s or a household''s tax planning, estate planning, and retirement planning?', array['Personal finance','Corporate finance','Government finance','Public finance'], 0::smallint, 'Personal finance. Personal finance is centered around meeting personal financial goals and involves managing money, saving, and investing. As an industry, it provides financial services to individuals or households and offers suggestions for financial and investment opportunities. Financial position, adequate position, tax planning, investment and accumulation goals, retirement planning, and estate planning all fall under personal finance. The other two main finance career areas are corporate finance and public finance. Corporate finance refers to providing funds for a business''s activities, as corporate finance managers typically balance risk and profitability, study and forecast economic trends, manage funds, and work to maximize stock value, among other things. Public finance (or government finance) centers around the financial dealings of states and public entities and focuses on the role of the government in the economy.', 'Professional Development', 'Finance', 1500, 'PD:152', 'Discuss employment opportunities in the finance industry', 'Finance District 2026 #83'),
  ('To calculate the future value of money, you need the present value, the length of time, and the', array['bottom line.','wage.','interest rate.','utility.'], 2::smallint, 'Interest rate. The future value of money is calculated by the equation FV = PV × (1 + i) ⁿ where "FV" is future value, "PV" is present value, "i" is the interest rate, and "n" is the period of time. The bottom line is the net income of a business or the net result of a project or event. Utility and wage are business terms that are not relevant to the calculation of the time value of money.', 'Financial Analysis', 'Finance', 1500, 'FI:238', 'Calculate the time value of money', 'Finance District 2026 #84'),
  ('Ryder has learned that his company will announce a round of layoffs in two weeks. Ryder decides to sell some of the stock options he had in the company before the news of the layoffs goes public. He tells his friends to do the same. This is an example of', array['insider trading.','corporate fraud.','corporate espionage.','extortion.'], 0::smallint, 'Insider trading. Insider trading occurs when a company''s owners, directors, or key management trade its stock. Insider trading is illegal when those individuals make trades based on information that has not been disclosed to the public. Corporate fraud involves deception purposely carried out so that a company can secure an unfair or unlawful gain. Corporate espionage involves spying on a competitor or theft of a competitor''s proprietary information. Extortion involves using force to obtain another person''s or company''s property or money.', 'Business Law', 'Finance', 1500, 'BL:133', 'Discuss legal considerations in the finance industry', 'Finance District 2026 #85'),
  ('If the dividend per share on a securities table is blank, it indicates that the company''s stock', array['has a net change value of zero.','does not currently pay dividends.','has a negative dividend yield.','had zero trades in the last 24 hours.'], 1::smallint, 'Does not currently pay dividends. The dividend per share indicates the annual dividend payment per share, and a blank indicates the company does not currently pay out dividends. A negative dividend would suggest that shareholders pay dividends to the company, which typically does not occur. The number of trades that have occurred in the last 24 hours is the trading volume listed on a securities table. Net change refers to the dollar value change in a stock price from previous day''s closing price and is represented as a positive or negative value in the net change column on a securities table.', 'Financial Analysis', 'Finance', 1500, 'FI:275', 'Interpret securities table', 'Finance District 2026 #86'),
  ('Which of the following is an effective way to initiate a professional relationship with a vendor:', array['Having salespeople talk to the vendor','Giving the vendor an expensive gift','Treating the person to a round of golf','Offering jobs to people on the vendor''s staff'], 2::smallint, 'Treating the person to a round of golf. Something as simple as four hours of golf gives you the opportunity to get to know a vendor better. It gives you an opportunity to learn the person''s interests and to talk business in a casual environment. Giving the vendor an expensive gift might be construed as a bribe. Although having salespeople talk to the vendor is helpful, it doesn''t foster a professional relationship with you. Offering jobs to people on the vendor''s staff would create conflict rather than helping to build a positive, professional relationship.', 'Professional Development', 'Finance', 1500, 'PD:153', 'Discuss opportunities for building professional relationships in finance', 'Finance District 2026 #87'),
  ('With an effective customer strategy, a business can increase revenues by', array['prioritizing new customers over existing customers.','prioritizing existing customers over new customers.','providing products and services customers want.','helping sales staff close deals at a slower pace.'], 2::smallint, 'Providing products and services customers want. Customer relationship management (CRM) refers to the strategies, processes, technology, and people a business uses to build, maintain, and maximize the long-term value of customer relationships. A strong CRM strategy uses several pieces of information about customers and market trends to help the company better market and sell their products and services while meeting customers'' needs. An effective CRM strategy can increase a business''s revenues because CRM helps businesses identify customers'' needs, thus making it easier to provide products and services that are exactly what customers want. CRM strategies can help businesses retain their existing customers and discover new ones, not prioritize one group over the other. CRM can help businesses increase revenues by helping its sales staff close deals faster, not slower.', 'Customer Relations', 'Finance', 1500, 'CR:024', 'Use Customer Relationship Management (CRM) technology', 'Finance District 2026 #88'),
  ('The accounting staff at the Sun Valley Granola Company recently completed their annual review of the company''s budget. The team noticed that the company spent more money on advertising and promotion in the last year than on quality control. One staff member remarked that the company had been receiving an increase in complaints from dissatisfied customers than in previous years. What function of financial information management did the company neglect in this situation?', array['Budgeting','Policy setting','Planning','Stewardship'], 3::smallint, 'Stewardship. Financial stewardship involves ensuring that a company''s financial resources are allocated appropriately and ethically to fulfill the company''s mission. In this situation, the Sun Valley Granola Company failed to engage in financial stewardship because it spent more money promoting its products than ensuring that its products were high-quality. There is not enough information given in this example to determine whether the company neglected to plan, budget, or set policies.', 'Financial-Information Management', 'Finance', 1500, 'FM:003', 'Explain the role of ethics in financial-information management', 'Finance District 2026 #89'),
  ('The Milton Ladder Corporation, which is publicly traded, is in the process of acquiring the Bradley Chute Company. What type of document is Milton Ladder required to file within 15 days of the acquisition?', array['Form 4','Form 10-K','Form 10-Q','Form 8-K'], 3::smallint, 'Form 8-K. Publicly traded companies are required to provide information about their finances to the Securities and Exchange Commission (SEC) every quarter. For the first three quarters of the fiscal year, publicly traded companies file 10-Q reports that focus on the company''s financial situation for that period of time. At the end of the fourth quarter of each fiscal year, each company is required to file a Form 10-K, which is similar to an annual report. It includes detailed information about the company, its competitors, risks it faces, legal proceedings that the company is involved in, and audited financial statements. In addition to these standard, routine documents, a company is also required to file a Form 8-K, also known as a current report if a significant, nonrecurring event occurs before a 10-Q or 10-K is due. Events might include changes in key management, introduction of a new product, legal actions, or the acquisition of another company. Form 4 tells you when insiders are buying or selling the company''s stock.', 'Financial Analysis', 'Finance', 1500, 'FI:274', 'Describe sources of securities information', 'Finance District 2026 #90'),
  ('Which of the following is an example of an indirect cost in a car manufacturing facility:', array['Glass','Shipping','Electricity','Assembly line workers'' salaries'], 2::smallint, 'Electricity. Indirect costs are those that are not associated with one particular business activity and cannot easily be assigned to specific cost objects. Because electricity is used for many purposes in a car manufacturing facility, it is considered an indirect cost. Glass is not an indirect cost because it goes toward specific products. Shipping costs, too, can be easily allocated to a particular product or business activity. Because the workers on an assembly line are contributing their efforts toward a particular product, their salaries can also be considered direct costs. Some employees'' salaries are considered indirect, depending on the nature of their jobs.', 'Financial Analysis', 'Finance', 1500, 'FI:663', 'Discuss the nature of cost allocation', 'Finance District 2026 #91'),
  ('External audits are different from internal audits in that external audits', array['are conducted by someone within the company.','focus on measuring current performance.','look for areas of improvement.','focus on proving the accuracy of financial statements.'], 3::smallint, 'Focus on proving the accuracy of financial statements. An external audit looks at the accuracy of a company''s financial statements as well as any other practices that could confirm the truthfulness of budget statements. Internal audits focus on a specific area of a company, measure current performance, and look for areas of improvement. Internal audits are conducted by someone within the company on the company''s behalf, while external audits are usually conducted by a third party.', 'Professional Development', 'Finance', 1500, 'PD:214', 'Describe the components of a well-governed company (e.g., board of directors, reporting,', 'Finance District 2026 #92'),
  ('Which type of investment institution helps firms to raise funds by issuing securities?', array['Investment bank','Securities exchange','Pension fund','Investment company'], 0::smallint, 'Investment bank. Investment banks locate outside sources of money for firms. In most cases, investment banks help these businesses to raise funds by issuing securities in the form of stocks or bonds. An investment company pools investors'' funds and invests those funds based on the needs of the investors. Investment companies are also often referred to as "mutual funds." Like mutual funds, pension funds pool investors'' contributions. However, investors in a particular pension fund are typically employed by one employer. A securities exchange creates investment opportunities for investors and access to funds for businesses. Investment banks help businesses to issue and sell their securities on a securities exchange.', 'Financial Analysis', 'Finance', 1500, 'FI:336', 'Describe the role of financial institutions', 'Finance District 2026 #93'),
  ('What question should finance professionals ask to provide the appropriate types and levels of service to their clients?', array['Should I follow up with the clients?','How can I maximize my returns?','Are my goals realistic and attainable?','What are the client''s expectations?'], 3::smallint, 'What are the client''s expectations? To provide the level of service that their clients desire, finance professionals need to understand and know the level of service and communication that their clients expect. To build long- term client relationships, finance professionals should participate in ongoing communication with clients, which includes following up with clients to answer questions and resolve problems. Answering questions about personal career goals and personal financial returns are not directly related to providing the appropriate levels of service to clients.', 'Customer Relations', 'Finance', 1500, 'CR:012', 'Explain the responsibilities of finance professionals in providing client services', 'Finance District 2026 #94'),
  ('To reduce the risk of future legal problems, a company might require its business partners to sign a formal', array['contract.','premium.','warrant.','invoice.'], 0::smallint, 'Contract. A contract is an agreement between two or more parties stating that one party is to do something in return for something provided by the other party. By putting the terms of an agreement or business arrangement in a written contract that both parties sign, the business reduces the risk of misunderstanding about what is expected and what will be provided. When agreements are not documented and a problem occurs, legal action may be required, which can be costly to the business. An invoice is a bill. A premium is a fee for an insurance policy. A warrant is a legal document issued by authorities that requires an individual or business to take a certain action.', 'Risk Management', 'Finance', 1500, 'RM:043', 'Discuss legal considerations affecting risk management', 'Finance District 2026 #95'),
  ('Last week, a man who frequents Alice''s health club and goes to the same church approached her and struck up a conversation. After a bit of small talk, the man said that he would love to help Alice earn some money in the stock market. "You can trust me," the man said. "We go to the same church and the same gym. In fact, our minister and the manager of the gym just gave me a ton of money to invest for them!" The man is attempting to commit __________ fraud.', array['private placement offering','life settlement','natural resource investing','group affinity'], 3::smallint, 'Group affinity. Group affinity fraud typically involves a scammer who either claims or actually is a member of the investor''s group. In this case, the man is a member of the same health club and attends the same church as Alice. Because the scammer is a member of the same group, investors may falsely believe they can trust the scammer, especially if the scammer has lured in a few well-respected group members (like the minister or the gym manager) to buy into the scam early on. Natural resource investing fraud occurs when a scammer convinces investors to put money in fraudulent energy investments. Investors are tempted by the scammer''s promise of a fast, easy return. Private placement offering fraud involves convincing investors to buy nonexistent stock from businesses. Life settlement fraud occurs when a scammer purchases a large life insurance policy from the insured for an unreasonably small amount of money. This usually occurs when the insured person needs money to pay necessities such as medicine and medical care before death.', 'Business Law', 'Finance', 1500, 'BL:133', 'Discuss legal considerations in the finance industry', 'Finance District 2026 #96'),
  ('Which of the following is an uninsurable external risk to businesses:', array['Personal injury','Natural disasters','Inventory','Tax increases'], 3::smallint, 'Tax increases. Businesses cannot control when and by how much a government may increase taxes, which are uninsurable. A business''s inventory is insurable. Liability insurance can be purchased to transfer the business''s risks related to the potential injuries of its employees and customers. Natural disasters such as fire, tornados, and earthquakes are insurable risks.', 'Risk Management', 'Finance', 1500, 'RM:058', 'Discuss the nature of risk control (i.e., internal and external)', 'Finance District 2026 #97'),
  ('Which of the following is a disadvantage of enterprise risk management practices:', array['They increase redundant processes and employee satisfaction.','They rely heavily on management estimates and inputs.','They lead to more unexpected risks.','They only identify risks a company is not aware of.'], 1::smallint, 'They rely heavily on management estimates and inputs. Enterprise risk management (ERM) is an organization- wide strategy to identify, assess, and prepare for potential dangers and hazards that may harm or interfere with an organization''s finances, operations, and objectives. A disadvantage of ERM is that it relies heavily on management estimates and inputs, which sometimes can be very difficult to accurately predict. ERM identifies risk that a company has been exposed to in the past, and is thus limited in identifying future risk that a company is not yet aware of. ERM benefits a business because it leads to less unexpected risks and greater employee satisfaction, while reducing or even eliminating redundant processes.', 'Risk Management', 'Finance', 1500, 'RM:062', 'Discuss the nature of enterprise risk management (ERM)', 'Finance District 2026 #98'),
  ('Catya has been Trevor''s financial planner for 10 years. Because Trevor feels that Catya has his best interests in mind and keeps him updated on his investments, he told several of his friends a nd colleagues about Catya''s expertise and recommended that they make appointments with her to discuss their financial plans. The benefit to Catya in this situation is that she', array['gained a positive reputation through social media.','received referrals from an existing client.','earned a sizable commission from Trevor''s investments.','obtained recognition from her colleagues.'], 1::smallint, 'Received referrals from an existing client. When clients such as Trevor are happy with a financial planner''s services, they are likely to recommend or refer the financial professional to their friends, family, and colleagues. Trevor could also give Catya the contact information of his friends and colleagues so that she can follow up with them. The benefit to Catya is that she increases her client base and earning potential. There isn''t enough information provided to determine if Trevor used social media to communicate with his friends and colleagues about Catya, if Catya earned a sizeable commission from Trevor''s investments, or if Catya obtained recognition from her colleagues.', 'Customer Relations', 'Finance', 1500, 'CR:012', 'Explain the responsibilities of finance professionals in providing client services', 'Finance District 2026 #99'),
  ('Soren participates in the London Stock Exchange, where investors trade stock amongst themselves without involvement from the issuing companies. Which of the following best describes this type of market:', array['Primary market','Tertiary market','Virtual market','Secondary market'], 3::smallint, 'Secondary market. The secondary market is where investors are able to trade securities after companies have sold their offerings on the primary market. The secondary market is often called the "stock market" and includes the London Stock Exchange, New York Stock Exchange, and Nasdaq. Primary markets are where companies sell securities to the public for the first time. A virtual market is where products are purchased and sold electronically, with no physical interaction between buyer and seller. Tertiary market can refer to a smaller market.', 'Financial Analysis', 'Finance', 1500, 'FI:337', 'Explain types of financial markets (e.g., money market, capital market, insurance market,', 'Finance District 2026 #100'),
  ('When Arlo travels out of the country, he picks up some souvenirs. When he tries to bring them back home with him, he discovers that he has to pay a tax on them. Arlo must pay the', array['travel tax.','souvenir tax.','customs duty.','travel duty.'], 2::smallint, 'Customs duty. Goods that are brought across international borders are often subject to a tax called a customs duty. This is meant to control the flow of goods. It is not called a travel tax, a travel duty, or a souvenir tax.', 'Business Law', 'Business Management', 1500, 'BL:126', 'Describe the nature of customs regulations', 'BMA District 2026 #1'),
  ('When an individual invests in a mutual fund, they are', array['taking on a high level of investing risk.','pooling their money with other investors.','selecting their own investment options.','purchasing corporate and government bonds.'], 1::smallint, 'Pooling their money with other investors. A mutual fund is a collection of stocks and bonds. When you buy a mutual fund, you are pooling your money with other investors, allowing you to pay for a professional manager to select investments for the group. Therefore, when an individual invests in a mutual fund, they are not selecting their own investment options, nor are they solely purchasing corporate and government bonds. Investing in a mutual fund is a relatively low-risk way to invest because a professional financial manager selects appropriate securities for you.', 'Financial Analysis', 'Business Management', 1500, 'FI:077', 'Explain types of investments', 'BMA District 2026 #2'),
  ('Wesley is thinking about getting a new phone, so he logged on to a well-known website to read others'' opinions and experiences with different types of phones that are currently on the market. Wesley is reading online product reviews to', array['make an informed buying decision.','reaffirm his recent purchasing selection.','compare the prices of phones from various online stores.','determine which company has the best phone plan.'], 0::smallint, 'Make an informed buying decision. The internet has revolutionized the ways in which business is conducted. The internet provides customers with the ability to obtain product information in a variety of ways—from business websites, blogs, newsfeeds, and consumer information websites. In the example, Wesley is doing research to find out how other users like different phones before he makes a decision about the one that he wants to buy. Wesley will likely visit various phone retailers to get product specifications and pricing before making his decision. Although phone plans are often a factor when making a phone purchasing decision, there is not enough information provided to determine whether phone plans will affect Wesley''s buying decision. Wesley hasn''t purchased his phone yet, so he can''t reaffirm his recent purchase.', 'Information Management', 'Business Management', 1500, 'NF:086', 'Describe the scope of the internet', 'BMA District 2026 #3'),
  ('Before entering a negotiation, which of the following questions should a person ask themselves when analyzing their opponent:', array['What are my needs and wants?','Do we share any common ground?','What can I learn from the other person''s body language?','When should I focus on the other person''s position?'], 1::smallint, 'Do we share any common ground? As you prepare for a negotiation, you should analyze the other side by asking and answering several questions. You should determine the other person''s position and interests, and then ask yourself if you share any common ground. While you should analyze your opponent''s body language, this is done when the negotiation is actually underway, not beforehand. Successful negotiations focus on interests rather than positions. You should consider your needs and wants during the first step of the preparation process, which involves determining your minimal and optimal expectations.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:062', 'Demonstrate negotiation skills', 'BMA District 2026 #4'),
  ('One of the roles of ethics in information management involves an individual''s right to', array['equity.','safety.','privacy.','dignity.'], 2::smallint, 'Privacy. Information management is the process of accessing, processing, maintaining, evaluating, and disseminating knowledge, facts, or data for the purpose of assisting business decision-making. Some of this information may be personal data that businesses obtain about their employees, customers, suppliers, etc. Individuals have the right to expect that the privacy of their personal information will be maintained. Businesses that are ethical do everything they can to protect private information and make sure it is not misused or made available to unauthorized users. Safety is freedom from danger or risk. Dignity is a high degree of calmness and self-possession. Equity is fairness.', 'Information Management', 'Business Management', 1500, 'NF:111', 'Explain the role of ethics in information management', 'BMA District 2026 #5'),
  ('The owner receives all of the profits of the business and can act quickly in making business decisions when the form of business ownership is a', array['corporation.','sole proprietorship.','joint venture.','partnership.'], 1::smallint, 'Sole proprietorship. Other advantages of a sole proprietorship are that it is easy to start, it has certain tax advantages, and the details of the business can be kept private. In a partnership, the profits are divided among the partners who sometimes disagree as to how profits should be divided. In a corporation, the profits are divided among the stockholders. The officers of the corporation are responsible for the actual operation and management of the firm. A joint venture is an arrangement that involves two or more businesses entering into a relationship by combining complementary resources, such as technology, skills, capital, or distribution channels, for the benefit of all parties.', 'Business Law', 'Business Management', 1500, 'BL:003', 'Explain types of business ownership', 'BMA District 2026 #6'),
  ('What is a characteristic of an effective persuasive message?', array['Is aggressive','Describes a process','Summarizes an issue','Creates desire'], 3::smallint, 'Creates desire. A persuasive message is intended to change a person''s mind or to convince someone to take action. For the message to be effective, it should create a desire in the person to do what the message wants. It should present a good reason or potential benefit that will persuade the reader. Otherwise, there may be no incentive for the person to do what the message wants. Persuasive messages often are assertive, but they should not be aggressive. Persuasive messages do not describe a process or summarize an issue.', 'Communication Skills', 'Business Management', 1500, 'CO:031', 'Write persuasive messages', 'BMA District 2026 #7'),
  ('When Rhett retrieved a client''s information and called the phone number listed, he discovered the information was incorrect. This is an example of the importance of __________ records.', array['paper','digital','quality','required'], 2::smallint, 'Quality. Rhett would have benefited from quality records—records that are accurate and reliable. Paper records, digital records, and required records (mandated by a governing authority) may or may not be quality records.', 'Information Management', 'Business Management', 1500, 'NF:001', 'Describe the nature of business records', 'BMA District 2026 #8'),
  ('Which of the following is an ineffective form of nonverbal communication to use while giving an oral presentation:', array['Swaying back and forth','Moving around the stage','Facial expressions','Hand gestures'], 0::smallint, 'Swaying back and forth. Ineffective nonverbal communication includes distracting gestures and actions such as gripping onto the podium, tapping your foot, twisting your hair, or swaying back and forth. Effective nonverbal communication includes facial expressions, hand gestures, and moving around the stage to create emphasis, interact with your audience, and convey meaning.', 'Communication Skills', 'Business Management', 1500, 'CO:025', 'Make oral presentations', 'BMA District 2026 #9'),
  ('Lucia was interested in becoming an assistant manager but was told that she was not assertive enough for the job. What could Lucia start doing to become more assertive?', array['Refraining from expressing her thoughts or ideas','Saying "no" to all requests made of her','Preventing others from taking advantage of her','Doing her work without asking for help from others'], 2::smallint, 'Preventing others from taking advantage of her. Assertive people don''t take advantage of others or allow others to take advantage of them. They don''t refrain from expressing their thoughts and ideas. They do not say "no" to all requests and do not feel guilty about saying "no" when necessary. They also ask for help when it is needed.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:008', 'Use appropriate assertiveness', 'BMA District 2026 #10'),
  ('Group orientation sessions for new employees are very important because they', array['provide in-depth training.','explain the duties of each job.','encourage organizational input.','help to motivate employees.'], 3::smallint, 'Help to motivate employees. A good orientation program makes new employees feel welcome, gives them an overview of the business, and helps to motivate them to do their best. Orientation often includes giving the new workers a handbook so that they have a copy of the information being presented. The primary purpose of an orientation session is to provide general information; it is not used to discuss specific job duties, provide in- depth training, or solicit input about organizational processes.', 'Human Resources Management', 'Business Management', 1500, 'HR:360', 'Orient new employees', 'BMA District 2026 #11'),
  ('You have a large amount of customer data at your office, and you want to sort through the information and find patterns. You should use data', array['mining.','elimination.','entry.','creation.'], 0::smallint, 'Mining. Data mining involves processing information and finding patterns. If you want to find patterns in your customer data, you should use data mining, not data elimination, entry, or creation.', 'Information Management', 'Business Management', 1500, 'NF:151', 'Demonstrate basic data mining techniques', 'BMA District 2026 #12'),
  ('Offering to provide additional information after a job interview is often the function of a(n)', array['email question.','handwritten note.','phone call.','follow-up message.'], 3::smallint, 'Follow-up message. After a job interview, it is important to send a follow-up, typically in email form, to the interviewer. The message thanks the interviewer for their time and reinforces the applicant''s interest in the position. In this communication, it is appropriate to mention your availability to provide any further information the interviewer may need. It is generally not appropriate to follow up with a phone call unless specifically instructed to do so. A handwritten note can be viewed as overly formal or old-fashioned. Emails are common after job interviews, but they should not ask questions—doing so would require the interviewer to respond.', 'Professional Development', 'Business Management', 1500, 'PD:029', 'Write a follow-up letter after job interviews', 'BMA District 2026 #13'),
  ('Farmers in a private enterprise economy own the', array['land they rent.','workers they hire.','money they borrow.','crops they raise.'], 3::smallint, 'Crops they raise. Ownership of private property in a free enterprise system also includes ownership of the results of the work; therefore, farmers own the crops they raise. Farmers who rent land do not own it, and they do not own the workers they hire. Borrowing money means that farmers are using it temporarily and must return it to the owner by a certain time.', 'Economics', 'Business Management', 1500, 'EC:009', 'Explain the concept of private enterprise', 'BMA District 2026 #14'),
  ('Bethany has decided to make a career change. After 10 years at her company, she is leaving her job for a new position in a different city. What would be the best way for Bethany to tell her manager that she''s leaving?', array['Via text','In person','By phone call','Via email'], 1::smallint, 'In person. This type of information is too important for Bethany to communicate via email, instant messaging, or text. The most appropriate method for Bethany to communicate that she is leaving would be in person, potentially accompanied by an official written letter.', 'Communication Skills', 'Business Management', 1500, 'CO:092', 'Choose and use appropriate channel for workplace communication', 'BMA District 2026 #15'),
  ('Which of the following is one of the biggest expenses that employees can help a business to control:', array['Taxes','Advertising','Rent','Payroll'], 3::smallint, 'Payroll. One of a business''s biggest expenses is payroll. Therefore, it is important for businesses to get full value for their payroll dollars to control expenses. Employees who arrive on time and work their designated hours are helping to ensure that the business receives the time it pays for. Advertising, taxes, and rent are other types of business expenses that are not under the employee''s control.', 'Operations', 'Business Management', 1500, 'OP:025', 'Explain employee''s role in expense control', 'BMA District 2026 #16'),
  ('Successful brands use brand promises to connect with their customers on a(n) __________ level.', array['logical','rational','emotional','ethical'], 2::smallint, 'Emotional. A brand promise is the specific benefit that customers can expect from using the good/service and interacting with the company. It connects to customers on an emotional level and gives meaning to the brand. Successful brands use brand promises to connect to their customers on a "gut" level. Customers are more likely to be loyal to brands that they feel share their values and beliefs. Some customers may feel connected to a brand due to its ethics, but brand promises do not always connect with customers on an ethical level as they do an emotional one. Customers might choose to purchase products and services from companies due to rational or logical reasons, but these are not usually connected to the business''s brand promise.', 'Customer Relations', 'Business Management', 1500, 'CR:001', 'Identify company''s brand promise', 'BMA District 2026 #17'),
  ('Which of the following statements about union federations is true:', array['They represent workers in specific geographic areas.','They consist of several different national unions.','They represent workers at a specific company.','They help to establish new local unions.'], 1::smallint, 'They consist of several different national unions. A federation is the highest level of union organization consisting of a group of national unions. These national unions of different kinds join together to further their common purposes, such as public relations, political agendas, etc. A local union—the lowest level of union organization—represents workers at a specific company or in a specific geographic area. A national/international union not only consists of a number of local unions, but it also helps establish new local unions.', 'Economics', 'Business Management', 1500, 'EC:015', 'Explain the concept of organized labor and business', 'BMA District 2026 #18'),
  ('A business must sell a certain amount of goods or services to create __________ for the company.', array['debt','free trade','competition','profit'], 3::smallint, 'Profit. Profit is the monetary reward a business receives. The business must sell enough goods or services to pay its expenses before it can receive profit. Debt is something that is owed by a business or an individual. Free trade is the elimination of trade barriers between countries. Competition is the rivalry between two or more businesses to attract scarce customer dollars.', 'Economics', 'Business Management', 1500, 'EC:010', 'Identify factors affecting a business''s profit', 'BMA District 2026 #19'),
  ('Effective collaboration among coworkers requires', array['mutual respect.','similar personality traits.','authoritarian attitudes.','selective communication.'], 0::smallint, 'Mutual respect. Coworkers must often collaborate with one another to accomplish business goals. For effective collaboration, coworkers must be respectful of one another. This involves being willing to share ideas, appreciating the contributions and knowledge of one''s coworkers, and acknowledging each coworker''s right to express opinions that others may not agree with. Effective collaboration does not require coworkers to have similar personality traits. An authoritarian workplace structure or management style may hinder collaborative efforts. Effective collaboration requires open and honest communication among all of the coworkers involved in the project or activity.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:061', 'Maintain collaborative partnerships with colleagues', 'BMA District 2026 #20'),
  ('When facilitating a group discussion, you should focus on providing __________, rather than __________.', array['printed materials; digital resources','specific directions; vague instructions','food; beverages','questions; answers'], 3::smallint, 'Questions; answers. The goal of facilitation is to help the group move forward, not to convey knowledge. The facilitator of a discussion should prepare questions for the group rather than simply provide information or answers. A discussion does not usually require specific questions; guidelines can be open-ended so that participants can feel comfortable sharing different ideas. Printed materials are not necessarily preferred over digital materials—both can function in a discussion setting. Food and beverages are not required for a discussion, and one is not necessarily better than the other.', 'Communication Skills', 'Business Management', 1500, 'CO:201', 'Facilitate (lead) group discussions', 'BMA District 2026 #21'),
  ('If a company is managing its information effectively, the data should be accurate and', array['anonymous.','relevant.','positive.','encrypted.'], 1::smallint, 'Relevant. To make business decisions, companies access, store, maintain, and evaluate a variety of information (e.g., facts, data). To make appropriate decisions, companies need to make sure the information they are basing their decisions upon is accurate and relevant. For example, information from an employee''s performance review will not help the business determine how to price its products. Information from an anonymous source may be incorrect and could lead to poor decisions and undesirable outcomes. Encryption is the process of transforming information into a secret code so only the recipient can read it. Not all information needs to be encrypted. While positive information about the company is nice, it is more important that the information is honest, accurate, and relevant.', 'Information Management', 'Business Management', 1500, 'NF:110', 'Discuss the nature of information management', 'BMA District 2026 #22'),
  ('Coral and Aaliyah are finishing a school project together. When Coral asks Aaliyah what she thinks about her half of the project, Aaliyah tells her, "That looks good, but let me show you what else you could have done." Aaliyah''s comments are an example of', array['constructive criticism.','internal feedback.','negative feedback.','self-control.'], 0::smallint, 'Constructive criticism. Constructive criticism is evaluative information designed to help someone improve. Negative feedback is feedback involving criticism, a negative judgment about you or your behavior; it tends to make you want to change or modify your words or actions. Internal feedback is feedback that comes from within yourself. Self-control is the restraint of your feelings, words, and actions.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:003', 'Explain the use of feedback for personal growth', 'BMA District 2026 #23'),
  ('Businesses often measure the efficiency of current production methods to find out if', array['loading docks are organized.','improvements are needed.','work areas are kept clean.','salaries should be adjusted.'], 1::smallint, 'Improvements are needed. Productivity cannot be improved unless it has been measured. Businesses often measure the efficiency of current production methods to determine whether improvements are needed and how to make those improvements. Businesses do not measure productivity to find out if salaries should be adjusted. Making sure work areas are clean and loading docks are organized could be improvements that are needed.', 'Economics', 'Business Management', 1500, 'EC:013', 'Explain the concept of productivity', 'BMA District 2026 #24'),
  ('Emilio is presenting at a sales meeting and wants to show how much of the year''s total revenue came from each region. What kind of graphic aid should Emilio use?', array['Flowchart','Bar graph','Line graph','Pie chart'], 3::smallint, 'Pie chart. A pie chart is a type of visual aid that demonstrates the proportion of parts to the whole. In this case, each segment of the pie chart would represent one of the sales regions and show how much of the total revenue came from each one. A bar graph is better suited for showing changes in magnitude over time. A line graph shows changes in direction over time. A flowchart demonstrates a schematic process.', 'Communication Skills', 'Business Management', 1500, 'CO:087', 'Select and use appropriate graphic aids', 'BMA District 2026 #25'),
  ('Which type of accountant creates budgets and provides internal information to organizations?', array['Public','Mediation','Managerial','Financial'], 2::smallint, 'Managerial. Managerial accountants provide internal information to organizations. Managerial accountants contribute to an organization''s day-to-day operations, financial decision-making, and business planning. They also forecast sales, create budgets, and allocate costs. Public accountants prepare, analyze, and verify financial data for a variety of clients, including the government, corporations, and individuals. Financial accountants provide information to those outside of the organization. Mediation accountant is a fictitious term.', 'Financial Analysis', 'Business Management', 1500, 'FI:351', 'Discuss the role of ethics in accounting', 'BMA District 2026 #26'),
  ('Craig knows he needs to make some changes, so he analyzes his own behavior and attitude. Instead of ignoring his flaws, he takes an honest assessment. Which adaptable trait is Craig exhibiting?', array['Respect','Empathetic behavior','Self-corrective behavior','Confidence'], 2::smallint, 'Self-corrective behavior. When adaptable people encounter new circumstances, they look at their own behavior and attitude and decide what needs to change. This honest assessment is far more helpful than ignoring flaws. This is what Craig does when he analyzes his own behavior and attitude. Respect, confidence, and empathy are all important characteristics of adaptable people, but they aren''t illustrated in Craig''s example.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:006', 'Demonstrate adaptability', 'BMA District 2026 #27'),
  ('The employees of the Deluxe Corporation routinely take office supplies for personal use. This is an example of', array['pilferage.','shoplifting.','robbery.','burglary.'], 0::smallint, 'Pilferage. Pilferage is the theft of small sums of money or inexpensive items from a business. Shoplifting is the theft of goods by customers. Burglary is any illegal entry into a building to commit a theft. Robbery is theft that involves the use of force, violence, or fear.', 'Operations', 'Business Management', 1500, 'OP:013', 'Explain routine security precautions', 'BMA District 2026 #28'),
  ('Which of the following is a category of innovation:', array['Physical','Piloting','Psychological','Product'], 3::smallint, 'Product. Product innovation occurs when a business either creates or improves a product. Other types of innovation include process, positioning, and paradigm. Psychological, piloting, and physical are not types of innovation.', 'Professional Development', 'Business Management', 1500, 'PD:126', 'Explain the need for innovation skills', 'BMA District 2026 #29'),
  ('Which of the following organizations should be contacted if a service business is not following health and safety regulations:', array['Utilities commission','Government agency','Local chamber of commerce','Regional risk coalition'], 1::smallint, 'Government agency. Service businesses must follow certain procedures to ensure the safety and health of both their customers and their employees. The government establishes health and safety laws to protect the well- being of anyone who enters the business. A service business that does not follow the laws could be endangering customers and employees. If this occurs, the appropriate government agency should be contacted so that corrective action can be taken to prevent accidents or illness. The local chamber of commerce, the utilities commission, and the regional risk coalition are not organizations that handle violations of health and safety regulations.', 'Operations', 'Business Management', 1500, 'OP:005', 'Report noncompliance with business health and safety regulations', 'BMA District 2026 #30'),
  ('After starting to write his paper, Shawn realized that he needed to use three sources instead of two. He only had to rewrite the introduction rather than the entire paper. This is an example of how', array['project quality is the most important criterion to measure.','only careless people need to take corrective actions.','monitoring projects saves time and resources.','it is important to build relationships with stakeholders.'], 2::smallint, 'Monitoring projects saves time and resources. If you monitor your project regularly, you''ll save time and resources that you might have otherwise wasted. Shawn is saving time that he might have spent rewriting the whole paper because he monitored the project during the process of doing the work. This is not an example of how it is important to build relationships with stakeholders. It is not true that only careless people need to take corrective actions. Finally, quality is not necessarily the most important aspect of a project to measure.', 'Operations', 'Business Management', 1500, 'OP:520', 'Monitor projects and take corrective actions', 'BMA District 2026 #31'),
  ('Asking a satisfied customer to pass on favorable information to your manager is an example of __________ behavior.', array['questionable','unfair','ethical','aggressive'], 2::smallint, 'Ethical. Satisfied customers often tell employees that they are pleased with a good or service. When this happens, it is ethical to ask the customer to pass on that information to management. Favorable comments from customers carry more weight than information provided by employees. In most cases, satisfied customers are willing to write a short review or leave a message expressing their satisfaction. Employees who ask customers to do so are behaving ethically because they are simply asking customers to be truthful. Politely asking customers to pass on favorable information is not an example of aggressive, questionable, or unfair behavior. This practice is common in business and intended to let management know that employees are performing effectively.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:038', 'Explain ethical considerations in providing information', 'BMA District 2026 #32'),
  ('What is a factor that affects a business''s relations with its customers?', array['Behavior of competitors','Condition of associates','Location of suppliers','Attitude of employees'], 3::smallint, 'Attitude of employees. The attitude that employees project toward customers has a significant effect on the type of relationship that businesses develop with customers. Employees who are friendly, polite, and helpful to customers help a business establish and maintain positive customer relations. On the other hand, employees who appear bored and ignore customers make a poor impression and may damage a business''s relations with its customers. Location of suppliers, behavior of competitors, and condition of associates are not factors that affect a business''s relations with its customers.', 'Customer Relations', 'Business Management', 1500, 'CR:003', 'Explain the nature of positive customer relations', 'BMA District 2026 #33'),
  ('Which of the following would indicate that a job applicant is more likely to make mistakes on the job:', array['The cover letter lacks the applicant''s signature.','The resume contains misspelled words.','The applicant did not complete their college degree.','The applicant does not provide references.'], 1::smallint, 'The resume contains misspelled words. Mistakes on job resumes often indicate to personnel directors that the applicants are careless and would continue that habit on the job. Applicants who provide error-free resumes are viewed more favorably by personnel directors and often have a better chance of finding jobs. Resumes and cover letters are often sent via email, so cover letters often do not include applicant''s handwritten signature. Often, businesses want professional references rather than personal references. In many situations, references are not required until the applicant passes the initial screening process. A college degree does not ensure that the applicant will not make mistakes on the job.', 'Professional Development', 'Business Management', 1500, 'PD:031', 'Prepare a resume', 'BMA District 2026 #34'),
  ('Jackson works for a hotel as a quality control specialist. In the past, he inspected every hotel room once a week to ensure that the rooms remained clean, attractive, and fully stocked. Lately, however, he has been skipping weekly inspections and only checking the hotel rooms that guests tell him need attention. What mistake is Jackson making?', array['He is not trusting his housekeeping staff to perform their jobs well.','He is not inspecting dirty or disorderly hotel rooms thoroughly enough.','He is being reactive instead of proactive in his quality-control practices.','He is failing to communicate effectively with the staff he oversees.'], 2::smallint, 'He is being reactive instead of proactive in his quality-control practices. Being proactive means anticipating and preventing problems before they arise, rather than waiting for problems to surface and handling them afterwards. As a quality control specialist, it is Jackson''s job to ensure that every room in his hotel is satisfactory and up to guest standards. He should inspect each hotel room periodically, rather than wait until he receives a complaint. The question does not provide enough information to conclude that Jackson is failing to communicate with his staff, inspect dirty rooms thoroughly enough, or trust his staff to perform their jobs well.', 'Operations', 'Business Management', 1500, 'OP:164', 'Utilize quality control methods at work', 'BMA District 2026 #35'),
  ('In which of the following situations would a conversational, informal tone and slang be most appropriate:', array['Industry publication','Report for a CEO','Social media post','Company-wide email'], 2::smallint, 'Social media post. Knowing when and how to adapt written correspondence to different audiences is a critical business communication skill. A conversational, informal tone and slang would be most appropriate in a company''s social media post. A report for a CEO and an industry publication would require a formal, serious tone and potentially technical jargon—these audiences require a more professional communication style. A company-wide email would be less formal than the publication and report but would likely avoid slang.', 'Communication Skills', 'Business Management', 1500, 'CO:203', 'Adapt written correspondence to targeted audiences', 'BMA District 2026 #36'),
  ('Jhenae just realized she failed to do an important and difficult task her boss had assigned to her. The task needs to be completed by tomorrow morning. What should Jhenae do to show she has initiative?', array['Work late to complete it on time.','Ask her teammates to help complete it.','Ask her boss to extend the deadline.','Complete what she can before her work shift is over.'], 0::smallint, 'Work late to complete it on time. Working late shows that Jhenae has initiative because she is willing to work hard to accomplish her assigned work. If Jhenae leaves the work unfinished, asks for an extended deadline, or asks her teammates to help, she will show a lack of initiative by not accepting personal responsibility for completing her assignment on time.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:024', 'Explain the importance of demonstrating initiative', 'BMA District 2026 #37'),
  ('While information technology and information systems are similar, information systems emphasize', array['global trends.','the people involved.','coding languages.','artificial intelligence.'], 1::smallint, 'The people involved. Information technology involves the technological elements of a set of information (e.g., hardware, software, networks). Information systems involve the management of an entire set of information, which includes both the technological elements and the people and processes therein. Coding languages, global trends, and artificial intelligence are not related to the distinction between information technology and information systems.', 'Information Management', 'Business Management', 1500, 'NF:083', 'Explain the role of information systems', 'BMA District 2026 #38'),
  ('Lia wants to be a change leader at work. She''s been coming in early for the past several weeks to get some extra training and mentoring from her boss. Which characteristic of a change leader is Lia displaying in this situation?', array['Willing to go above and beyond','Persuasive','Sense of urgency','Independent'], 0::smallint, 'Willing to go above and beyond. By going "the extra mile" to learn new things and grow as a professional, Lia is showing that she is willing to go above and beyond to become a change leader at work. Change leaders have a sense of urgency, are independent, and are persuasive, but these are not the characteristics Lia is displaying in this situation.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:005', 'Lead change', 'BMA District 2026 #39'),
  ('Why do businesses make investments?', array['To pay dividends','To monitor markets','To balance cash','To increase wealth'], 3::smallint, 'To increase wealth. Many businesses have cash remaining after all of the expenses have been paid. As a result, they often invest these funds to increase the wealth of the business. For example, a business that invests $5,000 in a stock that appreciates 8% in value in a year, then has an asset worth $5,400. As the business continues to invest, its wealth continues to increase. Stock is a type of investment in which shareholders receive dividends. Businesses do not make investments to balance cash or monitor markets.', 'Financial Analysis', 'Business Management', 1500, 'FI:270', 'Explain the need to save and invest', 'BMA District 2026 #40'),
  ('Decreased risk of harm to the environment, greater support from customers, and decreased risk of lawsuits are all examples of the', array['advantages of starting a limited liability company (LLC).','benefits of hiring employees with five years of work experience.','advantages of acting ethically while starting a business.','need to generate innovative ideas for new businesses.'], 2::smallint, 'Advantages of acting ethically while starting a business. Ethical decision-making has many advantages for entrepreneurs and their companies, including a decreased risk of harm to the environment, greater support from customers, and decreased risk of lawsuits. These are not necessarily examples of the benefits of hiring employees with five years of work experience or starting a limited liability company (LLC). These benefits may result from generating innovative ideas for businesses, but they are not necessarily examples of the need to generate innovative business ideas.', 'Entrepreneurship', 'Business Management', 1500, 'EN:044', 'Describe the use of business ethics in entrepreneurship', 'BMA District 2026 #41'),
  ('What might employees read to learn about new trends and technology in a specific industry?', array['News magazine','Trade journal','Daily newspaper','Annual report'], 1::smallint, 'Trade journal. Trade journals are a type of business magazine aimed at businesspeople interested in particular industries. Trade journals contain information about new trends, technology, and upcoming events related to specific industries. Employees read trade journals in order to keep current on developments in their industries. News magazines and daily newspapers contain information of interest to the general public. An annual report contains information about the financial condition and activities of a certain business.', 'Professional Development', 'Business Management', 1500, 'PD:036', 'Utilize resources that can contribute to professional development (e.g., trade', 'BMA District 2026 #42'),
  ('When our nation enjoys economic growth, what usually happens to domestic economic problems?', array['They are solved completely.','They are more easily resolved.','They are made worse.','They are not affected.'], 1::smallint, 'They are more easily resolved. When economic growth occurs, the government has more funds to spend on solving domestic economic problems such as poverty, lack of education, and inadequate medical services. The amount of economic growth directly affects the government''s ability to deal with domestic economic problems. When growth stands still or declines, economic problems tend to become worse. Domestic problems will never be completely solved.', 'Economics', 'Business Management', 1500, 'EC:017', 'Explain the concept of Gross Domestic Product (GDP)', 'BMA District 2026 #43'),
  ('Keeping aisles clear and file cabinets closed would be part of which of the following accident-prevention techniques:', array['Practicing vehicle safety','Lifting objects properly','Following proper health standards','Maintaining a clean work area'], 3::smallint, 'Maintaining a clean work area. Keeping aisles clear and file cabinets closed prevents accidents that occur when people trip over or bump into things. Following proper health standards, lifting objects properly, and driving safely are other types of accident prevention.', 'Operations', 'Business Management', 1500, 'OP:009', 'Explain procedures for handling accidents', 'BMA District 2026 #44'),
  ('A product development team reached out to customers to obtain their feedback on a new product release. The customers were then more likely to participate in a future focus group because they knew their opinions were valued. This is an example of how', array['customer feedback is rarely useful when evaluating project success.','evaluating project success builds stakeholder relationships.','communicating professionally with customers is important.','it is important to know whether a project achieved its goals.'], 1::smallint, 'Evaluating project success builds stakeholder relationships. When you communicate with stakeholders about their levels of satisfaction with the project results, they will be appreciative that you took the time to consider their feedback, such as is the case with the focus group. They''ll be more likely to want to continue working with the product development team in the future. This is not an example of how it is important to know whether a project achieved its goals. Customer feedback is generally useful when evaluating project success. Communicating professionally with customers is important, but this example is not related to that.', 'Operations', 'Business Management', 1500, 'OP:521', 'Evaluate project success', 'BMA District 2026 #45'),
  ('The reason to write a cover letter to submit with your resume is to', array['list former employers who are willing to serve as references.','indicate what days and times you are available for an interview.','summarize why you are a good candidate for the job.','include critical information that was left out of the resume.'], 2::smallint, 'Summarize why you are a good candidate for the job. A cover letter serves as a way to introduce yourself, express your interest in a job with the company, and briefly describe why you are a good candidate for the job. Job seekers should provide a list of references in a separate document. Critical information should be included in the resume rather than the cover letter. Job seekers should not indicate their availability for interviewing in a cover letter.', 'Professional Development', 'Business Management', 1500, 'PD:030', 'Write a cover letter', 'BMA District 2026 #46'),
  ('A product being in great demand is a factor that might encourage businesses to', array['decrease inventory.','gather information.','adjust prices.','contact competitors.'], 2::smallint, 'Adjust prices. Deciding on a product''s price is not always easy. Businesses must consider many factors, some of which encourage businesses to adjust prices. For example, if a product is in great demand, businesses might increase the price because customers are willing to pay the price to obtain the product. If a product is in great demand, a business would increase inventory to increase sales. Businesses do not contact competitors about demand or prices. By gathering information, a business might learn that a product is in great demand.', 'Marketing', 'Business Management', 1500, 'MK:002', 'Describe marketing functions and related activities', 'BMA District 2026 #47'),
  ('Which of the following is an advantage of labor specialization by job task:', array['Decreased worker dependency','Improved worker morale','Increased worker efficiency','Reduced boredom'], 2::smallint, 'Increased worker efficiency. Workers become highly skilled at the tasks they perform because they do the same tasks repeatedly. However, worker morale may worsen because of the increased boredom of doing the same job over and over. This can result in increased absenteeism, grievances, and complaints. Worker dependency increases because workers must rely on one another to complete the final product.', 'Economics', 'Business Management', 1500, 'EC:014', 'Analyze impact of specialization/division of labor on productivity', 'BMA District 2026 #48'),
  ('Making a decision when facing an ethical dilemma will most likely make you', array['unhappy.','less content.','anxious.','more satisfied.'], 3::smallint, 'More satisfied. Making a decision when facing an ethical dilemma—even if it''s tough—will make you happier, more satisfied, and less conflicted. Even if your ultimate decision when facing an ethical dilemma is to do nothing, it''s still important to make the decision instead of allowing the ethical dilemma to control your life. Making a decision is not likely to make you feel unhappy, anxious, or less content.', 'Emotional Intelligence', 'Business Management', 1500, 'EI:125', 'Recognize and respond to ethical dilemmas', 'BMA District 2026 #49'),
  ('Which of the following is a characteristic of an income statement:', array['Shows the owner''s financial position','Summarizes expenses and revenue from sales','Is the same as a balance sheet','Lists assets and liabilities'], 1::smallint, 'Summarizes expenses and revenue from sales. An income statement is a business''s financial picture that lists all revenue and expenses for a certain time period. An income statement is not the same as a balance sheet. Characteristics of a balance sheet include listing assets and liabilities and showing the owner''s financial position.', 'Financial Analysis', 'Business Management', 1500, 'FI:094', 'Describe the nature of income statements', 'BMA District 2026 #50'),
  ('Delia is a third-party logistics professional who has been contracted to revamp the product return system for a local distributor. To achieve this, Delia should develop a(n) __________ plan for the distributor.', array['market segmentation','reverse logistics','data mining','order fulfilment'], 1::smallint, 'Reverse logistics. Reverse logistics refers to the backward movement of products through the supply chain, from customers to distributors, manufacturers, or suppliers. By developing a reverse logistics plan, Delia can help her client create a better system of product returns. Order fulfillment is the complete act of receiving, processing, and shipping a customer''s order, and is not directly connected to returning products. Market segmentation is the division of a total market into smaller, more specific groups. Data mining is the process of searching, collecting, and analyzing large amounts of data to extract actionable information.', 'Operations', 'Business Management', 1500, 'OP:677', 'Discuss ethical considerations in supply chain management', 'BMA District 2026 #51'),
  ('A nonprofit organization made plans to build a new office building using funds from grants and loans. However, when an issue with the grant money arose, the organization was forced to rethink its carefully laid plans and go in a different direction. What characteristic of effective plans does this example demonstrate?', array['Feasibility','Flexibility','Simplicity','Goal-alignment'], 1::smallint, 'Flexibility. Effective plans are flexible so that changes can be made relatively easily and quickly. The business world is constantly changing—plans must be able to be adjusted accordingly. Effective plans are also relatively straightforward or simple, so that all team members are able to understand them. Finally, plans should be realistic and aligned with the organization''s ultimate goals. This example demonstrates the importance of flexibility in planning, not simplicity, feasibility, or goal-alignment.', 'Strategic Management', 'Business Management', 1500, 'SM:063', 'Discuss the nature of managerial planning', 'BMA District 2026 #52'),
  ('Six Sigma, SQC, and ISO 9000 are all examples of', array['workplace behavior policies.','decision support systems.','performance appraisal methods.','quality management frameworks.'], 3::smallint, 'Quality management frameworks. To improve quality, managers can use quality management frameworks such as Six Sigma, statistical quality control (SQC), and ISO 9000. Each framework has its own processes and best practices to help companies improve quality. Decision support systems help support the decision-making process through location and presentation of information. Performance appraisal is an evaluation of employee achievement and work. Workplace behavior refers to how people conduct themselves when in places or situations related to their employment. Six Sigma, SQC, and ISO 9000 are not related to decision support systems, performance appraisal, or workplace behavior.', 'Quality Management', 'Business Management', 1500, 'QM:002', 'Describe the nature of quality management frameworks (e.g., Six Sigma, ITIL, CMMI)', 'BMA District 2026 #53'),
  ('Although governments and businesses used computers in limited ways for several decades, the development and widespread use of desktop computers emerged in the 1980s in both homes and businesses, drastically changing the way people and businesses interact. What type of improvement does this situation exemplify?', array['Incremental','Breakthrough','Supplemental','Compliant'], 1::smallint, 'Breakthrough. Continuous improvement is the ongoing practice of looking for ways to increase the levels of excellence of a process, good, or service. Breakthrough improvements often occur suddenly and result in immediate, drastic changes. The emergence of desktop computers changed the way businesses operate. Within a relatively short time, much of today''s workforce now depends on desktop applications to perform their work. Incremental improvement involves carrying out small changes over time. Compliant and supplemental are not types of continuous improvement.', 'Quality Management', 'Business Management', 1500, 'QM:003', 'Discuss the need for continuous improvement of the quality process', 'BMA District 2026 #54'),
  ('A company that wishes to lower its risk management costs might start its own __________ insurance company, which is a type of corporate self-insurance.', array['professional liability','compulsory','captive','medical malpractice'], 2::smallint, 'Captive. A captive insurance company is one that is wholly owned by a parent company and is a form of self- insurance. The parent company is able to pay its premiums to its own captive insurer to protect the company against particular forms of risk. There are a number of reasons that a company may form its own captive insurer, many of which are focused on lowering the costs of risk management. Professional liability insurance protects businesses against claims of negligence. While it may be covered by a captive insurer, it is most often covered by a third-party insurer. Medical malpractice insurance is a form of professional liability insurance. Compulsory insurance is a term for any type of insurance that is required by law.', 'Risk Management', 'Business Management', 1500, 'RM:043', 'Discuss legal considerations affecting risk management', 'BMA District 2026 #55'),
  ('The current price of Sun Valley Corporation stock is $25 per share. The company has one million outstanding shares. On its latest cash flow statement, the corporation reported cash flows from operating activities of $15 million. Calculate the corporation''s price-to-cash flow ratio.', array['2.34','1.67','3.21','5.48'], 1::smallint, '1.67. Price-to-cash flow is a valuation ratio calculated by dividing the stock price of a company by its cash flow per share (price-to-cash flow = current stock price / cash flow per share). The price-to-cash flow ratio of a company can be compared with its competitors to see whether the company''s stock is overpriced or underpriced. To calculate the Sun Valley Corporation''s price-to-cash flow ratio, first calculate the cash flow per share by dividing total cash flow by the number of shares ($15 million / $1 million = $15 per share). Then, divide the stock price by the cash flow per share to calculate the corporation''s price-to-cash flow ratio ($25 / $15 = 1.67).', 'Financial Analysis', 'Business Management', 1500, 'FI:541', 'Interpret cash-flow statements', 'BMA District 2026 #56'),
  ('Which of the following statements about settling a case is true:', array['It requires only one party to agree to settle.','It requires lawyers and courtroom procedure.','It ends a dispute before the end of a trial.','It is typically more expensive than going to trial.'], 2::smallint, 'It ends a dispute before the end of a trial. Settling a case means ending a dispute before the end of a trial. Trials are expensive, but cases that reach settlement can avoid the expense of a trial while still offering some compensation for the wrong that was committed. Settlements do not take place after a trial. Even though they can sometimes speed up the process, lawyers and courtroom procedure are not necessary to reach a settlement. Both parties must agree to the settlement.', 'Business Law', 'Business Management', 1500, 'BL:159', 'Describe factors affecting the settlement of legal matters', 'BMA District 2026 #57'),
  ('When organizational change is implemented effectively, which of the following is a true statement about its impact:', array['It lengthens production cycles.','It increases morale among workers.','It is felt for a short period of time.','It only affects some employees.'], 1::smallint, 'It increases morale among workers. Organizational change management is planned organization-wide changes or alterations to a major component of the company to increase individual and organizational effectiveness. An effective organizational change can increase morale among workers and improve employees'' motivation while also driving positive teamwork and job enrichment. Change at the organizational level affects all employees, not some. Organizational change is typically felt at a deeper level and for a longer period of time, not a short period of time. By improving morale among workers, effective organizational change improves the quality of work while shortening production cycles and, thus, reducing costs.', 'Strategic Management', 'Business Management', 1500, 'SM:094', 'Describe relationship among innovation, learning, and change', 'BMA District 2026 #58'),
  ('One way to prevent breaches of digital customer data is to', array['store data indefinitely.','share data with all employees.','collect as little data as possible.','report data security issues.'], 2::smallint, 'Collect as little data as possible. One way that businesses can prevent large-scale breaches of customer data is to collect as little data as possible. If the business only collects the data that is necessary, rather than keeping a large amount of extraneous personal information, it will be less vulnerable. Sharing data with all employees increases the risk that customer data will be compromised. Storing data indefinitely also increases the risk of a data breach. Reporting data security issues is good practice, but it will not necessarily prevent data breaches in the first place.', 'Operations', 'Business Management', 1500, 'OP:518', 'Comply with strategies to protect digital customer data (e.g., information about customers,', 'BMA District 2026 #59'),
  ('Which of the following is the management function that focuses on matching the appropriate person with the necessary skills for a specific job:', array['Interviewing','Coordinating','Leading','Staffing'], 3::smallint, 'Staffing. Staffing is the management function of finding workers for a business. Recruiting, interviewing, hiring, and training are staffing activities. Leading is an activity that involves influencing and motivating others to take a certain course of action. Coordinating is an organizing activity that involves bringing resources together to accomplish a goal.', 'Strategic Management', 'Business Management', 1500, 'SM:065', 'Describe managerial considerations in staffing', 'BMA District 2026 #60'),
  ('A country''s government changes its policies to enact a trade barrier, impacting companies who do business there. This is an example of __________ risk.', array['currency','political','internal','technological'], 1::smallint, 'Political. Risk is the possibility of loss (failure) or gain (success). There are different types of risk, including political, currency (foreign exchange), internal, external, technological, human, etc. Political risk, a major international risk for businesses, occurs when a country''s government changes its policies, such as by enacting trade barriers or requesting additional funds to export items in the country. This is not an example of currency, internal, or technological risk.', 'Risk Management', 'Business Management', 1500, 'RM:092', 'Describe international considerations affecting risk management', 'BMA District 2026 #61'),
  ('Ahmed wants to determine his company''s earnings before interest, taxes, depreciation, and amortization (EBITDA). Some of the information that he needs to calculate EBITDA is found on the income statement, but other necessary information appears on the cash flow statement. What information does Ahmed need to gather from his company''s cash flow statement?', array['Earnings and depreciation','Amortization and tax','Tax and interest','Depreciation and amortization'], 3::smallint, 'Depreciation and amortization. Earnings before interest, taxes, depreciation, and amortization (EBITDA) measures a company''s overall financial performance and profitability. To calculate EBIDTA, Ahmed must take information from both the income statement and the cash flow statement. Information on the income statement that he needs includes earnings, tax, and interest. He can find the depreciation and amortization figures on the cash flow statement or in the notes to operating profit.', 'Financial Analysis', 'Business Management', 1500, 'FI:541', 'Interpret cash-flow statements', 'BMA District 2026 #62'),
  ('The use of technology in supply chain management often results in', array['improved budgeting.','increased efficiency.','more human error.','decreased efficiency.'], 1::smallint, 'Increased efficiency. By reducing human error and improving overall performance, the use of technology in supply chain management often results in increased efficiency. The use of technology in supply chain management does not necessarily result in improved budgeting. Technology generally increases efficiency and reduces human error.', 'Operations', 'Business Management', 1500, 'OP:478', 'Describe the impact of technology on supply chain management', 'BMA District 2026 #63'),
  ('An American clothing company manufactures most of its apparel overseas in an effort to cut costs. The company was faced with international backlash and declining sales when one of its factories was found to be in violation of numerous workplace safety laws. This is an example of which of the following global supply chain issues:', array['Time zone differences','Language barriers','Delivery and shipping delays','Accountability and compliance'], 3::smallint, 'Accountability and compliance. It is important for companies to consider safety regulations, child labor laws, and fair compensation practices before becoming involved in a global supply chain. Language barriers, time zone differences, and delivery and shipping delays are also important issues involved in global supply chain management; however, they are not described in this situation.', 'Operations', 'Business Management', 1500, 'OP:480', 'Discuss global supply chain issues', 'BMA District 2026 #64'),
  ('Which of the following actions can help a business protect its digital assets:', array['Giving employees full access to all company data','Making an inventory of digital information','Backing up key data once per fiscal year','Allowing employees to bring their own devices to work'], 1::smallint, 'Making an inventory of digital information. Making an inventory of digital information is an effective way to protect a company''s sensitive data. Keeping track of where digital information is stored can help a company access that data in the case of a data breach or other security emergency. Keeping an inventory can also help a company become aware of any security weaknesses that may lead to data theft or misuse. Allowing employees to bring their own devices to work is risky because of the potential for data to be lost or stolen on noncompany devices. Backing up key data is crucial—but once per year is not enough. Information backups should occur frequently to ensure that no data are lost. It''s not a wise idea to allow employees to access any company data that they want. Sensitive information should be protected and only accessible to relevant managers and company leaders.', 'Operations', 'Business Management', 1500, 'OP:517', 'Comply with strategies for protecting business'' digital assets (e.g., website, social media,', 'BMA District 2026 #65'),
  ('When a company uses process thinking to design a process, it should make sure that the process has', array['a deadline.','an unlimited scope.','multiple process owners.','a goal.'], 3::smallint, 'A goal. Businesses use process thinking to define and develop a system to accomplish a specific goal or task. Every process should have a goal, and its outputs should be measured against that goal. Each individual process should also support the overall goals of an organization. A process doesn''t have a specific deadline, since it is a technique used to achieve goals and meet deadlines. Each business process should have a single owner who is responsible for the output and functionality of the process. A business process should have a clearly defined, limited scope.', 'Operations', 'Business Management', 1500, 'OP:474', 'Discuss business process thinking and its impact', 'BMA District 2026 #66'),
  ('A manager watches an employee perform a work activity and writes notes that describe the process. This is an example of capturing knowledge by', array['rationalization.','interrogation.','observation.','imitation.'], 2::smallint, 'Observation. Observation involves obtaining information by watching others perform a task or activity. A business can obtain knowledge about work-task processes by observing employees performing their jobs. The manager is not rationalizing or imitating the employee''s behavior. There is not sufficient information provided to determine if the manager is asking questions or interrogating the employee.', 'Knowledge Management', 'Business Management', 1500, 'KM:005', 'Identify techniques that can be used to capture and transfer knowledge in an organization', 'BMA District 2026 #67'),
  ('At the beginning of a research report, the writer should include the', array['appendices.','purpose of the study.','bibliography.','solution to the problem.'], 1::smallint, 'Purpose of the study. A research report is a written document that summarizes an investigation related to a particular issue or problem. A research report contains many elements. The purpose of the study states why the topic at hand is being investigated. The purpose of the study should be described in the report''s introduction, which is at the beginning of the report. Stating the purpose of the study is important because it lets readers know what they are reading and why. Proposed solutions to a problem (recommendations) are addressed near the end of the document after the research has been presented. The appendices are segments that include supporting information, and are added to the end of a document. The bibliography contains the list of resources from which the writer obtained information for the report. The bibliography is generally placed at the end of the research report—after the recommendations section and before the appendices.', 'Communication Skills', 'Business Management', 1500, 'CO:186', 'Write research reports', 'BMA District 2026 #68'),
  ('Sonya wants to show her project team members the logical relationships among activities in their project. What format should she use to present this information?', array['Milestone and deliverable chart','Project schedule network diagram','Project calendar','Bar chart'], 1::smallint, 'Project schedule network diagram. A project schedule network diagram shows activities and relationships. It is the best method for demonstrating the relationships among activities in a project. A bar chart is a depiction of activities, dates, and durations using vertical and horizontal axes. It does not necessarily show the logical relationships among the activities. A milestone chart is similar to a bar chart, but only shows the start or completion of major deliverables. Again, it does not show the relationships among activities. A project calendar is a tool that identifies working days and shifts that are available for scheduled activities. It is not the best option for showing the relationships among project activities.', 'Project Management', 'Business Management', 1500, 'PJ:010', 'Manage project schedule', 'BMA District 2026 #69'),
  ('A company that makes power tools expects the price of steel to rise steadily over the next several months. What should the company do?', array['Pay attention to cyclical demand.','Avoid inventory carrying costs.','Buy steel in bulk and hold raw materials.','Purchase steel from a foreign vendor.'], 2::smallint, 'Buy steel in bulk and hold raw materials. One of the benefits of holding raw materials inventory is to get the best price for raw materials. If a rise in prices is expected, a company should purchase the raw materials in bulk to save money. While avoiding inventory carrying costs is a good strategy, it might not be worth it if the price of the raw materials is continuing to rise. Cyclical demand is not necessarily related to this issue. Finally, purchasing steel from a foreign vendor will not necessarily help with the rising price of steel.', 'Operations', 'Business Management', 1500, 'OP:336', 'Discuss types of inventory', 'BMA District 2026 #70'),
  ('In the business world, quality often refers to excellence, value, and', array['quantity.','empathy.','conformance.','technology.'], 2::smallint, 'Conformance. In the business world, quality often refers to excellence, value, satisfaction, and conformance. Conforming to predetermined specifications is an aspect of quality that has plenty of examples in the manufacturing industry. Let''s say a manufacturer is producing glass bottles. Each bottle should be a certain size and shape and should have no rough edges. If a bottle does not meet these specifications, it isn''t a quality product. Businesses strive to keep these variations or defects to a minimum, keeping the overall quality of their production output as high as possible. Quality does not typically refer to empathy, technology, or quantity.', 'Quality Management', 'Business Management', 1500, 'QM:001', 'Explain the nature of quality management', 'BMA District 2026 #71'),
  ('Measuring the productivity of a business''s employees is an example of', array['positional analysis.','formal authority.','managerial control.','leadership style.'], 2::smallint, 'Managerial control. One part of the controlling function involves measuring the performance of the business to determine if it is achieving the established objectives. One type of performance measurement involves measuring the productivity of employees. Managers often establish standards that employees are expected to meet, such as number of items produced per hour or the quality of the items produced. Then, managers use these controls to determine if employees are performing as expected. Formal authority is the authority and responsibility officially assigned to an individual who holds a position or a title on an organizational chart. Leadership style is the way or manner in which a leader goes about the task of influencing others. Positional analysis is a study of the tasks and responsibilities of a position and its place in an organization.', 'Strategic Management', 'Business Management', 1500, 'SM:004', 'Describe the nature of managerial control (control process, types of control, what is', 'BMA District 2026 #72'),
  ('The purpose of a project charter is to', array['document what went well during a project.','define what needs to be accomplished.','break down work into smaller activities.','determine when key deadlines will be met.'], 1::smallint, 'Define what needs to be accomplished. A project charter is a document completed at the beginning of a project that lays the foundation of the project. It includes defining what needs to be accomplished during the course of the project. However, the project charter generally does not get into the detail of scheduling key deadlines and breaking down work into smaller activities. Those would be determined after as a part of the project planning process. Documenting what went well during a project happens after a project has been completed, whereas a project charter is created during the initiation phase.', 'Project Management', 'Business Management', 1500, 'PJ:005', 'Initiate project', 'BMA District 2026 #73'),
  ('What is the first part of the litigation process?', array['Appealing the decision','Appearing in court','Filing a motion to dismiss','Investigating the complaint'], 3::smallint, 'Investigating the complaint. When a lawyer is first contacted about a potential lawsuit, they must investigate whether the complaint is worth a lawsuit. This might involve doing research, hiring investigators, or interviewing people involved. Investigating the complaint must occur before anyone appears in court, files a motion to dismiss, or appeals the decision.', 'Business Law', 'Business Management', 1500, 'BL:160', 'Describe the litigation process', 'BMA District 2026 #74'),
  ('Technological tools like email, forums, newsletters, and instant messaging are crucial for effective knowledge management because they', array['decrease interdepartmental interaction.','facilitate ongoing communication.','eliminate the need for customer input.','increase repetition of messaging.'], 1::smallint, 'Facilitate ongoing communication. Tools like email, forums, newsletters, and instant messaging are useful in keeping communication lines open to facilitate knowledge management because they allow for continuous and fast communication. These tools do not eliminate the need for customer input and instead often interpret and use this input. With these tools, communication between departments is increased as they work together to put gathered knowledge to good use. Because of the convenience of these communication tools, messaging is streamlined and repetition and redundancy are decreased.', 'Knowledge Management', 'Business Management', 1500, 'KM:003', 'Explain the use of technology in knowledge management', 'BMA District 2026 #75'),
  ('During an executive staff meeting, the company''s president stated, "Samari Enterprises experienced a three percent increase during the first quarter and a five percent increase during the second quarter of this fiscal year." The company''s president is providing the group with', array['personal opinion.','explicit knowledge.','speculation.','tacit knowledge.'], 1::smallint, 'Explicit knowledge. Explicit knowledge is knowledge or information consisting of words, numbers, codes, processes, and formulas that are easily stored, shared, and quantified (measured). The president of the company was communicating specific, measurable, numerical data. Tacit knowledge is knowledge consisting of personal opinions, experiences, expertise, or understanding that is not easily articulated, stored, or quantified. Speculation is hearsay or rumor.', 'Knowledge Management', 'Business Management', 1500, 'KM:001', 'Explain the nature of knowledge management', 'BMA District 2026 #76'),
  ('Which of the following is a top priority for supply chain managers:', array['Producing an appealing corporate image','Controlling costs','Developing overseas markets','Gaining leverage in negotiations'], 1::smallint, 'Controlling costs. Controlling costs is the top priority of many supply chain managers. In fact, some might argue that controlling costs is the driving force of supply chain management. It is also likely the area where supply chain managers have the most control. Controlling costs has many secondary benefits as well, such as creating value, contributing to profit maximization, and aiding in organizational stability. Developing overseas markets and producing an appealing corporate image are unlikely to be the direct results of supply chain management. Gaining leverage in negotiations is a possible outcome for supply chain managers but is not likely to be a top priority and will not apply to all supply chain managers.', 'Operations', 'Business Management', 1500, 'OP:477', 'Explain the impact of supply chains on business performance', 'BMA District 2026 #77'),
  ('What is a negative effect of employees who are unwilling to share tacit knowledge with one another?', array['Low efficiency','Less competition','High cohesiveness','More disclosure'], 0::smallint, 'Low efficiency. Tacit knowledge is knowledge consisting of personal opinions, experiences, expertise, or understanding that is not easily articulated, stored, or quantified. Tacit knowledge is often acquired by trial and error, which occurs by repeating tasks and activities over time. When an employee devises effective shortcuts or techniques that increase personal productivity, the employee has tacit knowledge. When employees are unwilling to share tacit knowledge that will improve efficiency levels, it takes longer for the company to achieve its goals. Employees who share tacit knowledge may improve the business''s efficiency and create a more open and cohesive work environment, which will reduce the competitiveness among employees.', 'Knowledge Management', 'Business Management', 1500, 'KM:002', 'Discuss the role of ethics in knowledge management', 'BMA District 2026 #78'),
  ('Project managers should take steps to manage project risks before they become project issues. The first step in this process is __________ project risks.', array['responding to','analyzing','identifying','monitoring'], 2::smallint, 'Identifying. You cannot manage a risk if you do not know what it is. The first step in successfully managing project risks is identifying them. This involves brainstorming with your team and collecting information. Risk management also includes analyzing, responding to, and monitoring project risks, but these steps come after the initial risk identification.', 'Project Management', 'Business Management', 1500, 'PJ:009', 'Execute and control projects', 'BMA District 2026 #79'),
  ('The Simpson Company is negotiating discount terms with Cornwell Manufacturing, a prospective vendor. During the negotiation, Cornwell states that it is willing to offer Simpson a six-percent discount on orders over $50,000. Although Simpson would rather have an eight-percent discount, it agrees to the terms, hoping to obtain something it wants later in the negotiation. This is an example of a', array['withdrawal.','concession.','position.','plea.'], 1::smallint, 'Concession. A concession is something that one party gives up during a negotiation. In many situations, one party will give up something that it wants and use it (the concession) as leverage to get something else that it wants later in the negotiation process. Withdrawal is a conflict response mode in which one or both parties exhibit passive behavior and express a low level of cooperation. A plea is a request. A position is what someone believes about an idea or issue.', 'Operations', 'Business Management', 1500, 'OP:337', 'Negotiate terms with vendors in business', 'BMA District 2026 #80'),
  ('If a company wants to ensure that changes are implemented in the best possible way and that those changes will lead to long-term benefits, it should use the __________ approach.', array['change-avoidance','problem-solving','change-management','solution-finding'], 2::smallint, 'Change-management. The change-management approach ensures that changes are implemented in the best possible way and that those changes will lead to long-term benefits. Change management is not referred to as problem-solving, change avoidance, or solution finding.', 'Strategic Management', 'Business Management', 1500, 'SM:095', 'Explain the nature of change management', 'BMA District 2026 #81'),
  ('Which of the following is a benefit of using mediation to resolve disputes:', array['Decisions that carry more weight','Cost-effectiveness and efficiency','Higher payouts for defendants','Unbiased third-party decision maker'], 1::smallint, 'Cost-effectiveness and efficiency. Mediation is an informal process during which two parties meet with an impartial third party to find a mutually satisfactory solution to a problem. A benefit of mediation is that it is cost- effective and efficient, especially compared to going to trial. Mediation does not lead to higher payouts for the defendant. Mediation cannot impose a legally binding decision, so it does not carry more weight. Finally, while there is a third-party mediator, that person does not make decisions. Instead, they help guide the negotiation process while the two parties come to a decision on their own.', 'Business Law', 'Business Management', 1500, 'BL:161', 'Discuss the arbitration/mediation process', 'BMA District 2026 #82'),
  ('Which of the following is a true statement about risk management and ethical behavior in business:', array['Because employees understand right from wrong, they tend to reduce risk levels rather than increase them.','If employees always behave in an ethical manner, the business will virtually eliminate its risk factors.','Businesses often reduce the risk of financial loss by providing ethics training for their employees.','Risk primarily involves the ways in which a firm invests in the stock market, so ethics are not an issue.'], 2::smallint, 'Businesses often reduce the risk of financial loss by providing ethics training for their employees. Because employees'' personal ethics often differ from their employers'' ethics policies, it is important for businesses to provide ongoing ethics training for all employees. If an employee does something unethical (intentionally or unintentionally), the business may be liable for the employee''s actions, which may involve financial losses. Effective risk management involves monitoring many business activities including investments, product quality, sales processes, etc. Risk can be controlled and reduced, but it cannot be eliminated.', 'Risk Management', 'Business Management', 1500, 'RM:041', 'Explain the role of ethics in risk management', 'BMA District 2026 #83'),
  ('Which of the following statements regarding cash flow statements is true:', array['A positive cash flow indicates that a company is financially unhealthy.','The less cash available for business operations, the better for company investors.','A cash flow statement is derived from the income statement and the balance sheet.','A negative cash flow indicates that a company is financially healthy and stable.'], 2::smallint, 'A cash flow statement is derived from the income statement and the balance sheet. When calculating cash flow, companies use income statements and balance sheets to observe how cash is flowing in and out of the company. A negative cash flow does not typically indicate that a company is financially healthy and stable. Generally, a negative cash flow is indicative of financial struggles. Therefore, investors are not likely to be happy if a company doesn''t have much cash available for business operations. A positive cash flow indicates that a company is financially healthy and stable—not unhealthy.', 'Financial Analysis', 'Business Management', 1500, 'FI:541', 'Interpret cash-flow statements', 'BMA District 2026 #84'),
  ('Planning, sourcing, producing, and distributing a product are steps in __________ management.', array['delivery','supply chain','quality','risk'], 1::smallint, 'Supply chain. Supply chain management is a career area in which employees supervise the complete process of getting products in the marketplace. Risk management is a business activity that involves the planning, controlling, preventing, and limiting of business losses and enhancing the possibilities for gain. Delivery is part of supply chain management. Quality management is the ongoing process of planning, implementing, and integrating quality into every aspect of an organization.', 'Operations', 'Business Management', 1500, 'OP:303', 'Discuss the nature of supply chain management', 'BMA District 2026 #85'),
  ('What is Claire doing when she reviews a report that compares the purchase transactions of the company''s four largest customers?', array['Conducting a sales analysis','Organizing an inventory report','Preparing a purchasing forecast','Analyzing service performance'], 0::smallint, 'Conducting a sales analysis. Businesses collect information to analyze all of their business functions. Sales are typically a business''s primary source of income. Businesses review many aspects of sales to analyze and compare product movement, customer activity, salesperson performance, etc. Claire is not preparing a purchasing forecast, organizing an inventory report, or analyzing service performance.', 'Operations', 'Business Management', 1500, 'OP:327', 'Discuss the nature of business analysis', 'BMA District 2026 #86'),
  ('For information to qualify as a trade secret, the information', array['must be commercially valuable.','can be known by a large group of people.','cannot be sold or licensed.','doesn''t need to be protected by a confidentiality agreement.'], 0::smallint, 'Must be commercially valuable. Trade secrets are intellectual property rights or confidential information that can be sold or licensed. For information to qualify as a trade secret, the information must be commercially valuable and be known by only a limited group of persons, rather than a large group of people. In addition, the information must be subject to reasonable steps taken by the rightful holder of the information to keep it secret, including the use of confidentiality agreements.', 'Knowledge Management', 'Business Management', 1500, 'KM:004', 'Explain legal considerations for knowledge management', 'BMA District 2026 #87'),
  ('Bryson is responsible for helping his company properly hire and utilize its employees. Which type of business management and administration career does Bryson have?', array['Human resources management','Operations management','Office management','Business analytics'], 0::smallint, 'Human resources management. Human resources management is the process of planning, staffing, leading, and organizing the employees of the business. Helping the company achieve its goals through the proper hiring and use of employees is one common human resources management job duty. This is not a job duty for employees in supply chain management, operations management, or business analytics.', 'Professional Development', 'Business Management', 1500, 'PD:297', 'Discuss employment opportunities in business management and administration', 'BMA District 2026 #88'),
  ('Sydnie is dividing the deliverables of a project into smaller, more manageable elements of work for her project team. What process of preparing a project''s work breakdown structure is Sydnie executing?', array['Decomposition','Procurement','Feasibility assessment','Communication analysis'], 0::smallint, 'Decomposition. A work breakdown structure (WBS) divides project tasks into small, meaningful components to complete the project. Dividing the entire project into smaller components helps the project manager identify tasks and effectively schedule, assign, and monitor complex project activities. Decomposition is the process of breaking down the work into smaller components. Procurement is the process of obtaining something such as purchasing goods and services for business purposes. The feasibility of carrying out the project is determined before the work breakdown structure is developed. The project manager may analyze the flow of communication during the closing phase of the project and include this information in the lessons-learned document.', 'Project Management', 'Business Management', 1500, 'PJ:006', 'Prepare work breakdown structure (WBS)', 'BMA District 2026 #89'),
  ('Determine the type of project-closing report that would most likely contain the following statement: "In review, group members agreed that additional training before the project began and ongoing technical support during the course of the project would have increased overall efficiency."', array['Executive summary','Lessons learned document','Stakeholder''s expense audit','Termination checklist'], 1::smallint, 'Lessons learned document. Developed during the closing phase of the project, the lessons learned document summarizes the project''s successes and failures. The document also includes suggestions for improvement for similar projects in the future, such as the need for additional training and ongoing technical support. An executive summary is an overview of a report or plan. A termination checklist is a list of tasks that need to be done during the closing phase of a project. An expense audit involves reviewing and evaluating various project expenses.', 'Project Management', 'Business Management', 1500, 'PJ:008', 'Close project', 'BMA District 2026 #90'),
  ('What occurs during the first stage of the change management life cycle?', array['Organizations identify and communicate the need for change to employees.','Organizations carry out a strategic plan for implementing desired change.','Organizations agree on a strategic plan for implementing the desired change.','Organizations engage in dialogue to determine how to best implement change.'], 0::smallint, 'Organizations identify and communicate the need for change to employees. The first stage of the change management life cycle involves realizing the need for change and explaining this to employees in an understandable manner. Engaging in dialogue to determine how to best implement change, agreeing on a strategic plan for implementing the desired change, and carrying out a strategic plan for implementing desired change are all actions taken in subsequent stages of the change management life cycle.', 'Strategic Management', 'Business Management', 1500, 'SM:096', 'Explain the change-management lifecycle', 'BMA District 2026 #91'),
  ('Which of the following is an example of a reorder:', array['Mr. and Mrs. Travis ordered a dining table and chairs in a wood finish that the furniture store doesn''t normally carry.','The Powell Company did not order enough paper towels for the month, so it ordered an additional four cases.','Sims Steakhouse received six out of eight cases of glassware on Monday because the vendor ran out of stock.','Henry''s Hardware Store ordered 35 model-N1 hammers and 2 cases of ¼" stainless steel bolts from Franklin Tool Manufacturers.'], 1::smallint, 'The Powell Company did not order enough paper towels for the month, so it ordered an additional four cases. A reorder involves ordering items that the company has previously ordered. The Powell Company placed a reorder because it submitted a second order for the same product (paper towels) to its vendor. A backorder occurs when a vendor ships part of an order on time and the rest of the order later when the stock is available. Mr. and Mrs. Travis placed a special order, which is a request for a custom item that a vendor does not normally carry in stock. Henry''s Hardware Store placed a regular order, which involves providing the vendor with the specifications of items that the business wants to order.', 'Operations', 'Business Management', 1500, 'OP:250', 'Describe types of purchase orders', 'BMA District 2026 #92'),
  ('Supply chain network design improves service and reduces cost by aligning purchasing, production, warehousing, inventory, and', array['marketing.','transportation.','promotion.','the sales force.'], 1::smallint, 'Transportation. Supply chain network design aligns purchasing, production, warehousing, inventory, and transportation. Supply chain network design does not incorporate marketing, promotion, or the sales force.', 'Operations', 'Business Management', 1500, 'OP:479', 'Describe supply chain networks', 'BMA District 2026 #93'),
  ('Before knowledge can be reused or shared, it must be', array['embedded.','recognized.','manipulated.','analyzed.'], 1::smallint, 'Recognized. The first phase of the knowledge management process is discovery and detection, during which knowledge is recognized and categorized. Knowledge must be recognized before it can be embedded, analyzed, or manipulated.', 'Knowledge Management', 'Business Management', 1500, 'KM:018', 'Apply knowledge management processes', 'BMA District 2026 #94'),
  ('A project-management software program that includes functions that store and calculate accounting information, such as amortization and expenses, has __________ capabilities.', array['comprehensive operating and scheduling','task delegation and charting','resource scheduling and leveling','cost assignment and tracking'], 3::smallint, 'Cost assignment and tracking. There are many project-management software programs available with a variety of capabilities to accommodate different types of projects. A business that is working on a complex project may want to use a cost assignment and tracking function program, which calculates and tracks accounting information. The cost assignment and tracking function is beneficial when the project consists of several hundred activities and resources. The resource scheduling and leveling function efficiently facilitates the scheduling of materials, equipment, and personnel. The leveling function, which relates to the resource scheduling function, helps project managers manage workloads, process bottlenecks, etc. Task delegation can be documented and tracked in a variety of ways, including Gantt charts. Programs that contain scheduling and operations capabilities may or may not include accounting applications.', 'Information Management', 'Business Management', 1500, 'NF:130', 'Utilize project-management software', 'BMA District 2026 #95'),
  ('A company wants to be alerted to security breaches and other IT threats. What type of software should the company invest in?', array['Presentation','Word processing','Risk management','Threat prediction'], 2::smallint, 'Risk management. If a company wants to be notified of security breaches, it should invest in risk management software. Word-processing and presentation software would not help with this. Threat prediction software is not a common name for risk management software.', 'Risk Management', 'Business Management', 1500, 'RM:042', 'Describe the use of technology in risk management', 'BMA District 2026 #96'),
  ('Which of the following is a true statement about the responsibilities associated with managing a project team:', array['The most important aspect of managing a project team is developing an overall operating budget for the organization.','It is more important for effective project managers to have financial-management expertise than effective communication skills.','Project managers usually require team members to work out any conflicts they have on their own.','Project managers are often responsible for coordinating the activities of team members from several departments.'], 3::smallint, 'Project managers are often responsible for coordinating the activities of team members from several departments. Many types of projects require the input and skills of team members from different departments— finance, legal, production, research and development, etc. When managing cross-functional project teams, the project manager must understand each team member''s role in the project so they can effectively coordinate all of the activities that need to be completed for the project. Although the project manager may be responsible for developing a budget for the project, the operations manager is usually responsible for developing the business''s operating budget. Because team members have different experiences, skills, and perceptions, project managers may, in some situations, need to intervene and help resolve conflicts. Although financial- management expertise may be important, project managers must have effective communication skills in order to guide the team members'' activities and help them to resolve problems and conflicts.', 'Project Management', 'Business Management', 1500, 'PJ:007', 'Manage project team', 'BMA District 2026 #97'),
  ('The customer service representatives of a car loan company handle several different types of requests including payments, loan financing, and other general requests. The company determines that the requests are very time-consuming when employees aren''t familiar with a procedure. The company implements a business process change that requires agents to specialize in particular procedures to increase their efficiency. Which of the following caused this business process change to be made:', array['Quality','Productivity','Risk management','Customer experience'], 1::smallint, 'Productivity. The company is concerned with the time required to handle customer requests, so the change is made to improve productivity. In the situation described there is no indication that quality of service or customer experience is impacted by the employee''s unfamiliarity with procedures. There''s no indication that the situation requires the management of risk.', 'Operations', 'Business Management', 1500, 'OP:476', 'Explain the causes of business process changes', 'BMA District 2026 #98'),
  ('The primary purpose of the organizing function of management is to provide', array['leverage.','structure.','insight.','motivation.'], 1::smallint, 'Structure. The organizing function of management focuses on setting up the way the business''s work will be done. Organizing provides the business with structure—a systematic, orderly way for carrying out activities to accomplish the business''s goals. Insight can help managers develop the best structure for the business. Leverage refers to the amount of power one person holds during a negotiation. Motivation is directing activity.', 'Strategic Management', 'Business Management', 1500, 'SM:064', 'Explain managerial considerations in organizing', 'BMA District 2026 #99'),
  ('Which of the following is a benefit of the directing function of management:', array['It helps determine company goals.','It makes sure everyone knows what their role is.','It allows managers to check progress.','It helps employees coordinate their work.'], 3::smallint, 'It helps employees coordinate their work. Directing is a management function that brings many benefits to organizations. One is that managers direct employees so that their work and effort is coordinated. Without direction, employees tend to work in isolation, leading to duplication of tasks and less efficiency. Directing does not necessarily ensure that everyone knows what their role is; this benefit is more directly related to organizing. Directing does not necessarily determine company goals; this benefit is more directly related to the planning function. Finally, directing does not necessarily allow managers to check progress; this benefit is more closely associated with the controlling function.', 'Strategic Management', 'Business Management', 1500, 'SM:066', 'Discuss managerial considerations in directing', 'BMA District 2026 #100'),
  ('To obtain a job promotion is an example of a __________ goal.', array['physical','career','social','personal'], 1::smallint, 'Career. Career goals are goals connected with work (e.g., added responsibility, a new job title, or a promotion). An example of a personal goal might be to improve self-control in trying situations. To run two miles every day is an example of a physical goal. To make new friends is an example of a social goal.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:018', 'Set personal goals', 'Hospitality District 2026 #1'),
  ('Which of the following is a capability of presentation software:', array['Connecting several computers','Combining animation and sound','Copying and printing documents','Calculating mathematical data'], 1::smallint, 'Combining animation and sound. Presentation software programs give the user the capability of presenting information by combining graphics, text, animation, photographs, and sound. Presentation software can be used to create slide shows, multimedia presentations, etc. This software enables users to develop visual presentations that are lively, colorful, and appealing to viewers. Presentation software programs are typically not used to connect several computers, copy and print documents, or calculate mathematical data.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:008', 'Demonstrate basic presentation applications', 'Hospitality District 2026 #2'),
  ('To evaluate an online source, what aspect would you consider when assessing whether its information is easy to read?', array['Relevance','Objectivity','Timeliness','Presentation'], 3::smallint, 'Presentation. Presentation is the way in which the information is communicated. It addresses such factors as clarity of language used, sufficiency of font size, clarity of layout, effectiveness of colors, usefulness of graphics or photos, clarity of audio or video (if included), and helpfulness of any animation used. Presentation is particularly important on the internet since so much time is spent reading online. Relevance deals with whether the information pertains to the topic being researched. Objectivity deals with presenting unbiased information. Timeliness deals with how up to date the information is; however, the importance of timeliness will vary from topic to topic.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:079', 'Evaluate quality and source of information', 'Hospitality District 2026 #3'),
  ('Managers are more likely to persuade employees to follow new procedures if the managers have', array['self-motivation.','enthusiasm.','organizational skills.','credibility.'], 3::smallint, 'Credibility. Credibility is believability. If employees believe what managers are saying, they are more likely to be persuaded to do what the managers want them to do. Managers develop credibility by always being truthful with employees. As a result, employees often like and trust managers who are credible and, therefore, are willing to follow their instructions. Having organizational skills, enthusiasm, or self-motivation does not necessarily mean that managers will be able to persuade employees.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:012', 'Persuade others', 'Hospitality District 2026 #4'),
  ('Inventing and testing a brand-new type of water-filtration system is an example of a(n) __________ project.', array['platform','R&D','derivative','breakthrough'], 1::smallint, 'R&D. Inventing and testing a brand-new type of water-filtration system is an example of an R&D project, a risky endeavor that creates new technologies or processes. A derivative project enhances, adds to, or extends an existing project. A platform project creates something entirely new. A breakthrough project relies on the use of new technology but does not create new technology as an R&D project does.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:158', 'Explain the nature of project management', 'Hospitality District 2026 #5'),
  ('Writing a follow-up letter after a job interview allows a job applicant the opportunity to', array['describe personal strengths and weaknesses.','restate their interest in the position.','provide references and recommendations.','explain their training and experience.'], 1::smallint, 'Restate their interest in the position. A follow-up letter allows a job applicant the opportunity to thank the interviewer for a job interview. It also allows the job applicant to restate their interest in the job and reinforce the ways in which they can benefit the company if hired. The applicant describes specific training and experience in a résumé, which may also include the applicant''s references. The applicant is usually asked about personal strengths and weaknesses during the interview.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:029', 'Write a follow-up letter after job interviews', 'Hospitality District 2026 #6'),
  ('Which of the following is a result of maintaining a code of ethics:', array['Poor organizational integrity','Improved employee loyalty','Diminished office morale','Lower legal compliance'], 1::smallint, 'Improved employee loyalty. Maintaining a code of ethics can help improve employee loyalty because people typically like affiliating with ethical organizations—and tend to stay away from organizations that act unethically. Maintaining a code of ethics also results in increased organizational integrity, greater legal compliance, and improved office morale.', 'Human Resources Management', 'Hospitality & Tourism', 1500, 'HR:411', 'Explain the role of ethics in human resources management', 'Hospitality District 2026 #7'),
  ('The federal government stimulates the flow of money by', array['raising taxes.','spending less.','raising interest rates.','increasing services.'], 3::smallint, 'Increasing services. An increase in the level of government services would increase the flow of money in the economy. The federal government restricts the flow of money by raising taxes, raising the interest rates to borrow money, or by purchasing fewer goods and services with which to run the government.', 'Economics', 'Hospitality & Tourism', 1500, 'EC:018', 'Determine the impact of business cycles on business activities', 'Hospitality District 2026 #8'),
  ('Why is it so important for startup companies to maintain happy, engaged employees?', array['Entrepreneurs can make money off of employees by overworking them.','Happy employees are more likely to purchase the business''s products.','Employees have practically no influence on a company''s profits.','Employees have a large impact on the success of a business.'], 3::smallint, 'Employees have a large impact on the success of a business. Entrepreneurs who integrate ethical decision - making into all aspects of their operations are more likely to attract and retain quality employees —and keep them happy and engaged in the company''s mission. This is especially important for new business ventures since a startup''s employees can make or break a company''s success. It is not necessarily true that happy employees will buy their company''s products. It would not be ethical to overwork employees in an attempt to make money off of them.', 'Entrepreneurship', 'Hospitality & Tourism', 1500, 'EN:044', 'Describe the use of business ethics in entrepreneurship', 'Hospitality District 2026 #9'),
  ('Because businesses change as often as people do, change leaders must be careful to avoid', array['making managers upset.','big changes.','making promises.','linear thinking.'], 3::smallint, 'Linear thinking. Because businesses are not static, change leaders must be careful to avoid linear thinking. This means that change can occur in a "two steps forward, one step back" manner, and there may be a loss of productivity along the way. Change leaders should expect this and not become discouraged by it. Change leaders don''t want to upset managers, but this is not because businesses change. Big changes are sometimes necessary. It''s OK for change leaders to make promises as long as they can keep them.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:005', 'Lead change', 'Hospitality District 2026 #10'),
  ('To effectively follow directions in the workplace, it is important to', array['respond with a good attitude.','listen passively.','rely on your memory.','avoid asking questions.'], 0::smallint, 'Respond with a good attitude. To effectively follow directions in the workplace, it is important to respond with a good attitude. It is important to demonstrate respect and a good attitude when your manager or supervisor gives you instructions. Demonstrating a bad attitude will not only make it more difficult to the person giving directions, but it will also likely make the task you''re performing more difficult. Asking questions, actively listening, and taking notes (rather than relying on your memory) are important steps you can take to effectively follow directions in the workplace.', 'Communication Skills', 'Hospitality & Tourism', 1500, 'CO:119', 'Follow oral directions', 'Hospitality District 2026 #11'),
  ('A memo is typically used for communication that takes place', array['among competitors.','between friends.','infrequently.','within a business.'], 3::smallint, 'Within a business. Memos are a frequently used form of brief, written communication exchanged by people within an organization. Memorandums are rarely used among competitors or between friends.', 'Communication Skills', 'Hospitality & Tourism', 1500, 'CO:094', 'Prepare simple written reports', 'Hospitality District 2026 #12'),
  ('When giving a presentation, a presenter should speak', array['slowly so the audience has time to take notes.','quickly so the audience doesn''t get bored.','loudly so the audience can hear their message.','with confidence to create interest in their speech.'], 3::smallint, 'With confidence to create interest in their speech. It''s important for a presenter to speak with confidence and energy to create interest in their message. Speakers should not speak too slowly, quickly, or loudly, because doing so can make it difficult for the audience to understand.', 'Communication Skills', 'Hospitality & Tourism', 1500, 'CO:025', 'Make oral presentations', 'Hospitality District 2026 #13'),
  ('Which of the following is a result of a leader abusing their power:', array['Decreased productivity','Less employee turnover','Increased team morale','High employee motivation'], 0::smallint, 'Decreased productivity. A leader who abuses their power brings down morale by causing followers to feel anxious and intimidated. This can harm overall productivity as followers lose their motivation and inspiration to do good work. The abuse of power can also lead to higher turnover in the workplace, since employees are unlikely to remain at a company where they feel threatened or disrespected.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:135', 'Use power appropriately', 'Hospitality District 2026 #14'),
  ('A ski resort that is mining data from its database has detected an anomaly (a deviation from standard behavior) that occurred on a holiday weekend. Which of the following is most likely to be the anomaly:', array['Visitors to the website also viewed nearby holiday attractions.','The resort was booked to full capacity, predominately by families.','Visitors to the website also viewed nearby hotels and restaurants.','Food service decreased when the resort was filled to capacity.'], 3::smallint, 'Food service decreased when the resort was filled to capacity. A decrease in food service is an anomaly because food service is much more likely to increase when the resort is filled to capacity. The resort is likely to be booked on the busy holiday weekend by families free to travel during that time. It is common for website visitors to view nearby hotels, restaurants, and nearby holiday attractions.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:149', 'Describe data mining tools and techniques', 'Hospitality District 2026 #15'),
  ('A business decides to use some surplus cash to pay off a loan early. This is an example of using financial information to', array['create budgets.','increase sales.','make purchases.','manage debt.'], 3::smallint, 'Manage debt. Paying off a loan early is one way a business can manage its debt. Analyzing financial information helps managers understand the different ways its debt can be managed. Paying off a loan early is not the same as increasing sales, making purchases, or creating budgets.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:579', 'Describe the need for financial information', 'Hospitality District 2026 #16'),
  ('Alexis can''t quit thinking about her father''s recent job loss and has trouble listening to her friend talk about their prom dress. This is an example of', array['an internal distraction.','random thoughts.','an environmental distraction.','focused attention.'], 0::smallint, 'An internal distraction. When a listener can''t quit thinking about something else, they are dealing with an internal distraction. Environmental distractions are distractions present in the listening environment, not within the speaker''s mind. A speaker with focused attention would not experience distractions. Random thoughts are thoughts that suddenly occur and distract the listener.', 'Communication Skills', 'Hospitality & Tourism', 1500, 'CO:017', 'Demonstrate active listening skills', 'Hospitality District 2026 #17'),
  ('One real-life opportunity in which you will need to "sell" yourself and your ideas is', array['the first day of school.','a job interview.','meeting new friends.','a sports game.'], 1::smallint, 'A job interview. A job interview is a perfect example of a real-life opportunity in which you''ll need to "sell" an idea-the idea of yourself as a future employee. You won''t necessarily need to "sell" yourself or your ideas when meeting new friends, on the first day of school, or during a sports game.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:108', '"Sell" ideas to others', 'Hospitality District 2026 #18'),
  ('The Value Corporation is examining a potential acquisition target''s employment contracts, liabilities, real property, permits, licensing agreements, pending litigation, and compliance with legal requirements. The Value Corporation is conducting legal', array['segmentation.','due diligence.','leveraging.','credit rating.'], 1::smallint, 'Due diligence. Prior to making an acquisition decision, most companies conduct an investigation or examination of the potential acquisition target. Companies conducting due diligence typically do so to determine how to structure the acquisition and how much money to pay for the acquisition. When conducting legal due diligence, a company analyzes its target''s compliance with legal obligations and requirements. Doing so helps the company determine how much risk is involved in acquiring the target business. Co mpanies do not conduct legal segmentation, legal credit rating, or legal leveraging during the acquisition process. Segmentation involves dividing customers into smaller groups based on similarities and differences. A credit rating is the score assigned to a borrower based on previous loans. Leveraging involves using something to its maximum advantage.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:356', 'Explain legal considerations for finance', 'Hospitality District 2026 #19'),
  ('According to the law of diminishing returns, what usually decreases at some point with the addition of more employees if all other factors stay the same?', array['Depreciation','Inequality','Productivity','Consumption'], 2::smallint, 'Productivity. The law of diminishing returns states that if all the factors of production remain the same except one, additions to the one variable factor will eventually decrease the level of productivity. Most businesses are most productive with a certain number of employees because there is only a certain amount of space, equipment, and supplies available. When a business hires additional employees but does not increase these other factors, overall productivity eventually decreases because employees get in each other''s way and do not have the equipment they need. Depreciation is the reduction in value of goods occurring over a period of time. Inequality means that two or more entities are not equal. Consumption is the process or activity of using goods and services.', 'Economics', 'Hospitality & Tourism', 1500, 'EC:023', 'Explain the impact of the law of diminishing returns', 'Hospitality District 2026 #20'),
  ('Which of the following personal traits help an employee take initiative when completing a complex task:', array['Self-confidence','Shyness','Anxiety','Honesty'], 0::smallint, 'Self-confidence. People with self-confidence believe in themselves and their abilities, making it is easier for them to complete complex tasks. Being shy, honest, or anxious is not likely to help an employee take initiative when completing a complex task. In fact, being shy or anxious could even hinder a person''s ability to take initiative when completing a complex task.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:024', 'Explain the importance of demonstrating initiative', 'Hospitality District 2026 #21'),
  ('After a few months at her new job as a manager, Stefanie feels discouraged. She is struggling to oversee one employee, while other managers at the company oversee at least five direct reports. Which of the following is the most likely reason why Stefanie is struggling:', array['She does not have the ability to make decisions.','She has less experience than other managers.','Her direct report is a competent worker.','She is not providing enough direction.'], 1::smallint, 'She has less experience than other managers. One reason that some managers can take on more direct reports than others is that they have more management experience. The more management experience you have, the better equipped you are to manage many employees. There is no indication that Stefanie is not providing enough direction. Having a competent worker on her staff would make it easier for Stefanie to manage more employees, rather than more difficult. Finally, there is no indication that she does not have the ability to make decisions.', 'Strategic Management', 'Hospitality & Tourism', 1500, 'SM:100', 'Explain factors that affect management', 'Hospitality District 2026 #22'),
  ('A business owner carries insurance that covers income losses that the business may experience if hurricane damage prevents the business from operating for a short period of time. What type of property insurance does the business owner carry?', array['No-fault','Disability','Business-interruption','Collision'], 2::smallint, 'Business-interruption. Hurricanes and other natural disasters can shut down a business for weeks or months. When a business does not have electricity, products, or a safe building in which to operate, employees cannot work, and the business cannot earn money. Business-interruption insurance helps businesses cover income losses during the period in which they are unable to operate. Disability insurance provides individuals with financial support when they cannot work due to an injury or illness. Collision and no-fault are types of automobile insurance.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:081', 'Describe the concept of insurance', 'Hospitality District 2026 #23'),
  ('Which form of technology creates tangible prototypes and products?', array['3D printing','Social media','Smartphones','Computer-aided design'], 0::smallint, '3D printing. Computer-aided design (CAD), social media, and smartphones are very useful in operations, but they can''t produce a tangible prototype or product. 3D printers allow companies to create cheaper prototypes and products in smaller quantities. This technology is currently being used to produce apparel, automobile and aircraft parts, medical devices, and more.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:189', 'Explain the nature of operations', 'Hospitality District 2026 #24'),
  ('Dallas and Edisyn are in business together and each of them has unlimited liability. Dallas and Edisyn''s business is an example of a', array['joint venture.','general partnership.','corporation.','franchise.'], 1::smallint, 'General partnership. A general partnership is a type of partnership agreement in which all partners are liable for a business''s losses. A corporation is a form of business ownership that is owned by stockholders who have purchased units or shares in the company. A joint venture is an arrangement that involves two or more businesses entering into a relationship by combining complementary resources for the benefit of all parties. The joint-venture relationship is usually for a short term or for a single project. A franchise is a contractual agreement between a parent company and a franchisee and allows the franchisee to distribute the parent company''s goods and services for a certain amount of money.', 'Business Law', 'Hospitality & Tourism', 1500, 'BL:003', 'Explain types of business ownership', 'Hospitality District 2026 #25'),
  ('Which of the following is the primary reason for a business''s employees to learn as much as possible about the business and its products:', array['To create publicity for the business','To assist coworkers','To answer customers'' inquiries','To reduce the promotional budget'], 2::smallint, 'To answer customers'' inquiries. Customers expect a business''s employees to be able to answer all of their inquiries, especially those about products the customers want to buy. When employees can answer customer inquiries, they help to create a good image for the business. Being knowledgeable about the business and its products may enable employees to help each other, but that is not a primary reason for them to be knowledgeable. Knowledgeable employees do not necessarily create publicity for the business or reduce its promotional budget.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:006', 'Respond to customer inquiries', 'Hospitality District 2026 #26'),
  ('Leo is a clerk for a local hotel known for its two key values: honesty and exceptional service. One day, he is having trouble checking a couple into their room and realizes that someone on staff never completed their reservation. The room is no longer available. Leo tells the couple that the hotel has made a mistake, but that he will take care of it. Within the hour, he has consulted his manager and checked the couple into an upgraded room at no additional cost. Did Leo reinforce the company image in this interaction?', array['No; he gave the company a negative brand image by admitting that the hotel made a mistake.','Yes; he consulted his manager and made sure to go up the chain of command before proceeding.','Yes; he was transparent about the hotel''s mistake and went above and beyond to assist the customers.','No; he should not have been the one to correct the mistake, because he was not the one to make it.'], 2::smallint, 'Yes; he was transparent about the hotel''s mistake and went above and beyond to assist the customers. The hotel is a company that strives to be honest and provide exceptional service. Leo showed honesty by admitting a mistake was made, and he provided quality service by ensuring the couple was taken care of, even if it meant that they did not pay extra money for an upgraded room. Consulting a manager before proceeding might have been preferred by the company, but it is not an action that reflects on the comp any''s image. Intentionally trying to hide that the hotel made a mistake would go against the hotel value of honesty. If Leo had refused to correct the mistake, he would not have provided exceptional service.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:002', 'Determine ways of reinforcing the company''s image through employee performance', 'Hospitality District 2026 #27'),
  ('Stella has just finished designing the webpage for her new business. Next, she needs to select a __________ and register the website''s __________.', array['media permit; server','hyperlink; modem','web host; domain name','file link; Ethernet'], 2::smallint, 'Web host; domain name. After creating a webpage, the developer needs to post the webpage through a web host (web server) or internet service provider (ISP). The web host may charge a fee to post and store the webpage, although some web hosts will provide the service free of charge. The domain name is the business''s web address. Internet users enter the web address to view Stella''s website. Stella can register her domain name directly with the Internet Corporation for Assigned Names and Numbers (ICANN). Or, Stella can work with her web host to register the domain name for her. Stella does not need to register a hyperlink, media permit, or file link with any organization. A hyperlink (link) is the component of an electronic document (file) that can be clicked on to jump to another place within the document or into a different document. A modem is an internal or external computer communications device that is used to transmit information over a particular medium such as telephone lines or television cables. Ethernet is a local area network.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:042', 'Create and post basic web page', 'Hospitality District 2026 #28'),
  ('Imagine that you are at work when you witness your coworker fall and injure their leg. What is the first thing you should do?', array['Call human resources.','Look up company protocol.','Ask them what they were doing.','Attend to the injury.'], 3::smallint, 'Attend to the injury. The first priority in an accident situation is responding to the medical needs of the person(s) in the accident. Looking up company protocol, calling human resources, and finding out how the accident occurred can all wait until after the injury is attended to.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:009', 'Explain procedures for handling accidents', 'Hospitality District 2026 #29'),
  ('Which of the following is a reason that businesses extend credit to customers:', array['To save money','To be competitive','To purchase stock as needed','To take advantage of the convenience'], 1::smallint, 'To be competitive. Businesses must compete with each other for customers. The convenience of being able to buy now and pay later is often the deciding factor for customers in selecting a company with which to do business. Extending credit to customers does not help the business to purchase stock as needed. It may, in fact, make it more difficult since the business may not have as much cash on hand to pay for stock as it would if its customers paid in cash. Extending credit is an expense to the business, not a saving.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:002', 'Explain the purposes and importance of credit', 'Hospitality District 2026 #30'),
  ('Which of the following is a specific goal:', array['Increase sales.','Improve profitability by 10%.','Increase efficiency/productivity.','Support a cause.'], 1::smallint, 'Improve profitability by 10%. Improving profitability by 10% would be considered a specific goal. Many companies would like to improve profitability, but the specific percentage would vary from organization to organization. Goals are statements that clearly describe tasks to be accomplished. Some are specific, and some are general. Increasing efficiency/productivity, supporting a cause, and increasing sales are all general goals with no specific benchmarks attached.', 'Marketing', 'Hospitality & Tourism', 1500, 'MK:015', 'Discuss actions employees can take to achieve the company''s desired results', 'Hospitality District 2026 #31'),
  ('User manuals, orientation guides, and standard operating procedures (SOPs) are examples of __________ business writing.', array['transactional','persuasive','informational','instructional'], 3::smallint, 'Instructional. User manuals, orientation guides, and standard operating procedures (SOPs) are examples of instructional business writing, or writing that provides readers with information they need to complete a task, assignment, or process. While these documents may also be informational, their primary purpose is to provide instructions. User manuals, orientation guides, and SOPs are not typically persuasive or transactional.', 'Communication Skills', 'Hospitality & Tourism', 1500, 'CO:088', 'Select and utilize appropriate formats for professional writing', 'Hospitality District 2026 #32'),
  ('A risk involved with information management is leaving customers unprotected from', array['identity theft.','bad customer service.','high prices.','faulty products.'], 0::smallint, 'Identity theft. A risk involved with information management is leaving customers unprotected from identity theft. An information management program that does not use technology properly may put customers'' personal information at risk. Appropriate information management will not necessarily protect customers from bad service, high prices, or faulty products.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:110', 'Discuss the nature of information management', 'Hospitality District 2026 #33'),
  ('Which of the following is an example of an extensive decision:', array['Booking an airline flight for a business trip','Wearing a blue suit to a meeting','Hiring a new department manager','Printing a document on yellow paper'], 2::smallint, 'Hiring a new department manager. An extensive decision is a type of decision that requires a lot of consideration. Hiring a department manager is an extensive decision because the decision maker(s) must evaluate each applicant''s skills in relation to the standards and expectations for the position. Often, this requires a lot of input from others, including other department managers and executive -staff members. Printing a document on yellow paper and wearing a blue suit to a meeting are routine decisions. Bo oking an airline flight for a business trip is an example of a limited decision because the individual has a few alternatives (flights) from which to choose.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:017', 'Make decisions', 'Hospitality District 2026 #34'),
  ('A responsible employee who realizes that they have given a fellow employee the wrong answer to a work question would handle the situation by', array['apologizing and giving the right answer.','pretending that they gave the right answer.','refusing to answer questions in the future.','letting the other employee figure it out.'], 0::smallint, 'Apologizing and giving the right answer. A responsible person acknowledges their mistakes as soon as they are aware of them and then corrects them whenever possible. Since an incorrect answer may have caused a problem for the other employee, an apology is also in order. Letting the other employee figure out that the answer was incorrect, pretending that the right answer was given, and refusing to answer questions in the future are examples of irresponsible behavior.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:021', 'Demonstrate responsible behavior', 'Hospitality District 2026 #35'),
  ('Which of the following is an example of someone who is modeling ethical behavior:', array['You try to tell the truth, but sometimes you lie to get out of trouble.','Erica shows her friends how to make braided friendship bracelets.','Your sister always follows the speed limit when she drives you places.','Luke reads the terms and conditions before downloading software.'], 2::smallint, 'Your sister always follows the speed limit when she drives you places. Modeling ethical behavior involves demonstrating ethical actions to other people so they will learn through observing you. Your sister is modeling ethical behavior because she is demonstrating an ethical action (following traffic laws) so that you will do the same. Erica is modeling behavior to her friends, but making friendship bracelets is not an example of ethical behavior. Reading the terms and conditions before downloading software is not an example of modeling ethical behavior. If you lie to get out of trouble, you are not modeling ethical behavior.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:132', 'Model ethical behavior', 'Hospitality District 2026 #36'),
  ('An apartment management firm plans to open a new building in time for college students to lease it for the upcoming year. This is an example of how', array['defining scope is the most important aspect of planning.','project planning keeps the focus on the overall goal.','a project''s team members impact project planning.','the business environment can affect project planning.'], 3::smallint, 'The business environment can affect project planning. The world around you can change the way you plan your project. In this case, the arrival of college students affects the planned schedule for a new apartment building. The apartment management firm is considering changes in the market when planning for its new project. This is not an example of how a project''s team members impact project planning, how project planning keeps the focus on the overall goal, or how defining scope is the most important aspect of planning.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:519', 'Plan project', 'Hospitality District 2026 #37'),
  ('Which of the following is a key reason why it is important for businesses to keep promotional records:', array['To document employees'' regular and overtime wages','To discuss reasons for an employee''s promotion','To time their promotions appropriately','To maintain adequate inventory levels'], 2::smallint, 'To time their promotions appropriately. Promotional records are documents containing information about communications that businesses use to inform, persuade, or remind customers of their products, images, or ideas. A key reason it is important for businesses to keep promotional records is to time their promotions effectively. Another primary reason is to evaluate the effectiveness of their promotions. Maintaining adequate inventory levels is a reason that businesses use inventory records, not promotional records. Discussing reasons for an employee''s promotion relates to personnel records rather than promotional records. Documenting employees'' regular and overtime wages is a reason that businesses use payroll records, not promotional records.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:001', 'Describe the nature of business records', 'Hospitality District 2026 #38'),
  ('Which of the following is a promotional method that enables businesses to introduce new products and generate new sales leads at the same time:', array['Cash rebates','Free samples','Sales contests','Trade shows'], 3::smallint, 'Trade shows. A trade show is a promotional method that many businesses use to introduce new products, generate new sales leads, and contact current customers at the same time. A trade show gives businesses the opportunity to display their products and meet with a large number of potential and current customers. Many businesses spend a significant portion of their promotional budgets on trade shows because they are an effective promotional method. Cash rebates involve returning part of the price a customer pays for a good or service. A sales contest is a way of motivating salespeople to increase their sales performance. Free samples are offers of a small amount of a product.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:036', 'Utilize resources that can contribute to professional development (e.g., trade', 'Hospitality District 2026 #39'),
  ('Which of the following demonstrates thinking uncreatively:', array['Role-playing','Brainstorming','Determining the facts','Stimulating your senses'], 2::smallint, 'Determining the facts. By determining the facts, you are already working on creative problem solving. You should work on getting your creativity going before you try to solve any problems in a creative way. Role - playing, brainstorming, and awakening your senses are ways of being creative. Role-playing is the process of assuming roles and acting through a given situation. Brainstorming is a creative thinking technique involving the identification of as many different ideas as possible during a certain time frame. By stimulating (awakening) your senses, you can do more to enhance your senses and their awareness, allowing you to create more.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:012', 'Demonstrate appropriate creativity', 'Hospitality District 2026 #40'),
  ('A human resources manager sets up a digital system for maintaining employee records. What type of resource is the manager using?', array['Natural','Human','Financial','Material'], 3::smallint, 'Material. Material resources are equipment and supplies used by businesses in their operation. Financial resources are all the sources of money available to the business. Human resources are people who work to produce goods or services. Natural resources are resources found in nature that are used to produce goods and services.', 'Strategic Management', 'Hospitality & Tourism', 1500, 'SM:001', 'Explain the concept of management', 'Hospitality District 2026 #41'),
  ('Which of the following is an example of an expense that a business would include in the cost of goods sold/cost of sales category of an income statement:', array['Insurance','Employee wages/salaries','Cost of raw materials','Mortgage or rent'], 2::smallint, 'Cost of raw materials. The cost of goods sold/cost of sales category of an income statement includes all direct costs to obtain or produce the goods or services that a business sells. This includes the cost of raw materials, shipping charges, labor costs, and items returned by customers, among others. The operating expenses do not cover the cost of goods sold/the cost of sales; rather, they cover all other expenses associated with the business. This includes employee wages/salaries, mortgage or rent, insura nce, utilities (natural gas, electricity, water, etc.), and interest paid on outstanding loans, to name a few.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:094', 'Describe the nature of income statements', 'Hospitality District 2026 #42'),
  ('Marketers add possession utility to products through', array['distribution.','personal selling.','development of new products.','delivery.'], 1::smallint, 'Personal selling. Possession utility is usefulness created when ownership of a product is transferred from the seller to the user. Salespeople add possession utility to products by by helping customers choose the right goods and services. Delivery and distribution affect place utility, and the development of new products affects form utility.', 'Economics', 'Hospitality & Tourism', 1500, 'EC:004', 'Determine economic utilities created by business activities', 'Hospitality District 2026 #43'),
  ('The goal of many governmental agencies is to protect the', array['target markets of large corporations.','monetary policy.','barriers to international trade.','rights of businesses and consumers.'], 3::smallint, 'Rights of businesses and consumers. Many governmental agencies are responsible for enforcing rules and regulations that are intended to protect the rights of businesses and customers. Some of these agencies help to keep the marketplace competitive and protect businesses'' trade secrets and formulas from being stolen. The agencies often develop a strong relationship with businesses in the process of protecting their rights. Governmental agencies do not typically protect the barriers to trade, the target marke ts of large corporations, or the monetary policy.', 'Business Law', 'Hospitality & Tourism', 1500, 'BL:072', 'Explain the nature of agency relationships', 'Hospitality District 2026 #44'),
  ('Operating costs that do not increase or decrease with changes in production are called __________ expenses.', array['mixed','variable','fixed','semi-variable'], 2::smallint, 'Fixed. Operating costs that do not increase or decrease with changes in production are called fixed expenses. Variable expenses fluctuate along with production. Semi-variable, or mixed, expenses are fixed until a certain level of production is reached; after that, they become variable.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:024', 'Explain the nature of overhead/operating costs', 'Hospitality District 2026 #45'),
  ('When Solange attends a national workshop, she likes to start a conversation with the person sitting next to her. Solange is exhibiting', array['verbal assertiveness.','empathy.','body language.','nosiness.'], 0::smallint, 'Verbal assertiveness. Verbal assertiveness is a confident attitude that involves the use of words. Some of the ways in which you can be verbally assertive include starting conversations, saying what you think, asking questions, requesting help, and refusing others'' requests. Nonverbal assertiveness is assertive behavior that does not involve words. It is often expressed through body language. Empathy is the ability to put yourself in another person''s situation. People can start conversations with others without asking prying questions that would indicate nosiness.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:008', 'Use appropriate assertiveness', 'Hospitality District 2026 #46'),
  ('Data encryption helps keep information safe and private by', array['requiring a password to access it.','storing it on a hard drive.','passing it through several servers.','translating it into a secret code.'], 3::smallint, 'Translating it into a secret code. Data encryption helps keep information safe and private by translating it into a secret code that can then be decoded by the intended receiver. Data encryption does not necessarily store information on a hard drive, pass it through several servers, or require a password for access.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:017', 'Explain the role of ethics in customer relationship management', 'Hospitality District 2026 #47'),
  ('Kent is going to start his own business. He is concerned that the merchandise he wants to carry will go out of style soon after opening his business. Which type of risk must he prepare for?', array['Natural','Economic','Human','Incompetence'], 1::smallint, 'Economic. Economic risks are changes in the market that force prices to be lowered, products to change, or even businesses to fail. Changes in the market that may make some products go out of style are a type of economic risk. Natural risks result from such natural causes as floods, tornadoes, fires, lightning, blizzards, and earthquakes. Human risks are caused by human weakness and the unpredictability of employees or customers. Incompetence is a form of human risk whereby the employee does not have the sk ills, knowledge, or attitudes needed to succeed in the position.', 'Economics', 'Hospitality & Tourism', 1500, 'EC:011', 'Determine factors affecting business risk', 'Hospitality District 2026 #48'),
  ('What can you do if you are unable to obtain the amount of financial support you need to complete the project?', array['Decrease time.','Cut costs.','Lower expectations.','Eliminate the project.'], 1::smallint, 'Cut costs. In some cases, the amount of money you think you will need will not be possible to obtain. When this happens, the most realistic approach is to look for ways to cut costs. If your ideal budget is based on getting everything you want or would like to have, consider substituting inexpensive materials for costly ones or making do without some supplies. By cutting costs, you will be able to proceed with the project. It is not necessary to lower your expectations because, in most cases, you will be able to complete the project by making some substitutions. Decreasing the amount of time that is allotted for the project will not necessarily make up for a lack of funding. Eliminating the project is not a good choice, either.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:003', 'Identify resources needed for project', 'Hospitality District 2026 #49'),
  ('Businesses operating in the global environment must be sensitive to different traditions, beliefs, and etiquette, which are __________ factors.', array['cultural','economic','political','intellectual'], 0::smallint, 'Cultural. Culture refers to the customs, habits, and traditions of a particular group of people. If businesses want to develop favorable relationships with foreign businesses, they need to recognize, understand, and respect other cultures. A business that does not learn about the cultural differences may do or say something to offend a foreign customer or potential customer. Political factors relate to government issues. Economic factors are ways that a nation meets consumers'' competing wants with limited resources. Intellect is a person''s cognitive ability.', 'Economics', 'Hospitality & Tourism', 1500, 'EC:104', 'Discuss the global environment in which businesses operate', 'Hospitality District 2026 #50'),
  ('One way to increase coupon redemption rates is to', array['offer digital coupons.','limit the expiration dates.','decrease the discount amount.','increase quantity of coupons.'], 0::smallint, 'Offer digital coupons. Digital coupons have a higher redemption rate than printed coupons because they are convenient and easily accessible. If a business wants to increase the effectiveness of its coupons, it should consider offering digital or mobile coupons. Decreasing the discount amount will not increase the use of coupons. Increasing the quantity of coupons could lead to over-couponing, which can tarnish brand value. Finally, limiting expiration dates would not necessarily lead to an increase in redem ption rates.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:149', 'Process complimentary offers and coupons/discounts', 'Hospitality District 2026 #51'),
  ('Which of the following businesses is the hospitality and tourism industry most likely to indirectly impact economically:', array['A design studio','A local produce farm','A drugstore chain','A used car dealership'], 1::smallint, 'A local produce farm. The hospitality and tourism industry has both direct and indirect impacts on the economy. It indirectly impacts other members of its supply chain, such as a local produce farm that provides the ingredients that a restaurant needs to serve customers. When the restaurant purchases produce, the produce farm receives an economic boost. A used car dealership, a drugstore chain, and a design studio are less likely to be economically impacted by the hospitality and tourism industry.', 'Economics', 'Hospitality & Tourism', 1500, 'EC:136', 'Explain the relationship between the economy and hospitality and tourism', 'Hospitality District 2026 #52'),
  ('What step in the Plan-Do-Check-Act (PDCA) continuous improvement technique involves analyzing the results of a small-scale change to determine if the change was effective?', array['Do','Act','Check','Plan'], 2::smallint, 'Check. The first step in the PDCA continuous improvement technique is planning a change. During the second step of the process, the business implements (does) the small-scale change. The third step involves checking the results to determine if the small-scale change was effective. If the change was successful, then the business takes action to implement the change on a larger scale.', 'Quality Management', 'Hospitality & Tourism', 1500, 'QM:003', 'Discuss the need for continuous improvement of the quality process', 'Hospitality District 2026 #53'),
  ('Corporate brands are built on all the associations and experiences', array['consumers have toward a business or product.','companies have about other industries.','consumers have about things they want to buy.','businesses have about and with each other.'], 0::smallint, 'Consumers have toward a business or product. The current meaning of "brand" is completely consumer focused and combines the consumers'' experiences, images, and associations regarding a company, good, or service. A brand is the relationship a company or product has with its customers. A brand is not built on how businesses view each other or other industries, nor is a brand about consumers'' views of things they want to buy.', 'Product/Service Management', 'Hospitality & Tourism', 1500, 'PM:206', 'Explain the nature of corporate branding', 'Hospitality District 2026 #54'),
  ('In an effort to pressure their employer to meet their demands, every employee stops working and leaves their office building. This describes a(n)', array['strike.','boycott.','arbitration.','mediation.'], 0::smallint, 'Strike. A strike is a union pressure strategy in which employees stop working and leave their jobs. Arbitration is the act of settling a dispute by using an uninvolved third party. Mediation is the process in which a neutral third party works to help opposing parties resolve a conflict. A boycott is a union pressure strategy in which union members refuse to buy a company''s products and encourage others to do the same.', 'Human Resources Management', 'Hospitality & Tourism', 1500, 'HR:452', 'Explain labor-relations issues', 'Hospitality District 2026 #55'),
  ('It is important for companies to practice enterprise risk management (ERM) because', array['most risks are predictable and manageable.','most risks are unexpected.','it increases business costs in the long run.','it leads to loss of shareholder value.'], 0::smallint, 'Most risks are predictable and manageable. Enterprise risk management is important and helpful because most business risks are predictable and manageable. If a company can plan for risks, it can minimize its losses. Although some risks are surprises, most of them are not. Not managing risks can cause loss of shareholder value. ERM should reduce business costs in the long run by helping a business avoid or manage risks that could lose money.', 'Risk Management', 'Hospitality & Tourism', 1500, 'RM:062', 'Discuss the nature of enterprise risk management (ERM)', 'Hospitality District 2026 #56'),
  ('Which of the following statements about technology''s impact on the tourism industry is true:', array['It allows customers to book hotels and flights more easily.','It makes it more difficult to conduct research before a trip.','It complicates the process of leaving a review.','It makes trip navigation more challenging.'], 0::smallint, 'It allows customers to book hotels and flights more easily. Mobile technology has drastically changed the tourism industry over the last two decades. Thanks to many hotels and airlines creating mobile apps, customers can book hotels and flights more easily. Mobile technology has made it easier for tourists to conduct research before a trip and to leave reviews, as they can do it on their cell phones and tablets. Thanks to apps like Google Maps, it is easier for tourists to navigate while on a trip.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:313', 'Describe the impact of mobile technology on the hospitality and tourism industry', 'Hospitality District 2026 #57'),
  ('Which of the following research activities would provide qualitative data about customers'' hotel amenity preferences:', array['Counting how many guests use each amenity daily','Interviewing hotel guests','Identifying which spa services are used most','Analyzing which webpages guests visit'], 1::smallint, 'Interviewing hotel guests. Interviews with guests are a way to capture in-depth, personalized information that is likely to be based on thoughts and feelings, not on numbers. Qualitative data are subjective information based on opinion and personal interpretations, not numbers. Analyzing webpages visited, tracking guests'' use of amenities, and identifying which spa services are used most are all research activities that would provide quantitative data based on numerical information.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:283', 'Describe methods used to collect hospitality and tourism business information (e.g.,', 'Hospitality District 2026 #58'),
  ('One of the benefits of obtaining selling information from company promotional materials is that the salesperson will be able to use that information to', array['satisfy managers'' requests.','answer customers'' questions.','discuss products with buyers.','order goods from vendors.'], 1::smallint, 'Answer customers'' questions. Salespeople often use the selling information they obtain from company promotional materials to answer customers'' questions. Company promotional materials, such as advertisements and brochures, usually contain valuable information that salespeople can use when customers ask questions during the selling process. Salespeople need to be well informed about the features and benefits of products because customers expect salespeople to be knowledgeable about the goods and services they sell. Salespeople usually do not order goods from vendors. Managers may suggest that salespeople read company promotional materials, which may make it easier for salespeople to discuss the products with buyers. However, these are not benefits of obtaining selling information from company promotional materials.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:062', 'Acquire product information for use in selling', 'Hospitality District 2026 #59'),
  ('A resort uses software to charge guests'' food, gift shop purchases, and other resort -related expenses to their accounts through their room key cards. This software increases the resort''s efficiency because it is', array['automated.','independent.','affordable.','complicated.'], 0::smallint, 'Automated. Automation is the use of technology to control a process. When a resort guest swipes their room key card to make a purchase, it transmits a transaction to the hotel''s software system, which adds the expense to the guest''s bill. Guests typically pay for their purchases when they check out of the resort. This software increases the hotel''s efficiency because it reduces paperwork by using a central bookkeeping system. The software is not independent. Whether the software is affordable or complicated does not impact how it increases the resort''s efficiency.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:106', 'Use software to automate services', 'Hospitality District 2026 #60'),
  ('Promotion in the travel and tourism industry is often intended to inform customers about', array['new advertising campaigns.','publicity and public relations.','new products and services.','contests and sweepstakes.'], 2::smallint, 'New products and services. The overall goal of promotion is to inform, persuade, and remind. In the travel and tourism industry, promotion is often intended to inform customers about new travel products and services. By informing potential customers, the industry is building awareness during the early stages of the buying process. If customers have been adequately informed, future promotions might persuade them to buy or remind them of positive experiences that will encourage them to buy again. The travel and tourism industry often uses contests, sweepstakes, advertising campaigns, publicity, and public relations as promotional tools.', 'Promotion', 'Hospitality & Tourism', 1500, 'PR:121', 'Describe the concept of promotion in the hospitality and tourism industry', 'Hospitality District 2026 #61'),
  ('One way businesses segment their markets is by studying', array['consumers'' characteristics.','mass marketing.','human relations.','their employees.'], 0::smallint, 'Consumers'' characteristics. To satisfy their customers, many businesses segment the whole market into smaller groups and focus their marketing efforts on a specific group. Consumer characteristics that they consider include age, occupation, gender, educational level, and life stage. Mass marketing is designing products and directing marketing activities to appeal to the whole market. A firm''s employees would not necessarily provide information about the target market. Studying human relations —all the ways people form and conduct relationships with one another—would not help a firm to segment its market.', 'Market Planning', 'Hospitality & Tourism', 1500, 'MP:003', 'Explain the concept of market and market identification', 'Hospitality District 2026 #62'),
  ('Cher, a front-desk clerk, listens carefully as a hotel guest explains a problem with their meal from room service. Cher also kindly repeats the guest''s concerns. What skill is Cher demonstrating?', array['Customer service','Patience','Oral presentation','Mirroring'], 0::smallint, 'Customer service. Customer service involves activities and benefits that a business and its employee provide to increase customer satisfaction and create goodwill. By listening and then repeating the customer''s issue back to them, Cher shows that the guest is important to her and that she wants to make things right for the guest. By doing so, she helps increase the guest''s satisfaction with their hotel stay and, more specifically, their meal. Mirroring occurs when someone unconsciously mimics another person''s body language, speech, or attitude. Patience is the ability to endure life''s aggravations and difficulties calmly. An oral presentation is a speech that brings an idea to someone''s attention.', 'Emotional Intelligence', 'Hospitality & Tourism', 1500, 'EI:090', 'Describe personal traits important to success in hospitality and tourism', 'Hospitality District 2026 #63'),
  ('Excellent customer service is crucial in the hospitality industry because the success of hospitality businesses often depends on the __________ of customers.', array['goodwill','capital','records','return'], 3::smallint, 'Return. Most businesses in the hospitality industry rely on repeat customers to be profitable. Poor customer service is the primary reason that customers do not return to a business, so it is important that every customer receive good service every time. Goodwill is either the kindness of customers—something a business cannot rely on to be profitable—or an intangible asset related to a company purchase. Capital is wealth and is not directly related to customer service. While some customers might review businesses in the hospitality industry, their personal records will not determine the success of a business.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:049', 'Explain the nature of customer service in the hospitality and tourism industry', 'Hospitality District 2026 #64'),
  ('To reconcile cash, which of the following should businesses do:', array['Total up the money in each of the company''s cash registers.','Multiply the cash received by the total number of receipts.','Compare cash received with receipts or transaction records.','Divide the transaction total by the amount of cash received.'], 2::smallint, 'Compare cash received with receipts or transaction records. To reconcile cash, a business should compare the total amount of cash received with the total on transaction records or receipts. For example, if a business wanted to reconcile its cash daily, it would count the amount of money in its cash registers and then look at all the sales receipts to make sure the numbers match. Reconciling cash does not involve any multiplication or division. Simply counting up the cash in cash registers would not be enough to reconcile a business''s cash for any given period.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:396', 'Reconcile cash', 'Hospitality District 2026 #65'),
  ('Employees should __________ to prevent identity theft.', array['have only one password','keep physical records','have a bad credit history','use secure web browsers'], 3::smallint, 'Use secure web browsers. Identity theft occurs when an individual obtains and uses another person''s information (e.g., credit cards) without that person''s consent. To reduce the risk of identity theft, people should use secure web browsers to make purchases. Because internet sales transactions often require a person to provide credit card information, it is important to make sure that the web browsers are secure. Physical records do not prevent identify theft; information kept on paper is also vulnerable to theft. It is recommended to use many unique passwords online, rather than one password. Having a bad credit history is a potential consequence of identity theft, not a preventative measure.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:654', 'Explain the nature of identity theft controls', 'Hospitality District 2026 #66'),
  ('A business can enhance its customer-service levels after the sales transaction has occurred by', array['offering training programs and providing technical support.','checking inventory status and advertising product specials.','arranging financing and suggestion selling.','providing product information and generating referrals.'], 0::smallint, 'Offering training programs and providing technical support. Providing quality customer service after the sale helps to reinforce the customer''s buying decision and often leads to repeat sales. Offering training programs and providing technical support are two ways in which a business can provide customer service after the sale. Arranging financing, suggestion selling, providing product information, checking inventory, and advertising are actions that businesses take before the sales transaction occurs. Generating referrals is a way for salespeople to increase their clientele rather than providing customer service after the sale.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:076', 'Explain the role of customer service as a component of selling relationships', 'Hospitality District 2026 #67'),
  ('Closing the sale is important because it provides the salesperson with an opportunity to', array['get the customer''s order.','determine the customer''s needs.','calculate daily sales earnings.','summarize the product''s features and benefits.'], 0::smallint, 'Get the customer''s order. Getting the order is one of the main reasons for closing the sale, because the ultimate goal of the selling process is to sell. Summarizing the product''s features and benefits should be done prior to the close. Determining the customer''s needs should be completed after approaching the customer. Calculating daily sales earnings is not a part of the selling process.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:048', 'Explain the selling process', 'Hospitality District 2026 #68'),
  ('During fire emergencies, all hotel employees need to', array['know emergency escape and route procedures.','activate the central sprinkler control system.','check all fire extinguishers for malfunctions.','keep portable smoke detectors with them at all times.'], 0::smallint, 'Know emergency escape and route procedures. Every hotel employee should know and understand escape and route procedures in the event of a fire. A fire can occur anywhere, so each employee should be familiar with escape routes and alternate escape routes in all areas of the hotel. Understanding and following the procedures, if possible, helps to lessen chaos and increases the chance to get everyone out of harm''s way in a safe manner. Most emergency plans specify certain employees to conduct certain activities during the evacuation. For example, one group of employees might make sure guests are alerted to evacuate. Others might need to follow procedures to protect hotel documents such as guest folios. During a fire emergency, a hotel''s sprinkler system should activate automatically. If the sprinkler system malfunctions, all employees should know how to activate the system. However, it is not necessary for all employees to activate the system during the actual fire. Generally, the person closest to the system would activate any backup system on the property. Fire extinguishers are not checked for malfunctions during a fire emergency. They are evaluated by qualified inspectors during nonemergency times. Hotels are often required to keep smoke detectors throughout the facility, including in each sleeping and meeting room. Therefore, employees do not usually carry portable smoke detectors.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:119', 'Handle emergency situations in hospitality and tourism', 'Hospitality District 2026 #69'),
  ('As competition in the hospitality industry increases, many businesses are shifting their promotional focus to build and maintain customer loyalty. This is most effectively achieved by highlighting', array['price and discounts.','service and product.','technology and automation.','location and amenities.'], 1::smallint, 'Service and product. As competition in the hospitality industry increases, many businesses are focusing on maintaining long-term customer loyalty. The best way to build this loyalty is to focus on providing excellent service, which includes the actions and care provided by staff, and a high-quality product, which includes physical aspects like the room, food, and amenities. These two elements create a positive customer experience, which in turn leads to long-term customer loyalty. Technology is a tool used to enhance the guest experience and improve efficiency. While a business may promote its use of technology, the ultimate goal is to highlight the improved service it provides. Customers expect a great location and worthwhile amenities; the quality of the service and experience make them return. Customers who only come for the lowest price often leave when they find a cheaper option; discounts don''t necessarily keep customers loyal.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:048', 'Describe current issues and trends in the hospitality and tourism industry', 'Hospitality District 2026 #70'),
  ('The details regarding quotas for each salesperson would be outlined in what type of selling policy?', array['Service','Qualifying the customer','Terms-of-sale','Selling-activity'], 3::smallint, 'Selling-activity. The details regarding quotas for each salesperson would be outlined in a selling -activity policy. Selling-activity policies involve salespeople''s interactions with customers. Terms -of-sale policies involve the parts of the sale that concern customers most (e.g., pricing, discounts). Service policies involve what happens after the sale. Qualifying the customer is another selling-activity policy that involves ensuring that a customer is right for the purchase.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:932', 'Explain company selling policies', 'Hospitality District 2026 #71'),
  ('Which promotional medium would be most appropriate for a low profit-margin product?', array['Novels','Email','Magazine','TV'], 1::smallint, 'Email. Email marketing is very inexpensive relative to other mediums such as TV and magazine print. For products with a low profit margin, seeking cheap methods for marketing is ideal. Novels are not used for product promotion.', 'Pricing', 'Hospitality & Tourism', 1500, 'PI:001', 'Explain the nature and scope of the pricing function', 'Hospitality District 2026 #72'),
  ('When providing first aid, what should you do first?', array['Check the person for responsiveness.','Give care based on the condition found.','Check the scene for safety.','Ask questions about symptoms.'], 2::smallint, 'Check the scene for safety. Checking the scene for safety, obtaining consent, forming an initial impression, and using any personal protective equipment (PPE) as needed must happen before any following first aid steps. Otherwise, you might hurt yourself or do more harm than good. Checking the person for responsiveness, giving care based on the condition found, and asking questions about signs and symptoms are steps involved in providing first aid, but they should be completed after checking that the scene is safe.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:657', 'Provide first-aid', 'Hospitality District 2026 #73'),
  ('Mia is very organized and detail-oriented and enjoys helping others arrange activities such as fundraisers, receptions, and meetings. Based on her skills and interests, Mia might consider working in the hospitality industry as a(n)', array['accounting manager.','restaurant chef.','event planner.','purchasing agent.'], 2::smallint, 'Event planner. Convention centers, hotels, restaurants, and other types of businesses hire and employ event planners to coordinate many types of events including fundraisers, wedding receptions, trade shows, and business meetings. To ensure that their clients have everything they need for successful events, event planners should be organized and detail-oriented. A restaurant chef develops the menu, prepares entrees, and manages the kitchen staff. A purchasing agent locates, negotiates, and buys goods and services for the business. An accounting manager supervises the accounting function''s staff and activities.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:272', 'Explain career opportunities in hospitality and tourism', 'Hospitality District 2026 #74'),
  ('The stage of brand loyalty in which consumers will buy another brand if the brand they like is not available is called brand', array['preference.','insistence.','recognition.','awareness.'], 0::smallint, 'Preference. At this stage of brand loyalty, consumers recognize the brand, are aware of its existence, have purchased it, and are satisfied with the brand. However, they have not yet reached the stage of brand insistence because they will still accept a substitute for the brand they prefer and recognize.', 'Product/Service Management', 'Hospitality & Tourism', 1500, 'PM:021', 'Explain the nature of product/service branding', 'Hospitality District 2026 #75'),
  ('Amare works as a customer service associate at a hotel. He is approached by a customer who complains that their room has not been cleaned thoroughly prior to their arrival. The customer wants a new room, but Amare knows the hotel has been completely booked for an upcoming wedding. What is the best way for Amare to respond to this customer''s complaint?', array['He should provide an alternative solution to this customer''s complaint.','He should inspect the room to see for himself whether it is truly dirty.','He should apologize profusely and reprimand the cleaning staff.','He should explain in detail why he cannot accommodate the request.'], 0::smallint, 'He should provide an alternative solution to this customer''s complaint. When an employee receives a customer complaint, they should focus on how they can help the customer, not how they can''t. While Amare could not offer a new room, because the hotel had been completely booked, he could potentially have offered some other complimentary amenity to the customer as their room was being cleaned. Explaining in detail why he could not accommodate the request, inspecting the room, or reprimanding the staff would not help the customer and could potentially only exacerbate the issue.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:044', 'Resolve hospitality and tourism related conflicts for customers', 'Hospitality District 2026 #76'),
  ('Which of the following factors should be considered by hotels planning evacuation protocols:', array['The average income of customers','Hotel price and ratings','Local transportation services','Hotel employee satisfaction'], 2::smallint, 'Local transportation services. When planning evacuation protocols, hotels should consider the availability of local transportation services to determine how evacuees will be removed from the premises. Hotel price and ratings, hotel employee satisfaction, and the average income of customers are not relevant factors to consider when planning an evacuation protocol.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:527', 'Identify factors affecting evacuation procedures/protocols', 'Hospitality District 2026 #77'),
  ('An airline executive wants to know why sales are dropping. They are most likely to need to conduct primary research if', array['they have not conducted secondary research yet.','they have already exhausted their secondary research options.','the airline has little money for research.','no one on their team has the information they need.'], 1::smallint, 'They have already exhausted their secondary research options. Primary research is that which a person or company generates on their own for their exact needs and purposes. Primary research is generally done when the needed information does not exist yet. Therefore, the airline executive should first do an exhaustive search of secondary sources before deciding to conduct primary research. Even if no one on the executive''s team has the information they need, the executive still might not need to conduct prima ry research because they might be able to use secondary research. If the airline has little money for research, the executive might be better off focusing on secondary research because it is cheaper than primary research.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:282', 'Explain types of primary hospitality and tourism market information', 'Hospitality District 2026 #78'),
  ('What is the best, least costly technique for an event management company to use to encourage recycling at an event?', array['Hire a waste management company to clean up the venue.','Purchase paper goods that do not need to be recycled.','Require attendees to turn in solid waste following the event.','Place recycling bins throughout the venue.'], 3::smallint, 'Place recycling bins throughout the venue. Many universities and businesses use large, green recycling bins to encourage event goers to participate in recycling efforts. It''s not feasible to require attendees to turn in solid waste following an event. Some attendees would, but others would resist being told what to do. Hiring a waste management company is a good technique to use; however, it''s more costly than providing recycling bins. Purchasing paper products that don''t need to be recycled defeats the whole purpose of encouraging recycling efforts.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:134', 'Practice safe and sanitary handling/disposal of wastes/recyclables', 'Hospitality District 2026 #79'),
  ('Jorge manages a bakery with five types of products: breads, muffins, cookies, quiches, and desserts. He wants to know how each type of product contributed to last year''s sales in relation to the others. So, he creates a graph with sections sized proportionally to the quantity they represent to show a part-to-whole relationship. What type of chart did Jorge create?', array['Scatter plot','Bar chart','Line graph','Pie chart'], 3::smallint, 'Pie chart. A pie chart is a circular graph that is divided into sections sized proportionally to the quantity they represent. Pie charts are best used to show a part-to-whole relationship; in this case, Jorge''s chart was showing how the sales from each type of product made up last year''s total sales. A bar chart presents categorical data with proportional rectangle bars. A line graph connects a series of data points. A scatter plot uses dots to represent values for two different variables.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:289', 'Display hospitality and tourism data in charts/graphs or in tables', 'Hospitality District 2026 #80'),
  ('John''s office recently ran out of printer paper. As the employee in charge of ordering office supplies, John called up the paper supplier and asked them to send the office 100 reams of paper. When the order arrived a few days later, however, John noticed that his company only received 80 reams instead of 100. When he called the supplier to complain, the agent argued that John asked for 80 reams--even though John knows he asked for 100. What could John have done to prevent this miscommunication?', array['Completed a purchase order','Asked for a smaller quantity','Requested the order the same day','Sent the company an invoice'], 0::smallint, 'Completed a purchase order. A purchase order is a formal, written request for a product or service. Purchase orders generally include all of the specifications of the order, such as the amount of product requested, the price of the products requested, and the contact information for both buyer and seller. Completing a purchase order would have prevented this miscommunication between John''s office and the paper supplier. John should not have sent an invoice to the paper supplier. Invoices are sent to busines ses that owe money for purchases they already made. Asking for a smaller quantity or requesting the order the same day would not necessarily have reduced the chance of miscommunication between John and the paper supplier.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:250', 'Describe types of purchase orders', 'Hospitality District 2026 #81'),
  ('What is the typical effect of an economic slowdown on the hospitality industry?', array['An increase in the number of guests and a decrease in the number of rooms available','A decrease in the number of guests and a decrease in the number of rooms available','A decrease in the number of guests and an increase in the number of rooms available','An increase in the number of guests and an increase in the number of rooms available'], 2::smallint, 'A decrease in the number of guests and an increase in the number of rooms available. A decrease in the number of guests occurs during economic slowdowns because people are reluctant to spend their discretionary income on travel. Consequently, there is an increase in the number of rooms available as more rooms become available for rent. An increase in the number of guests and an increase in the number of rooms available does not follow the law of supply and demand, which suggests that as demand for rooms go up, supply typically goes down. A decrease in the number of guests and a decrease in the number of rooms available would work the other way because as demand goes down, the supply of rooms available for rent typically goes up. An increase in the number of guests and a decrease in the number of rooms available typically occurs during good economic times when people are more willing to spend their discretionary income on travel.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:111', 'Describe the nature of the hospitality and tourism industry', 'Hospitality District 2026 #82'),
  ('Which of the following is a benefit customers receive from product bundling:', array['Increased revenue','Access to unpopular products','Improved workflow','Convenience'], 3::smallint, 'Convenience. Product bundling is when two products are sold together as one item or purchase. It is convenient for customers because they have fewer separate purchases to make and can obtain several items that they need at once. Product bundling can increase revenue for businesses rather than for customers. Access to unpopular products is not a benefit for customers. Improved workflow is a benefit for business rather than for customers.', 'Product/Service Management', 'Hospitality & Tourism', 1500, 'PM:041', 'Describe the nature of product bundling', 'Hospitality District 2026 #83'),
  ('Which of the following questions would be part of product/service management:', array['Which training method works best for employees?','How will we communicate a positive image to our clients?','Is the item packaged appropriately?','What type of insurance should we purchase?'], 2::smallint, 'Is the item packaged appropriately? Product/Service management is the process of obtaining, developing, maintaining, and improving a product or service mix in response to market opportunities. It includes all activities from the time of a product''s creation to the time of its removal from the company''s line of products. Choosing the appropriate packaging for the item is one of those activities. Purchasing insurance is not a function of product/service management. The choice of training method is a management decision. How a business communicates to outsiders is a function of promotion.', 'Product/Service Management', 'Hospitality & Tourism', 1500, 'PM:001', 'Explain the nature and scope of the product/service management function', 'Hospitality District 2026 #84'),
  ('What is a likely result of accommodating a customer''s special request?', array['Other customers will feel they are not being treated fairly.','The customer will generate word-of-mouth influence.','The company will be perceived as inadequate.','The customer will become even more demanding.'], 1::smallint, 'The customer will generate word-of-mouth influence. When customers request special treatment, honoring their requests will create an exceptional experience for them. They will be much more likely to provide positive word - of-mouth feedback to other potential customers. It is not likely that other customers will feel that they are not being treated fairly, that the customer will become even more demanding, or that the company will be perceived as inadequate.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:054', 'Accommodate special needs/specific requests of customers', 'Hospitality District 2026 #85'),
  ('Ms. Woo is staying at a hotel that is across the street from the office of the client with whom she plans to meet. Which of the following factors most likely motivated Ms. Woo to select the hotel:', array['Desire for convenience','Desire for safety','Need for relaxation','Need for prestige'], 0::smallint, 'Desire for convenience. Travelers select certain lodging facilities for many reasons or for a combination of reasons. Ms. Woo staying in a hotel across the street from her client''s office implies that one reason Ms. Woo selected the hotel was for the convenience of being near the office where she was planning to attend a business meeting. Because there is not enough information revealed about the location or Ms. Woo, it cannot be determined whether additional factors for her selection included relaxation, safety, or prestige.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:220', 'Explain factors that motivate people to choose a hospitality and tourism site', 'Hospitality District 2026 #86'),
  ('To prevent sensitive customer data from being stolen by hackers, companies should', array['ask customers to sign a waiver in case their information is stolen.','refuse to accept credit or debit cards from customers.','prohibit workers from accessing customer information.','require that employees follow good password practices.'], 3::smallint, 'Require that employees follow good password practices. Good password practices, such as changing your password frequently and using a password that is at least 12 characters long, can help companies protect customer data from hackers. Companies do not need to prohibit workers from accessing customer information; however, it might be wise to limit access to those who need it for their everyday work. Asking customers to sign a waiver in case their information is stolen would be inappropriate and would likely drive customers away. Refusing to accept credit or debit cards might help prevent hackers from targeting the company, but it may be financially unrealistic to be a cash-only business.', 'Operations', 'Hospitality & Tourism', 1500, 'OP:518', 'Comply with strategies to protect digital customer data (e.g., information about customers,', 'Hospitality District 2026 #87'),
  ('According to Continental Eatery''s menu, its salmon is flown in directly from Alaska every day. However, the salmon is actually purchased from a local grocery store once a week. What type of law is the restaurant potentially violating?', array['Affinity fraud','Truth-in-menu','Petty theft','Insider trading'], 1::smallint, 'Truth-in-menu. Truth-in-menu laws are designed to protect consumers by mandating that restaurants'' menus accurately describe the food that restaurants serve to their guests. Insider trading laws prevent a company''s owners, directors, or key management from trading company stock if they are making those trades on information that is not disclosed to the public. Petty theft, also known as pilferage, involves the theft of small sums of money or inexpensive items. Affinity fraud is an investment scam in which the scammer claims to be a member of the group they are targeting.', 'Business Law', 'Hospitality & Tourism', 1500, 'BL:065', 'Explain the nature of regulations affecting the hospitality and tourism industry', 'Hospitality District 2026 #88'),
  ('Which of the following is an example of how databases help improve customer satisfaction:', array['Management can determine inventory remotely.','A variety of services can be integrated into one system.','Hotels can customize guest room preferences.','Restaurants receive customer feedback from social media.'], 2::smallint, 'Hotels can customize guest room preferences. A customer database allows hotels to gather guest information and preferences so they can personalize the guests'' experiences. For example, if a customer purchases several soft drinks from room service, the hotel can store that information in a database and then prepare the room by stocking the mini fridge with the same soft drink upon the customer''s return. While restaurants can use social media to receive feedback, they are not necessarily using a database to i mprove customer satisfaction when they do so. A variety of services can be integrated into one system, but this does not necessarily depend on a database; rather, it is due to hotel and restaurant management system software. Finally, while technology such as washable chips allows management to determine inventory remotely, this is also not an example of how databases help improve customer satisfaction.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:060', 'Explain ways that technology impacts the hospitality and tourism industry', 'Hospitality District 2026 #89'),
  ('Benjamin, a human resources manager, is in charge of screening and interviewing potential employees for his company. Screening and interviewing are important components of which managerial function?', array['Staffing','Planning','Directing','Organizing'], 0::smallint, 'Staffing. Staffing is the management function of finding, training, and compensating workers for the business. Most often, human resources managers are the primary staffers within a company. Planning is the management function of deciding what will be done and how it will be accomplished. Directing is the management function of providing guidance to workers and work projects. Organizing is the management function of setting up the way the business''s work will be done.', 'Strategic Management', 'Hospitality & Tourism', 1500, 'SM:065', 'Describe managerial considerations in staffing', 'Hospitality District 2026 #90'),
  ('The executives of an airline recently determined that the cost of their extensive employee training program was too high and decided to terminate the program. What is a possible consequence of this decision?', array['Decreased quality of customer service','Increased number of repeat customers','Reduced focus on productivity by management','Stronger financial standing'], 0::smallint, 'Decreased quality of customer service. The costs of customer service training programs are a challenge for the hospitality and tourism industry, especially with high turnover rates. However, training is essential to customer service, and without it, quality is sure to suffer. Terminating a customer service training program is not likely to lead to an increased number of repeat customers or a stronger financial standing. Although the training program has been terminated, management will not reduce its produc tivity focus.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:043', 'Describe customer-service challenges in the hospitality and tourism industry', 'Hospitality District 2026 #91'),
  ('Which of the following businesses is most likely to provide services that directly relate to the guests'' desire for rest and relaxation:', array['Wild and Wacky Amusement Park','Whispering Hills Resort and Spa','Metropolis Bureau of Travel and Tourism','Rugged River Whitewater Rafting Company'], 1::smallint, 'Whispering Hills Resort and Spa. The resort''s lodging facilities provide sleeping accommodations, which satisfies the guests'' desire for rest, while the spa services (e.g., massages and facials) satisfy the guests'' desire for relaxation. The Wild and Wacky Amusement Park and the Rugged River Whitewater Rafting Company provide services that are adventure oriented. The Metropolis Bureau of Travel and Tourism promotes tourism for the city and helps individuals and businesses identify resources that they might want and need during their visit.', 'Product/Service Management', 'Hospitality & Tourism', 1500, 'PM:095', 'Describe services offered by the hospitality and tourism industry', 'Hospitality District 2026 #92'),
  ('Which of the following is subtracted from operating cash flow to find free cash flow:', array['Capital expenditures','Dividends','Earnings','Acquisitions'], 0::smallint, 'Capital expenditures. Free cash flow is a measure of a company''s performance. It is calculated by subtracting capital expenditures from operating cash flow. Capital expenditures include equipment, buildings, and other property. You do not need to subtract dividends, acquisitions, or earnings to find free cash flow.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:541', 'Interpret cash-flow statements', 'Hospitality District 2026 #93'),
  ('At the end of each day, Bob, owner of Bob''s Barbecue, deposits the restaurant''s cash in the bank. Laura, a manager at Bob''s Barbecue, keeps track of the restaurant''s accounting journals. This separation of duties is an example of a(n)', array['bank reconciliation.','petty cash fund.','internal control.','external control.'], 2::smallint, 'Internal control. Internal accounting controls are policies and procedures that are created and enforced to ensure the reliability of accounting systems. Examples of internal controls include separations of duties, access control/authorization, documentation, physical audits, trial balances, reconciliations, and approval authority. Separation of duties is the dividing of accounting responsibilities so that no one person oversees the lifespan of a single financial transaction. By separating the duties that pertain to Bob''s Barbecue''s finances, Bob is safeguarding his restaurant from theft, fraud, and other financial issues. A petty cash fund is a small amount of money kept on hand by a business for business purchases. A bank reconciliation is a comparison of a business''s internal accounting records to its bank account statements. External controls also impact business operations, but the source of these controls is outside the business, rather than in.', 'Financial Analysis', 'Hospitality & Tourism', 1500, 'FI:113', 'Explain cash control procedures (e.g., signature cards, deposit slips, internal/external', 'Hospitality District 2026 #94'),
  ('Under which of the following circumstances might a chain of quick-serve restaurants decide to eliminate a certain food item from its product mix:', array['Product''s reputation is positive.','Product''s sales are in decline.','Product complements other products.','Product is similar to competitors'' products.'], 1::smallint, 'Product''s sales are in decline. When a product''s sales and profits decline, the product is considered to be weak. Such a product can become a financial burden to the quick-serve restaurant and have a negative impact on the restaurant''s image. A chain of quick-serve restaurants might decide to eliminate a certain food item, such as corn dogs, if the item was not popular with customers and was not selling well. A quick -serve restaurant would not eliminate a food item if it complemented other products and had a positive reputation. Many quick-serve restaurants sell food items that are similar to the ones sold by their competitors.', 'Product/Service Management', 'Hospitality & Tourism', 1500, 'PM:003', 'Explain the concept of product mix', 'Hospitality District 2026 #95'),
  ('Which of the following agencies is most likely to impact the hospitality and tourism industry on an international scale:', array['Florida Restaurant & Lodging Association (FRLA)','World Tourism Organization (UNWTO)','UKHospitality','American Hotel & Lodging Association (AHLA)'], 1::smallint, 'World Tourism Organization (UNWTO). There are many hospitality and tourism organizations across the world. Some deal with local hospitality and tourism, while others deal with this industry on a much greater scale. The World Tourism Organization is the United Nations agency responsible for global tourism initiatives and is most likely to impact hospitality and tourism on an international scale. The American Hotel & Lodging Association, UKHospitality, and Florida Restaurant & Lodging Association all handle hospitality and tourism on a smaller scale.', 'Professional Development', 'Hospitality & Tourism', 1500, 'PD:398', 'Explain the roles and responsibilities of hospitality and tourism organizations', 'Hospitality District 2026 #96'),
  ('Which of the following statements about guest recovery is true:', array['Companies should not keep records of their customer feedback.','It is important to wait a day to respond to a customer.','Companies should avoid implementing a customer response process.','Communication is vital to the recovery process.'], 3::smallint, 'Communication is vital to the recovery process. Guest recovery refers to the steps a company takes to address or correct a customer''s complaints. When it comes to addressing a customer''s complaints, communication is vital to the recovery process. Without proper communication, important information from either side may fall through the cracks or the customer may not feel they are being heard. Companies should prioritize establishing a response process for customer complaints. A response process can serve as a blueprint for staff members for handling customer feedback. Without this process, customers will experience varied levels of responses and response times. Rather than wait a day to respond to a customer, companies should try to respond as soon as possible. Companies should keep records of their customer feedback. Tracking customer feedback can help companies analyze their processes and improve where needed.', 'Customer Relations', 'Hospitality & Tourism', 1500, 'CR:045', 'Explain the nature of guest recovery', 'Hospitality District 2026 #97'),
  ('Selling is often referred to as personal selling because it', array['provides specific product information.','involves interaction with customers.','can take place in the customer''s home.','follows a standardized format.'], 1::smallint, 'Involves interaction with customers. Selling is referred to as personal selling because salespeople interact with their customers and try to meet their individual needs. Providing specific product information is one of the ways salespeople meet those needs. Selling seldom follows a standardized format except in situations such as telemarketing. Personal selling can take place in a variety of places, including the home, but it is the interaction with customers that gives it its name.', 'Selling', 'Hospitality & Tourism', 1500, 'SE:017', 'Explain the nature and scope of the selling function', 'Hospitality District 2026 #98'),
  ('To make it easier to find specific information in a business report, you should include a(n)', array['introduction.','title page.','appendix.','table of contents.'], 3::smallint, 'Table of contents. When preparing a business report, it is often a good idea to include a table of contents, the portion of a document in which the sections are listed with their page numbers for easy navigation. This allows a reader to sift through a lengthy document to find the needed information. While title pages, introductions, and appendices are also helpful in a written business report, their main purposes are not to make it easier to find specific information.', 'Information Management', 'Hospitality & Tourism', 1500, 'NF:292', 'Prepare written reports for hospitality and tourism decision-making', 'Hospitality District 2026 #99'),
  ('A hotel that buys advertising space on a travel agency''s website is using this form of promotion to', array['recruit new employees.','obtain publicity.','attract potential guests.','obtain an agency rating.'], 2::smallint, 'Attract potential guests. Hotel advertising on websites is intended to catch the attention of people making travel plans and prompt them to make reservations at the hotel. Buying advertising is not a method of obtaining publicity or a rating from a travel agency. A website ad is not an appropriate channel for recruiting new employees.', 'Promotion', 'Hospitality & Tourism', 1500, 'PR:082', 'Explain promotional methods used by the hospitality and tourism industry', 'Hospitality District 2026 #100')
) as v(question_text, choices, correct_index, explanation, kpi_area, cluster,
              difficulty_rating, pi_code, pi_text, source_exam)
where not exists (
  select 1 from public.questions existing where existing.question_text = v.question_text
);
